class _BundledModuleLoader(_bundle_importlib_abc.MetaPathFinder, _bundle_importlib_abc.Loader):
    def find_spec(self, fullname: str, path: Any = None, target: Any = None) -> Any:
        if fullname not in _BUNDLED_MODULE_PAYLOADS:
            return None
        return _bundle_importlib_util.spec_from_loader(
            fullname, self, is_package=fullname in _BUNDLED_PACKAGES
        )

    def create_module(self, spec: Any) -> Any:
        return None

    def exec_module(self, module: Any) -> None:
        module_name = module.__name__
        encoded = "".join(_BUNDLED_MODULE_PAYLOADS[module_name])
        source = _bundle_zlib.decompress(
            _bundle_base64.b85decode(encoded.encode("ascii"))
        ).decode("utf-8")
        module.__file__ = _BUNDLED_ROOT_FILE
        module.__package__ = module_name if module_name in _BUNDLED_PACKAGES else module_name.rpartition(".")[0]
        if module_name in _BUNDLED_PACKAGES:
            module.__path__ = []
        exec(compile(source, f"{_BUNDLED_ROOT_FILE}::{module_name}", "exec"), module.__dict__)

_BUNDLED_MODULE_LOADER = _BundledModuleLoader()
_bundle_sys.meta_path.insert(0, _BUNDLED_MODULE_LOADER)

