def _audit_only_conflict_execution_threshold(
    candidate_quality: float,
    conflict: Optional[dict[str, Any]] = None,
) -> float:
    """Offline replay diagnostic for the retired adaptive-conflict override.

    This helper is intentionally excluded from live Executive decisions. It exists
    only so ``--audit-journal`` can reproduce historical investigations without
    placing a misleading score override in the production path.
    """
    conflict = conflict or {}
    severity = max(
        0.0,
        -safe_float(conflict.get("market_score"), 0.0),
        -safe_float(conflict.get("execution_score"), 0.0),
    )
    quality_credit = clamp((safe_float(candidate_quality, 0.0) - RISKY_ENTRY_SCORE_BASE) / 3.0, 0.0, 2.0)
    threshold = CONFLICT_OVERRIDE_EXECUTION_BASE + min(4.0, severity * 0.35) - quality_credit
    return round(clamp(threshold, CONFLICT_OVERRIDE_EXECUTION_MIN, CONFLICT_OVERRIDE_EXECUTION_MAX), 2)


def _audit_only_conflict_allows_reduced_entry(
    execution_quality: float,
    risk_blocked: bool,
    rr1: float,
    minimum_execution_quality: Optional[float] = None,
) -> bool:
    """Offline-only predicate used by historical conflict-scale replay.

    Live PROBE/ENTRY decisions never call this function. Production conflict handling
    is performed by staged evidence, Trading Philosophy and the Executive contract.
    """
    required = (
        CONFLICT_OVERRIDE_EXECUTION_BASE
        if minimum_execution_quality is None
        else float(minimum_execution_quality)
    )
    return (
        float(execution_quality or 0) >= required
        and not bool(risk_blocked)
        and float(rr1 or 0) >= MIN_RR1
    )


# ==========================================================
# UTILITIES
# ==========================================================

def now_utc() -> datetime:
    return datetime.now(timezone.utc)


def iso_now() -> str:
    return now_utc().isoformat()


def safe_float(value: Any, default: float = 0.0) -> float:
    try:
        if value is None or value == "":
            return default
        result = float(value)
        return result if math.isfinite(result) else default
    except Exception:
        return default


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def round_price(value: Any) -> float:
    value = safe_float(value)
    if abs(value) >= 100:
        return round(value, 3)
    if abs(value) >= 10:
        return round(value, 4)
    return round(value, 5)


def pct(new: float, old: float) -> float:
    return ((new - old) / old * 100.0) if old else 0.0


def side_sign(side: str) -> int:
    return 1 if side == Side.LONG.value else -1


def opposite(side: str) -> str:
    return Side.SHORT.value if side == Side.LONG.value else Side.LONG.value


def json_safe(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, datetime):
        return value.isoformat()
    if hasattr(value, "__dataclass_fields__"):
        return json_safe(asdict(value))
    if isinstance(value, dict):
        return {str(k): json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [json_safe(v) for v in value]
    return str(value)


def classify_trade_result(result_r: Any = None, pnl_pct: Any = None, outcome_status: str = "") -> str:
    """Classify economic outcome independently from the mechanical close action."""
    value = None
    for raw in (result_r, pnl_pct):
        try:
            if raw is not None and raw != "":
                candidate = float(raw)
                if math.isfinite(candidate):
                    value = candidate
                    break
        except Exception:
            continue
    if value is None:
        return "UNRESOLVED" if str(outcome_status or "").upper() not in {"RESOLVED", "CLOSED"} else "BREAKEVEN"
    if value > 1e-9:
        return "WIN"
    if value < -1e-9:
        return "LOSS"
    return "BREAKEVEN"


def _tracked_setup_types() -> tuple[str, ...]:
    """Canonical list of the 24 real setup types; NONE is a domain sentinel."""
    return tuple(item.value for item in SetupType if item.value != SetupType.NONE.value)


def _setup_lifecycle_event_key(event: dict[str, Any]) -> tuple[str, str, str]:
    return (
        str(event.get("side") or "NEUTRAL"),
        str(event.get("setup_type") or SetupType.NONE.value),
        str(event.get("model_id") or event.get("ict_model") or "UNKNOWN"),
    )


def _ensure_setup_episode_identity_schema(ledger: dict[str, Any]) -> dict[str, Any]:
    """Reset only derived independent-episode counters when identity changes.

    Raw scan counters, recent runs, trades and signals remain untouched. The old
    registry is summarized in a bounded migration archive because its ranked and
    selected stages may have used different keys and therefore cannot be merged
    without inventing history.
    """
    policy = dict(ledger.get("independent_episode_policy") or {})
    current_schema = str(policy.get("schema_version") or "")
    derived_keys = (
        "episode_registry", "active_trade_shadow_episode_registry",
        "independent_episode_totals", "active_trade_shadow_independent_episode_totals",
        "independent_episode_conversion", "live_independent_episode_conversion",
        "shadow_independent_episode_conversion",
    )
    has_derived = any(bool(ledger.get(key)) for key in derived_keys)
    if current_schema == SETUP_EPISODE_SCHEMA_VERSION:
        return {"changed": False, "schema_version": SETUP_EPISODE_SCHEMA_VERSION}

    if has_derived or current_schema:
        archive = {
            "migrated_at": iso_now(),
            "from_schema": current_schema or "LEGACY_OR_UNKNOWN",
            "to_schema": SETUP_EPISODE_SCHEMA_VERSION,
            "live_registry_size": len(ledger.get("episode_registry") or {}),
            "shadow_registry_size": len(ledger.get("active_trade_shadow_episode_registry") or {}),
            "live_totals": json_safe(ledger.get("independent_episode_totals") or {}),
            "shadow_totals": json_safe(ledger.get("active_trade_shadow_independent_episode_totals") or {}),
            "reason": "RANKED_AND_SELECTED_STAGE_KEYS_WERE_NOT_CANONICALLY_IDENTICAL",
            "raw_scan_counters_preserved": True,
        }
        archives = ledger.setdefault("episode_identity_schema_migrations", [])
        archives.append(archive)
        del archives[:-10]

    for key in derived_keys:
        ledger.pop(key, None)
    ledger["independent_episode_policy"] = {
        "identity": "CANONICAL_RANKED_EPISODE_KEY_PROPAGATED_TO_ALL_STAGES",
        "anchor_bucket_atr": SETUP_EPISODE_ANCHOR_BUCKET_ATR,
        "time_bucket_minutes": SETUP_EPISODE_TIME_BUCKET_MINUTES,
        "raw_scan_counters_preserved": True,
        "schema_version": SETUP_EPISODE_SCHEMA_VERSION,
    }
    return {
        "changed": True,
        "from_schema": current_schema or "LEGACY_OR_UNKNOWN",
        "schema_version": SETUP_EPISODE_SCHEMA_VERSION,
        "archived_derived_registry": bool(has_derived),
    }


def migrate_setup_episode_identity_schema(journal: dict[str, Any]) -> dict[str, Any]:
    ledger = journal.setdefault("setup_lifecycle_counters", {})
    report = _ensure_setup_episode_identity_schema(ledger)
    report["completed_at"] = iso_now()
    previous = journal.get("setup_episode_identity_migration")
    if report.get("changed") or not isinstance(previous, dict):
        journal["setup_episode_identity_migration"] = dict(report)
    else:
        previous["last_checked_at"] = report["completed_at"]
        previous["current_schema"] = SETUP_EPISODE_SCHEMA_VERSION
    return report


def migrate_predicate_reachability_schema(journal: dict[str, Any]) -> dict[str, Any]:
    """Separate dependency-aware observations from legacy mixed counters.

    Lifetime evaluated/fired/blocker totals remain available. Only predicate
    truth, applicability, margins and current-schema health are reset because
    old FALSE rows cannot be distinguished from what should now be N/A.
    """
    ledger = journal.setdefault("setup_lifecycle_counters", {})
    rows = ledger.setdefault("detector_reachability", {})
    changed = 0
    for setup_type, row in list(rows.items()):
        if not isinstance(row, dict):
            continue
        current_schema = str(row.get("predicate_schema_version") or "")
        if current_schema == DETECTOR_REACHABILITY_SCHEMA_VERSION:
            continue
        legacy_snapshot = {
            "migrated_at": iso_now(),
            "from_schema": current_schema or str((row.get("last_observation") or {}).get("schema_version") or "LEGACY_MIXED"),
            "to_schema": DETECTOR_REACHABILITY_SCHEMA_VERSION,
            "lifetime_evaluated_at_migration": int(row.get("evaluated") or 0),
            "lifetime_fired_at_migration": int(row.get("fired") or 0),
            "condition_true_counts": json_safe(row.get("condition_true_counts") or {}),
            "condition_false_counts": json_safe(row.get("condition_false_counts") or {}),
            "condition_not_applicable_counts": json_safe(row.get("condition_not_applicable_counts") or {}),
            "margin_statistics": json_safe(row.get("margin_statistics") or {}),
            "diagnostic_reason_counts": json_safe(row.get("diagnostic_reason_counts") or {}),
            "current_schema_diagnostic_reason_counts": json_safe(row.get("current_schema_diagnostic_reason_counts") or {}),
            "path_true_counts": json_safe(row.get("path_true_counts") or {}),
            "path_observation_counts": json_safe(row.get("path_observation_counts") or {}),
            "saturated_predicates": list(row.get("saturated_predicates") or []),
            "reason": "PREDICATE_SEMANTICS_CHANGED; V9_5_27_NORMALIZES_PRIMARY_SWEEP_ADMISSION_AND_ADDS_MODEL_LOCAL_FRESH_EXECUTION_TELEMETRY",
        }
        archives = row.setdefault("predicate_schema_archives", [])
        archives.append(legacy_snapshot)
        del archives[:-5]
        for key, empty in (
            ("condition_true_counts", {}), ("condition_false_counts", {}),
            ("condition_observation_counts", {}), ("condition_false_rates", {}),
            ("condition_not_applicable_counts", {}), ("predicate_dependencies", {}),
            ("margin_statistics", {}), ("current_schema_blocker_counts", {}),
            ("current_schema_scan_mode_counts", {}), ("current_schema_diagnostic_reason_counts", {}),
            ("path_true_counts", {}), ("path_observation_counts", {}),
        ):
            row[key] = empty
        row["current_schema_evaluated"] = 0
        row["current_schema_fired"] = 0
        row["saturated_predicates"] = []
        row["health_status"] = "OBSERVING"
        row["predicate_schema_version"] = DETECTOR_REACHABILITY_SCHEMA_VERSION
        changed += 1
    report = {
        "changed": changed,
        "rows_migrated": changed,
        "schema_version": DETECTOR_REACHABILITY_SCHEMA_VERSION,
        "lifetime_totals_preserved": True,
        "trades_and_signals_preserved": True,
        "completed_at": iso_now(),
    }
    ledger["detector_reachability_schema_policy"] = {
        "current_schema": DETECTOR_REACHABILITY_SCHEMA_VERSION,
        "health_scope": "CURRENT_SCHEMA_ONLY",
        "lifetime_evaluated_and_fired_preserved": True,
        "false_denominator": "CURRENT_SCHEMA_TRUE_PLUS_FALSE_APPLICABLE_OBSERVATIONS",
    }
    previous = journal.get("predicate_schema_migration")
    if changed or not isinstance(previous, dict):
        journal["predicate_schema_migration"] = dict(report)
    else:
        previous["last_checked_at"] = report["completed_at"]
        previous["current_schema"] = DETECTOR_REACHABILITY_SCHEMA_VERSION
    return report


def setup_market_episode_key(event: dict[str, Any], context: dict[str, Any]) -> str:
    """Stable episode identity for repeated 15-minute scans of one thesis."""
    explicit = str(event.get("episode_key") or "").strip()
    if explicit:
        return explicit
    side = str(event.get("side") or "NEUTRAL")
    setup_type = str(event.get("setup_type") or SetupType.NONE.value)
    model_id = str(event.get("model_id") or event.get("ict_model") or "UNKNOWN")
    price = safe_float(context.get("price"), 0.0)
    atr15 = max(safe_float(context.get("atr15"), 0.0), price * 0.001, 1e-6)
    anchor = safe_float(
        event.get("execution_anchor"),
        safe_float(event.get("trigger_level"), safe_float(event.get("anchor"), price)),
    )
    anchor_step = max(atr15 * SETUP_EPISODE_ANCHOR_BUCKET_ATR, price * 0.0005, 1e-6)
    anchor_bucket = int(round(anchor / anchor_step)) if anchor > 0 else 0
    as_of_ts = int(event.get("as_of_ts") or _preconfirm_as_of_ts(context))
    age = safe_float(event.get("model_thesis_age_minutes"), -1.0)
    if age < 0:
        age = safe_float(event.get("market_thesis_age_minutes"), -1.0)
    origin_ts = as_of_ts - int(max(age, 0.0) * 60_000) if age >= 0 else as_of_ts
    bucket_ms = SETUP_EPISODE_TIME_BUCKET_MINUTES * 60_000
    thesis_epoch = origin_ts // max(bucket_ms, 1)
    origin = str(event.get("thesis_origin") or "UNKNOWN")
    # Qualified/ranked candidates already carry the canonical thesis key, whose
    # anchor is quantized by candidate construction. Prefer it over recomputing
    # identity from a changing ATR on every scan. Raw detector events may not yet
    # have a thesis key, so they retain the conservative anchor bucket fallback.
    thesis_key = str(event.get("thesis_key") or "").strip()
    identity = f"K{thesis_key}" if thesis_key else f"A{anchor_bucket}"
    return f"{side}|{setup_type}|{model_id}|{identity}|T{thesis_epoch}|{origin}"


def _register_setup_episode_stage(
    ledger: dict[str, Any],
    totals: dict[str, Any],
    event: dict[str, Any],
    stage: str,
    context: dict[str, Any],
    *,
    shadow_mode: bool,
) -> str:
    registry_key = "active_trade_shadow_episode_registry" if shadow_mode else "episode_registry"
    registry = ledger.setdefault(registry_key, {})
    episode_key = setup_market_episode_key(event, context)
    setup_type = str(event.get("setup_type") or SetupType.NONE.value)
    episode_totals_key = "active_trade_shadow_independent_episode_totals" if shadow_mode else "independent_episode_totals"
    episode_totals = ledger.setdefault(episode_totals_key, {})
    row = episode_totals.setdefault(setup_type, {})
    for name in ("detected", "qualified_detected", "ranked", "selected", "would_executable", "executable", "entered"):
        row[name] = int(row.get(name) or 0)
    record = registry.setdefault(episode_key, {
        "episode_key": episode_key,
        "side": str(event.get("side") or "NEUTRAL"),
        "setup_type": setup_type,
        "model_id": str(event.get("model_id") or event.get("ict_model") or "UNKNOWN"),
        "first_seen": iso_now(),
        "stages_seen": [],
    })
    seen = set(str(value) for value in (record.get("stages_seen") or []))
    if stage not in seen:
        row[stage] += 1
        seen.add(stage)
    record["stages_seen"] = sorted(seen)
    record["last_seen"] = iso_now()
    record["last_rank"] = event.get("rank")
    record["last_score"] = event.get("final_score")
    record["last_anchor"] = event.get("execution_anchor", event.get("trigger_level"))
    event["episode_key"] = episode_key
    if len(registry) > SETUP_EPISODE_REGISTRY_LIMIT:
        ordered = sorted(registry.items(), key=lambda item: str((item[1] or {}).get("last_seen") or ""))
        for key, _ in ordered[:len(registry) - SETUP_EPISODE_REGISTRY_LIMIT]:
            registry.pop(key, None)
    return episode_key


def _compact_lifecycle_candidate_event(event: dict[str, Any]) -> dict[str, Any]:
    """Lean per-run candidate snapshot. Aggregate ledgers keep the full counters."""
    if not isinstance(event, dict):
        return {}
    keys = (
        "side", "setup_type", "model_id", "ict_model", "rank", "final_score", "evidence_adjusted_selection_score",
        "episode_key", "thesis_key", "thesis_origin", "execution_anchor",
        "trigger_level", "trigger_ready", "entry_stage", "execution_source",
        "model_thesis_age_minutes", "market_thesis_age_minutes",
    )
    return {key: json_safe(event.get(key)) for key in keys if event.get(key) not in (None, "", [], {})}


def _compact_reachability_event_for_run(event: dict[str, Any]) -> dict[str, Any]:
    """Keep only episode-local reachability evidence in recent_runs.

    Full condition counts, margins, dependencies and health remain in
    setup_lifecycle_counters.detector_reachability. Repeating those payloads on
    every scan was the main source of journal growth.
    """
    if not isinstance(event, dict):
        return {}
    conditions = dict(event.get("conditions") or {})
    applicability = {str(k): bool(v) for k, v in (event.get("condition_applicability") or {}).items()}
    diagnostics = dict(event.get("diagnostics") or {})
    false_predicates = [
        str(name) for name, value in conditions.items()
        if isinstance(value, bool) and applicability.get(str(name), True) and value is False
    ][:10]
    not_applicable = [str(name) for name, applies in applicability.items() if not applies][:10]
    true_paths = [str(name) for name, value in (event.get("paths") or {}).items() if bool(value)][:8]
    return {
        "setup_type": str(event.get("setup_type") or ""),
        "fired": bool(event.get("fired")),
        "blockers": [str(value) for value in (event.get("blockers") or [])][:8],
        "false_predicates": false_predicates,
        "not_applicable_predicates": not_applicable,
        "true_paths": true_paths,
        "reason_codes": [str(value) for value in (diagnostics.get("reason_codes") or [])][:8],
        "selected_confirmation_kind": str(diagnostics.get("selected_confirmation_kind") or ""),
        "schema_version": str(event.get("schema_version") or DETECTOR_REACHABILITY_SCHEMA_VERSION),
    }


def compact_setup_lifecycle_run_for_journal(run_row: dict[str, Any]) -> dict[str, Any]:
    """Bounded recent-run representation; never used as live decision authority."""
    if not isinstance(run_row, dict):
        return {}
    if str(run_row.get("schema_version") or "") == "setup_lifecycle_recent_run_v9.5.23_compact":
        return copy.deepcopy(run_row)
    reachability_source = run_row.get("detector_reachability")
    if not isinstance(reachability_source, list):
        reachability_source = run_row.get("detector_reachability_summary") or []
    compact = {
        "time": str(run_row.get("time") or ""),
        "bot_version": str(run_row.get("bot_version") or ""),
        "architecture_version": str(run_row.get("architecture_version") or ""),
        "scan_mode": str(run_row.get("scan_mode") or "LIVE"),
        "capacity_blocked": bool(run_row.get("capacity_blocked")),
        "active_trade_id": str(run_row.get("active_trade_id") or ""),
        "detected": [_compact_lifecycle_candidate_event(item) for item in (run_row.get("detected") or []) if isinstance(item, dict)],
        "qualified_detected": [_compact_lifecycle_candidate_event(item) for item in (run_row.get("qualified_detected") or []) if isinstance(item, dict)],
        "ranked": [_compact_lifecycle_candidate_event(item) for item in (run_row.get("ranked") or []) if isinstance(item, dict)],
        "detector_reachability_summary": [
            _compact_reachability_event_for_run(item) for item in reachability_source if isinstance(item, dict)
        ],
        "selected": json_safe(run_row.get("selected")) if isinstance(run_row.get("selected"), dict) else None,
        "selection_anomaly": json_safe(run_row.get("selection_anomaly")) if isinstance(run_row.get("selection_anomaly"), dict) else None,
        "would_executable": bool(run_row.get("would_executable")),
        "executable": bool(run_row.get("executable")),
        "entered": bool(run_row.get("entered")),
        "decision_action": str(run_row.get("decision_action") or Action.NO_SETUP.value),
        "migration_flags": {
            "episode_identity_changed": bool((run_row.get("episode_identity_migration") or {}).get("changed")),
            "predicate_rows_migrated": int((run_row.get("predicate_schema_migration") or {}).get("rows_migrated") or 0),
        },
        "schema_version": "setup_lifecycle_recent_run_v9.5.23_compact",
    }
    return compact


def _episode_conversion_table(values_by_setup: dict[str, Any]) -> dict[str, Any]:
    return {
        setup: {
            **dict(values),
            "ranked_to_entered_rate": round(safe_float(values.get("entered"), 0.0) / max(int(values.get("ranked") or 0), 1), 6),
            "detected_to_ranked_rate": round(safe_float(values.get("ranked"), 0.0) / max(int(values.get("detected") or 0), 1), 6),
        }
        for setup, values in (values_by_setup or {}).items() if isinstance(values, dict)
    }


def compact_setup_lifecycle_history(journal: dict[str, Any]) -> dict[str, Any]:
    ledger = journal.setdefault("setup_lifecycle_counters", {})
    before = list(ledger.get("recent_runs") or [])
    kept = before[-SETUP_LIFECYCLE_RECENT_RUN_LIMIT:]
    compacted = [compact_setup_lifecycle_run_for_journal(row) for row in kept if isinstance(row, dict)]
    changed = before != compacted
    ledger["recent_runs"] = compacted
    return {
        "changed": changed,
        "before": len(before),
        "after": len(compacted),
        "limit": SETUP_LIFECYCLE_RECENT_RUN_LIMIT,
        "full_detector_reachability_retained_per_run": False,
    }


def update_setup_lifecycle_counters(
    journal: dict[str, Any],
    context: dict[str, Any],
    decision: Optional[Decision],
    *,
    scan_mode: str = "LIVE",
    capacity_blocked: bool = False,
    active_trade_id: str = "",
) -> dict[str, Any]:
    """Persist a truthful setup funnel without changing trading permission.

    LIVE runs update the canonical totals. ACTIVE_TRADE_SHADOW runs use a
    separate counter bucket and may report ``would_execute``, but they can never
    increment live executable/entered counters. Detector reachability is shared
    because a predicate observation remains valid while capital is occupied.
    """
    scan_mode = str(scan_mode or "LIVE").upper()
    shadow_mode = scan_mode != "LIVE"
    capacity_blocked = bool(capacity_blocked or shadow_mode)
    setup_types = _tracked_setup_types()
    ledger = journal.setdefault("setup_lifecycle_counters", {})
    episode_migration = _ensure_setup_episode_identity_schema(ledger)
    predicate_migration = migrate_predicate_reachability_schema(journal)
    totals_key = "active_trade_shadow_totals" if shadow_mode else "totals"
    totals = ledger.setdefault(totals_key, {})
    stages = ("detected", "qualified_detected", "ranked", "selected", "would_executable", "executable", "entered")
    for setup_type in setup_types:
        row = totals.setdefault(setup_type, {})
        for stage in stages:
            row[stage] = int(row.get(stage) or 0)
    # The independent episode ledger is a full 24-setup matrix, not a sparse
    # dictionary of whichever setup happened to fire first. This keeps dormant
    # setups (including DIRECTION_FLIP_15M) visible and auditable at zero.
    episode_totals_key = "active_trade_shadow_independent_episode_totals" if shadow_mode else "independent_episode_totals"
    episode_totals = ledger.setdefault(episode_totals_key, {})
    for setup_type in setup_types:
        row = episode_totals.setdefault(setup_type, {})
        for stage in stages:
            row[stage] = int(row.get(stage) or 0)

    detected_events = [
        dict(item) for item in (context.get("_setup_lifecycle_detected") or [])
        if isinstance(item, dict) and str(item.get("setup_type") or "") in setup_types
    ]
    qualified_events = [
        dict(item) for item in (context.get("_setup_lifecycle_qualified") or [])
        if isinstance(item, dict) and str(item.get("setup_type") or "") in setup_types
    ]
    ranked_events = [
        dict(item) for item in (context.get("_setup_lifecycle_ranked") or [])
        if isinstance(item, dict) and str(item.get("setup_type") or "") in setup_types
    ]
    reachability_events = [
        dict(item) for item in (context.get("_detector_reachability") or [])
        if isinstance(item, dict) and str(item.get("setup_type") or "") in DORMANT_SETUP_REACHABILITY_TYPES
    ]
    detected_events = list({_setup_lifecycle_event_key(item): item for item in detected_events}.values())
    qualified_events = list({_setup_lifecycle_event_key(item): item for item in qualified_events}.values())
    ranked_events = list({_setup_lifecycle_event_key(item): item for item in ranked_events}.values())

    # Highest-fidelity ranked identity is propagated back to qualified/detected
    # rows from the same scan. This makes the independent funnel monotonic while
    # preserving raw scan counters and event payloads.
    canonical_by_lifecycle_key = {_setup_lifecycle_event_key(item): item for item in ranked_events}
    for item in qualified_events:
        canonical_by_lifecycle_key.setdefault(_setup_lifecycle_event_key(item), item)
    identity_fields = (
        "thesis_key", "execution_anchor", "trigger_level", "as_of_ts",
        "market_thesis_age_minutes", "model_thesis_age_minutes", "thesis_origin",
    )
    for collection in (qualified_events, detected_events):
        for event in collection:
            canonical = canonical_by_lifecycle_key.get(_setup_lifecycle_event_key(event)) or {}
            for field_name in identity_fields:
                if canonical.get(field_name) not in (None, ""):
                    event[field_name] = canonical.get(field_name)

    for event in detected_events:
        totals[event["setup_type"]]["detected"] += 1
    for event in qualified_events:
        totals[event["setup_type"]]["qualified_detected"] += 1
    for event in ranked_events:
        totals[event["setup_type"]]["ranked"] += 1

    for event in detected_events:
        _register_setup_episode_stage(ledger, totals, event, "detected", context, shadow_mode=shadow_mode)
    for event in qualified_events:
        _register_setup_episode_stage(ledger, totals, event, "qualified_detected", context, shadow_mode=shadow_mode)
    for event in ranked_events:
        _register_setup_episode_stage(ledger, totals, event, "ranked", context, shadow_mode=shadow_mode)

    reachability_ledger = ledger.setdefault("detector_reachability", {})
    for event in reachability_events:
        setup_type = str(event.get("setup_type") or "")
        row = reachability_ledger.setdefault(setup_type, {
            "evaluated": 0, "fired": 0, "blocker_counts": {},
            "condition_true_counts": {}, "condition_false_counts": {},
            "condition_observation_counts": {}, "condition_false_rates": {},
            "condition_not_applicable_counts": {}, "predicate_dependencies": {},
            "margin_statistics": {}, "last_observation": {},
            "scan_mode_counts": {}, "health_status": "OBSERVING",
            "saturated_predicates": [],
            "current_schema_evaluated": 0, "current_schema_fired": 0,
            "current_schema_blocker_counts": {}, "current_schema_scan_mode_counts": {},
            "diagnostic_reason_counts": {}, "current_schema_diagnostic_reason_counts": {},
            "path_true_counts": {}, "path_observation_counts": {},
            "predicate_schema_version": DETECTOR_REACHABILITY_SCHEMA_VERSION,
        })
        if str(row.get("predicate_schema_version") or "") != DETECTOR_REACHABILITY_SCHEMA_VERSION:
            migrate_predicate_reachability_schema(journal)
            row = reachability_ledger.setdefault(setup_type, row)
        row["evaluated"] = int(row.get("evaluated") or 0) + 1
        row["fired"] = int(row.get("fired") or 0) + int(bool(event.get("fired")))
        row["current_schema_evaluated"] = int(row.get("current_schema_evaluated") or 0) + 1
        row["current_schema_fired"] = int(row.get("current_schema_fired") or 0) + int(bool(event.get("fired")))
        row["predicate_schema_version"] = DETECTOR_REACHABILITY_SCHEMA_VERSION
        mode_counts = row.setdefault("scan_mode_counts", {})
        mode_counts[scan_mode] = int(mode_counts.get(scan_mode) or 0) + 1
        current_mode_counts = row.setdefault("current_schema_scan_mode_counts", {})
        current_mode_counts[scan_mode] = int(current_mode_counts.get(scan_mode) or 0) + 1
        blockers = row.setdefault("blocker_counts", {})
        current_blockers = row.setdefault("current_schema_blocker_counts", {})
        for blocker in event.get("blockers") or []:
            blockers[str(blocker)] = int(blockers.get(str(blocker)) or 0) + 1
            current_blockers[str(blocker)] = int(current_blockers.get(str(blocker)) or 0) + 1
        diagnostics = dict(event.get("diagnostics") or {})
        reason_codes = diagnostics.get("reason_codes") or []
        lifetime_diagnostic_counts = row.setdefault("diagnostic_reason_counts", {})
        current_diagnostic_counts = row.setdefault("current_schema_diagnostic_reason_counts", {})
        for reason in reason_codes:
            key = str(reason or "").strip()
            if not key:
                continue
            lifetime_diagnostic_counts[key] = int(lifetime_diagnostic_counts.get(key) or 0) + 1
            current_diagnostic_counts[key] = int(current_diagnostic_counts.get(key) or 0) + 1
        path_true_counts = row.setdefault("path_true_counts", {})
        path_observation_counts = row.setdefault("path_observation_counts", {})
        for path_name, path_value in (event.get("paths") or {}).items():
            key = str(path_name)
            path_observation_counts[key] = int(path_observation_counts.get(key) or 0) + 1
            if bool(path_value):
                path_true_counts[key] = int(path_true_counts.get(key) or 0) + 1
        true_counts = row.setdefault("condition_true_counts", {})
        false_counts = row.setdefault("condition_false_counts", {})
        not_applicable_counts = row.setdefault("condition_not_applicable_counts", {})
        applicability = {str(k): bool(v) for k, v in (event.get("condition_applicability") or {}).items()}
        dependencies = row.setdefault("predicate_dependencies", {})
        for name, values in (event.get("predicate_dependencies") or {}).items():
            dependencies[str(name)] = [str(value) for value in values]
        for name, value in (event.get("conditions") or {}).items():
            if isinstance(value, bool):
                key = str(name)
                if not applicability.get(key, True):
                    not_applicable_counts[key] = int(not_applicable_counts.get(key) or 0) + 1
                    continue
                target = true_counts if value else false_counts
                target[key] = int(target.get(key) or 0) + 1
        margin_stats = row.setdefault("margin_statistics", {})
        for name, value in (event.get("margins") or {}).items():
            try:
                number = float(value)
            except Exception:
                continue
            if not math.isfinite(number):
                continue
            stat = margin_stats.setdefault(str(name), {"count": 0, "sum": 0.0, "min": number, "max": number})
            stat["count"] = int(stat.get("count") or 0) + 1
            stat["sum"] = safe_float(stat.get("sum"), 0.0) + number
            stat["min"] = min(safe_float(stat.get("min"), number), number)
            stat["max"] = max(safe_float(stat.get("max"), number), number)
            stat["mean"] = round(stat["sum"] / max(stat["count"], 1), 6)

        observation_counts: dict[str, int] = {}
        false_rates: dict[str, float] = {}
        for name in sorted(set(true_counts) | set(false_counts)):
            observations = int(true_counts.get(name) or 0) + int(false_counts.get(name) or 0)
            observation_counts[name] = observations
            false_rates[name] = round(int(false_counts.get(name) or 0) / max(observations, 1), 6)
        row["condition_observation_counts"] = observation_counts
        row["condition_false_rates"] = false_rates
        saturated = sorted(
            name for name, observations in observation_counts.items()
            if observations >= DORMANT_PREDICATE_SATURATION_MIN_OBSERVATIONS
            and false_rates.get(name, 0.0) >= DORMANT_PREDICATE_SATURATION_FALSE_RATE
        )
        row["saturated_predicates"] = saturated
        evaluated = int(row.get("current_schema_evaluated") or 0)
        fired = int(row.get("current_schema_fired") or 0)
        row["health_status"] = (
            "PREDICATE_SATURATION_SUSPECTED"
            if fired == 0 and saturated
            else "DORMANT_MARKET_CONDITIONS"
            if evaluated >= 50 and fired == 0
            else "REACHABLE"
            if fired > 0
            else "OBSERVING"
        )
        row["saturation_policy"] = {
            "denominator": "CURRENT_SCHEMA_APPLICABLE_TRUE_PLUS_FALSE_OBSERVATIONS",
            "minimum_observations": DORMANT_PREDICATE_SATURATION_MIN_OBSERVATIONS,
            "false_rate_threshold": DORMANT_PREDICATE_SATURATION_FALSE_RATE,
            "predicate_schema_version": DETECTOR_REACHABILITY_SCHEMA_VERSION,
            "lifetime_totals_excluded_from_health": True,
        }
        row["last_observation"] = {**dict(event), "scan_mode": scan_mode}

    selected_event: Optional[dict[str, Any]] = None
    selection_anomaly: Optional[dict[str, Any]] = None
    executable = False
    entered = False
    would_executable = False
    candidate = getattr(decision, "candidate", None) if decision is not None else None
    selected_type = str(getattr(candidate, "setup_type", "") or "")
    if candidate is not None and selected_type in setup_types:
        selected_model = str(getattr(candidate, "ict_model", "UNKNOWN") or "UNKNOWN")
        selected_source = str(
            getattr(candidate, "selected_source", "")
            or ((getattr(candidate, "score_components", {}) or {}).get("selected_source"))
            or "RANKED_CANDIDATE"
        )
        selected_key = (str(getattr(candidate, "side", "NEUTRAL")), selected_type, selected_model)
        ranked_keys = {_setup_lifecycle_event_key(item) for item in ranked_events}
        ranked_match = selected_key in ranked_keys
        saved_reentry = selected_source == "SAVED_OPPORTUNITY_REENTRY" and str(getattr(candidate, "execution_source", "")) == ExecutionSource.REENTRY.value
        selection_allowed = ranked_match or saved_reentry
        if selection_allowed:
            totals[selected_type]["selected"] += 1
            executive_report = (
                (((getattr(decision, "audit", {}) or {}).get("executive_director") or {}).get("report") or {})
                .get("executive_decision") or {}
            )
            plan_ready = bool(getattr(getattr(decision, "plan", None), "execution_ready", False))
            revalidation = dict(getattr(candidate, "revalidation_profile", {}) or {})
            blocking_reasons = [str(value) for value in (executive_report.get("blocking_reasons") or []) if str(value).strip()]
            warning_reasons = [str(value) for value in (executive_report.get("warning_reasons") or []) if str(value).strip()]
            score_value = int(safe_float(getattr(candidate, "final_score", 0), 0.0))
            action_is_entry = str(getattr(decision, "action", "")) in EXECUTABLE_ENTRY_ACTIONS
            would_executable = bool(executive_report.get("allow_execution")) or action_is_entry
            if would_executable:
                totals[selected_type]["would_executable"] += 1
            if capacity_blocked and would_executable:
                gap_classification = "ACTIVE_TRADE_CAPACITY_BLOCK"
            elif action_is_entry:
                gap_classification = "EXECUTED"
            elif not plan_ready:
                gap_classification = "PLAN_NOT_EXECUTABLE"
            elif score_value < RISKY_ENTRY_SCORE_BASE:
                gap_classification = "CANONICAL_SCORE_BELOW_RISKY"
            elif blocking_reasons:
                gap_classification = "EXECUTIVE_BLOCK"
            else:
                gap_classification = "NONE"
            executable = bool(would_executable and not capacity_blocked)
            entered = bool(action_is_entry and not capacity_blocked)
            if executable:
                totals[selected_type]["executable"] += 1
            if entered:
                totals[selected_type]["entered"] += 1
            selected_event = {
                "side": selected_key[0],
                "setup_type": selected_type,
                "model_id": selected_model,
                "selected_source": selected_source,
                "ranked_match": ranked_match,
                "final_score": score_value,
                "evidence_adjusted_selection_score": round(_candidate_selection_score(candidate), 4),
                "canonical_risky_min": RISKY_ENTRY_SCORE_BASE,
                "trigger_ready": bool(getattr(candidate, "trigger_ready", False)),
                "entry_stage": str(getattr(candidate, "entry_stage", "") or ""),
                "execution_source": str(getattr(candidate, "execution_source", "") or ""),
                "plan_execution_ready": plan_ready,
                "would_executable": would_executable,
                "capacity_blocked": capacity_blocked,
                "gap_classification": gap_classification,
                "blocking_reasons": blocking_reasons,
                "warning_reasons": warning_reasons,
                "decision_explanation": str(getattr(decision, "reason", "") or ""),
                "thesis_key": str(getattr(candidate, "thesis_key", "") or ""),
                "thesis_clock": {
                    "market_age_minutes": safe_float(getattr(candidate, "market_thesis_age_minutes", -1.0), -1.0),
                    "model_age_minutes": safe_float(getattr(candidate, "model_thesis_age_minutes", -1.0), -1.0),
                    "effective_age_minutes": safe_float(getattr(candidate, "thesis_age_minutes", -1.0), -1.0),
                    "origin": str(getattr(candidate, "thesis_origin", "") or ""),
                    "hard_expired": bool(revalidation.get("hard_expired") or revalidation.get("state") == "DEAD"),
                },
            }
            selected_episode_event = {
                **selected_event,
                "thesis_key": str(getattr(candidate, "thesis_key", "") or ""),
                "execution_anchor": safe_float(getattr(candidate, "execution_anchor", 0.0), 0.0),
                "trigger_level": safe_float(getattr(candidate, "trigger_level", 0.0), 0.0),
                "market_thesis_age_minutes": safe_float(getattr(candidate, "market_thesis_age_minutes", -1.0), -1.0),
                "model_thesis_age_minutes": safe_float(getattr(candidate, "model_thesis_age_minutes", -1.0), -1.0),
                "thesis_origin": str(getattr(candidate, "thesis_origin", "") or ""),
                "as_of_ts": _preconfirm_as_of_ts(context),
            }
            ranked_episode_event = next(
                (item for item in ranked_events if _setup_lifecycle_event_key(item) == selected_key),
                None,
            )
            if isinstance(ranked_episode_event, dict) and ranked_episode_event.get("episode_key"):
                selected_episode_event["episode_key"] = str(ranked_episode_event["episode_key"])
            selected_event["episode_key"] = _register_setup_episode_stage(
                ledger, totals, selected_episode_event, "selected", context, shadow_mode=shadow_mode
            )
            if would_executable:
                _register_setup_episode_stage(ledger, totals, selected_episode_event, "would_executable", context, shadow_mode=shadow_mode)
            if executable:
                _register_setup_episode_stage(ledger, totals, selected_episode_event, "executable", context, shadow_mode=shadow_mode)
            if entered:
                _register_setup_episode_stage(ledger, totals, selected_episode_event, "entered", context, shadow_mode=shadow_mode)
        else:
            selection_anomaly = {
                "code": "SELECTED_WITHOUT_RANKED_MATCH",
                "side": selected_key[0],
                "setup_type": selected_type,
                "model_id": selected_model,
                "selected_source": selected_source,
                "scan_mode": scan_mode,
            }
            if decision is not None:
                decision.audit.setdefault("setup_lifecycle", {})["selection_anomaly"] = selection_anomaly

    episode_totals_key = "active_trade_shadow_independent_episode_totals" if shadow_mode else "independent_episode_totals"
    episode_totals = ledger.get(episode_totals_key) or {}
    ledger["independent_episode_policy"] = {
        "identity": "CANONICAL_RANKED_EPISODE_KEY_PROPAGATED_TO_ALL_STAGES",
        "anchor_bucket_atr": SETUP_EPISODE_ANCHOR_BUCKET_ATR,
        "time_bucket_minutes": SETUP_EPISODE_TIME_BUCKET_MINUTES,
        "raw_scan_counters_preserved": True,
        "ranked_selected_key_equality_enforced": True,
        "schema_version": SETUP_EPISODE_SCHEMA_VERSION,
    }
    live_conversion = _episode_conversion_table(ledger.get("independent_episode_totals") or {})
    shadow_conversion = _episode_conversion_table(ledger.get("active_trade_shadow_independent_episode_totals") or {})
    ledger["live_independent_episode_conversion"] = live_conversion
    ledger["shadow_independent_episode_conversion"] = shadow_conversion
    # Compatibility alias is deliberately LIVE-only. A shadow run may update the
    # shadow table but can no longer overwrite the analytics used to describe
    # real entry conversion.
    ledger["independent_episode_conversion"] = copy.deepcopy(live_conversion)
    ledger["independent_episode_conversion_scope"] = "LIVE_COMPATIBILITY_ALIAS"

    run_row = {
        "time": iso_now(),
        "bot_version": BOT_VERSION,
        "architecture_version": ARCHITECTURE_VERSION,
        "scan_mode": scan_mode,
        "capacity_blocked": capacity_blocked,
        "active_trade_id": str(active_trade_id or ""),
        "detected": detected_events,
        "qualified_detected": qualified_events,
        "ranked": ranked_events,
        "detector_reachability": reachability_events,
        "selected": selected_event,
        "selection_anomaly": selection_anomaly,
        "would_executable": would_executable,
        "executable": executable,
        "entered": entered,
        "decision_action": str(getattr(decision, "action", Action.NO_SETUP.value) if decision is not None else Action.NO_SETUP.value),
        "episode_identity_migration": episode_migration,
        "predicate_schema_migration": predicate_migration,
    }
    recent = ledger.setdefault("recent_runs", [])
    recent.append(compact_setup_lifecycle_run_for_journal(run_row))
    if len(recent) > SETUP_LIFECYCLE_RECENT_RUN_LIMIT:
        del recent[:-SETUP_LIFECYCLE_RECENT_RUN_LIMIT]
    ledger.update({
        "setup_type_count": len(setup_types),
        "stages": list(stages),
        "selection_contract": "ranked match required; decision.reason is explanatory, never a blocking reason",
        "active_trade_shadow_contract": "separate counters; may observe would_execute; cannot increment live entered",
        "updated_at": run_row["time"],
        "schema_version": "setup_lifecycle_funnel_v9.5.20_canonical_episode_predicate_scope",
    })
    return run_row



# ==========================================================
# v9.5 HIERARCHICAL CONFIRMATION PROBABILITY LAYER
# ==========================================================
# Contract:
# - observes only precursor state frozen at as_of_ts;
# - never publishes an execution Action;
# - calibrated output may only gate/promote an already existing fresh-probe path;
# - untrusted bootstrap heuristics remain audit-only.

PRECONFIRM_FEATURE_NAMES = (
    "approach_velocity_atr",
    "approach_efficiency",
    "wick_rejection_ratio",
    "flow_alignment",
    "failed_attempts_norm",
    "dealing_range_favorability",
    "htf_alignment",
    "liquidity_swept",
    "distance_to_anchor_atr",
    "session_quality",
    "trigger_freshness",
    "prior_touch_rejection",
    "volume_impulse",
)


def _preconfirm_sigmoid(value: float) -> float:
    value = clamp(safe_float(value, 0.0), -35.0, 35.0)
    return 1.0 / (1.0 + math.exp(-value))


def _preconfirm_logit(probability: float) -> float:
    p = clamp(safe_float(probability, 0.5), 1e-6, 1.0 - 1e-6)
    return math.log(p / (1.0 - p))


def _preconfirm_as_of_ts(context: dict[str, Any]) -> int:
    candles = (context.get("candles") or {}).get("3m", []) or []
    confirmed = [int(getattr(c, "ts", 0) or 0) for c in candles if getattr(c, "confirmed", True)]
    return max(confirmed, default=int(now_utc().timestamp() * 1000))


def _preconfirm_candles(context: dict[str, Any], timeframe: str, as_of_ts: int) -> list[Candle]:
    candles = (context.get("candles") or {}).get(timeframe, []) or []
    return sorted(
        [c for c in candles if getattr(c, "confirmed", True) and int(getattr(c, "ts", 0) or 0) <= int(as_of_ts)],
        key=lambda c: int(getattr(c, "ts", 0) or 0),
    )


def _preconfirm_event_kind(candidate: Candidate) -> str:
    model = str(getattr(candidate, "ict_model", "") or "").upper()
    setup = str(getattr(candidate, "setup_type", "") or "").upper()
    if getattr(candidate, "confirmation_pending", False):
        return "EXPLICIT_PENDING_CONFIRMATION"
    if any(token in model or token in setup for token in ("SWEEP", "LIQUIDITY")):
        return "LIQUIDITY_SWEEP_REVERSAL"
    if "FVG" in model or "FVG" in setup:
        return "FVG_REACTION"
    if "OB" in model or "ORDER_BLOCK" in setup:
        return "OB_REACTION"
    if any(token in model or token in setup for token in ("CHOCH", "BOS", "MSS", "STRUCTURAL")):
        return "STRUCTURE_CONFIRMATION"
    return "DIRECTIONAL_ACCEPTANCE"


def _preconfirm_model_family(candidate: Candidate) -> str:
    setup_family = str(getattr(candidate, "setup_family", "UNKNOWN") or "UNKNOWN").upper()
    return f"{setup_family}:{_preconfirm_event_kind(candidate)}"


def _preconfirm_range_position(candles: list[Candle], price: float) -> float:
    recent = candles[-32:]
    if not recent:
        return 0.5
    low = min(safe_float(c.low, price) for c in recent)
    high = max(safe_float(c.high, price) for c in recent)
    if high - low <= 1e-9:
        return 0.5
    return clamp((price - low) / (high - low), 0.0, 1.0)


def _preconfirm_feature_vector(
    context: dict[str, Any],
    candidate: Candidate,
    precursor_journal: Optional[dict[str, Any]] = None,
    *,
    as_of_ts: Optional[int] = None,
) -> dict[str, float]:
    """Build timestamp-frozen features. No candle after as_of_ts is visible."""
    as_of_ts = int(as_of_ts or _preconfirm_as_of_ts(context))
    c3 = _preconfirm_candles(context, "3m", as_of_ts)
    c15 = _preconfirm_candles(context, "15m", as_of_ts)
    price = safe_float(context.get("price"), safe_float(c3[-1].close, 0.0) if c3 else 0.0)
    if c3:
        price = safe_float(c3[-1].close, price)
    atr15 = max(safe_float(context.get("atr15"), 0.0), price * 0.001, 1e-6)
    sign = 1.0 if str(candidate.side).upper() == Side.LONG.value else -1.0
    anchor = safe_float(
        (getattr(candidate, "confirmation_state", {}) or {}).get("anchor"),
        safe_float(candidate.trigger_level, safe_float(candidate.execution_anchor, price)),
    )
    if anchor <= 0:
        anchor = price

    approach = c3[-8:] if len(c3) >= 2 else c15[-6:]
    net = sign * (safe_float(approach[-1].close, price) - safe_float(approach[0].close, price)) if len(approach) >= 2 else 0.0
    path = sum(abs(safe_float(approach[i].close) - safe_float(approach[i - 1].close)) for i in range(1, len(approach)))
    approach_velocity = clamp(net / atr15, -3.0, 3.0)
    approach_efficiency = clamp(net / max(path, atr15 * 0.05), -1.0, 1.0)

    wick_values: list[float] = []
    for candle in (c3[-8:] or c15[-6:]):
        rng = max(safe_float(candle.high) - safe_float(candle.low), 1e-9)
        body_low = min(safe_float(candle.open), safe_float(candle.close))
        body_high = max(safe_float(candle.open), safe_float(candle.close))
        wick = body_low - safe_float(candle.low) if sign > 0 else safe_float(candle.high) - body_high
        wick_values.append(clamp(wick / rng, 0.0, 1.0))
    wick_rejection = mean(wick_values) if wick_values else 0.0

    latest_context_ts = _preconfirm_as_of_ts(context)
    # Flow/CVD are point-in-time aggregates, not candle series. During historical
    # timestamp-freeze replay they are disabled unless the replay point is the
    # actual context edge; otherwise a current aggregate would leak future flow.
    flow = context.get("flow") or {} if as_of_ts >= latest_context_ts else {}
    cvd = context.get("cvd") or {} if as_of_ts >= latest_context_ts else {}
    flow_bias = str(flow.get("bias") or "NEUTRAL").upper()
    cvd_bias = str(cvd.get("bias") or "NEUTRAL").upper()
    if flow.get("reliable"):
        flow_alignment = 1.0 if flow_bias == str(candidate.side).upper() else -1.0 if flow_bias in {Side.LONG.value, Side.SHORT.value} else 0.0
    else:
        proxy = 1.0 if cvd_bias == str(candidate.side).upper() else -1.0 if cvd_bias in {Side.LONG.value, Side.SHORT.value} else 0.0
        flow_alignment = proxy * SYNTHETIC_CVD_SCORE_MULTIPLIER

    family = _preconfirm_model_family(candidate)
    failed_attempts = 0
    for event in (precursor_journal or {}).get("events", []) or []:
        if not isinstance(event, dict) or str(event.get("model_family") or "") != family:
            continue
        if int(event.get("observed_ts") or 0) > as_of_ts:
            continue
        if _preconfirm_event_status(event) in {"FAILED", "EXPIRED"}:
            event_anchor = safe_float(event.get("anchor"), anchor)
            if abs(event_anchor - anchor) <= atr15 * 0.50:
                failed_attempts += 1
    failed_attempts_norm = clamp(failed_attempts / 5.0, 0.0, 1.0)

    range_position = _preconfirm_range_position(c15, price)
    dealing_favorability = 1.0 - range_position if sign > 0 else range_position
    htf_alignment = clamp(safe_float(get_htf_fact(candidate).get("alignment_score"), 0.0), -1.0, 1.0)
    evidence_text = " ".join(
        [str(x) for x in (getattr(candidate, "evidence_families", []) or [])]
        + [str(x) for x in (getattr(candidate, "confirmations", []) or [])]
    ).upper()
    liquidity_swept = 1.0 if "SWEEP" in evidence_text or "LIQUIDITY" in _preconfirm_event_kind(candidate) else 0.0
    distance_to_anchor_atr = clamp(abs(price - anchor) / atr15, 0.0, 4.0)

    try:
        session_hour = datetime.fromtimestamp(as_of_ts / 1000.0, tz=timezone.utc).astimezone(zoneinfo.ZoneInfo("Europe/Kyiv")).hour
        if ASIA_START_H <= session_hour < ASIA_END_H:
            session = "ASIA"
        elif LONDON_START_H <= session_hour < LONDON_END_H:
            session = "LONDON"
        elif NY_START_H <= session_hour < NY_END_H:
            session = "NY"
        else:
            session = "OFF_HOURS"
    except Exception:
        session = str(context.get("session_name") or "OFF_HOURS").upper()
    session_quality = {"LONDON": 1.0, "NY": 1.0, "ASIA": 0.55, "OFF_HOURS": 0.25}.get(session, 0.50)
    age = max(0.0, candidate_execution_trigger_age_minutes(candidate))
    trigger_freshness = math.exp(-age / max(float(EXECUTION_TRIGGER_TTL_MIN), 1.0))

    touches: list[float] = []
    for candle in c15[-24:]:
        if safe_float(candle.low) <= anchor <= safe_float(candle.high):
            rng = max(safe_float(candle.high) - safe_float(candle.low), 1e-9)
            reaction = sign * (safe_float(candle.close) - anchor) / rng
            touches.append(clamp(reaction, -1.0, 1.0))
    prior_touch_rejection = mean(touches[-4:]) if touches else 0.0

    volume_window = c3[-12:] if c3 else c15[-8:]
    if volume_window:
        avg_volume = mean(max(0.0, safe_float(c.volume)) for c in volume_window[:-1] or volume_window)
        volume_impulse = clamp(safe_float(volume_window[-1].volume) / max(avg_volume, 1e-9), 0.0, 3.0) / 3.0
    else:
        volume_impulse = 0.0

    return {
        "approach_velocity_atr": round(approach_velocity, 6),
        "approach_efficiency": round(approach_efficiency, 6),
        "wick_rejection_ratio": round(wick_rejection, 6),
        "flow_alignment": round(flow_alignment, 6),
        "failed_attempts_norm": round(failed_attempts_norm, 6),
        "dealing_range_favorability": round(dealing_favorability, 6),
        "htf_alignment": round(htf_alignment, 6),
        "liquidity_swept": round(liquidity_swept, 6),
        "distance_to_anchor_atr": round(distance_to_anchor_atr, 6),
        "session_quality": round(session_quality, 6),
        "trigger_freshness": round(trigger_freshness, 6),
        "prior_touch_rejection": round(prior_touch_rejection, 6),
        "volume_impulse": round(volume_impulse, 6),
    }


def _preconfirm_heuristic_probability(features: dict[str, float]) -> float:
    z = (
        -0.30
        + 0.55 * safe_float(features.get("approach_velocity_atr"))
        + 0.75 * safe_float(features.get("approach_efficiency"))
        + 0.80 * safe_float(features.get("wick_rejection_ratio"))
        + 0.55 * safe_float(features.get("flow_alignment"))
        - 0.80 * safe_float(features.get("failed_attempts_norm"))
        + 0.50 * safe_float(features.get("dealing_range_favorability"))
        + 0.65 * safe_float(features.get("htf_alignment"))
        + 0.45 * safe_float(features.get("liquidity_swept"))
        - 0.45 * safe_float(features.get("distance_to_anchor_atr"))
        + 0.30 * safe_float(features.get("session_quality"))
        + 0.55 * safe_float(features.get("trigger_freshness"))
        + 0.40 * safe_float(features.get("prior_touch_rejection"))
        + 0.20 * safe_float(features.get("volume_impulse"))
    )
    return clamp(_preconfirm_sigmoid(z), 0.08, 0.92)


def _preconfirm_select_model_rows(rows: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Select a recent, schema-consistent training population without label peeking.

    Selection depends only on chronological order and schema metadata. Labels are
    never used to choose the window. Legacy rows remain available to hierarchical
    rate calibration, but the pooled logistic prefers the current feature schema
    once that schema has enough resolved observations.
    """
    ordered = sorted([dict(row) for row in rows if isinstance(row, dict)], key=lambda row: int(row.get("observed_ts") or 0))
    current = [row for row in ordered if str(row.get("feature_schema_version") or "") == PRECONFIRM_FEATURE_SCHEMA_VERSION]
    if len(current) >= PRECONFIRM_CURRENT_SCHEMA_MIN_MODEL_ROWS:
        selected = current[-PRECONFIRM_RECENT_MODEL_WINDOW:]
        population = "CURRENT_FEATURE_SCHEMA_RECENT_WINDOW"
    else:
        selected = ordered[-PRECONFIRM_RECENT_MODEL_WINDOW:]
        population = "MIXED_SCHEMA_RECENT_BOOTSTRAP"

    n = len(selected)
    for index, row in enumerate(selected):
        age_rows = max(0, n - 1 - index)
        recency_weight = math.exp(-math.log(2.0) * age_rows / max(PRECONFIRM_RECENCY_HALF_LIFE_ROWS, 1e-9))
        schema_weight = 1.0 if str(row.get("feature_schema_version") or "") == PRECONFIRM_FEATURE_SCHEMA_VERSION else 0.35
        row["sample_weight"] = round(recency_weight * schema_weight, 10)
    return selected, {
        "population": population,
        "available_rows": len(ordered),
        "current_feature_schema_rows": len(current),
        "selected_rows": len(selected),
        "recent_window": PRECONFIRM_RECENT_MODEL_WINDOW,
        "recency_half_life_rows": PRECONFIRM_RECENCY_HALF_LIFE_ROWS,
        "excluded_rows_total": max(0, len(ordered) - len(selected)),
        "legacy_feature_schema_rows_available": max(0, len(ordered) - len(current)),
        "current_schema_rows_excluded_by_window": max(0, len(current) - len(selected)) if population == "CURRENT_FEATURE_SCHEMA_RECENT_WINDOW" else 0,
        "selection_uses_labels": False,
        "schema_version": "preconfirm_model_population_v9.5.17",
    }


def _preconfirm_fit_logistic(rows: list[dict[str, Any]]) -> dict[str, Any]:
    if not rows:
        return {"valid": False, "reason": "no_rows"}
    sample_weights = [max(1e-6, safe_float(row.get("sample_weight"), 1.0)) for row in rows]
    total_weight = sum(sample_weights)
    means = {
        name: sum(weight * safe_float(row["features"].get(name)) for row, weight in zip(rows, sample_weights)) / max(total_weight, 1e-9)
        for name in PRECONFIRM_FEATURE_NAMES
    }
    stds: dict[str, float] = {}
    for name in PRECONFIRM_FEATURE_NAMES:
        variance = sum(
            weight * (safe_float(row["features"].get(name)) - means[name]) ** 2
            for row, weight in zip(rows, sample_weights)
        ) / max(total_weight, 1e-9)
        stds[name] = max(math.sqrt(variance), 1e-6)
    positive_weight = sum(weight for row, weight in zip(rows, sample_weights) if int(row["label"]) == 1)
    negative_weight = sum(weight for row, weight in zip(rows, sample_weights) if int(row["label"]) == 0)
    if positive_weight <= 0 or negative_weight <= 0:
        return {"valid": False, "reason": "single_class"}
    weights = {name: 0.0 for name in PRECONFIRM_FEATURE_NAMES}
    intercept = _preconfirm_logit(positive_weight / max(positive_weight + negative_weight, 1e-9))
    pos_class_weight = 0.5 / positive_weight
    neg_class_weight = 0.5 / negative_weight
    for epoch in range(320):
        grad_b = 0.0
        grad_w = {name: 0.0 for name in PRECONFIRM_FEATURE_NAMES}
        for row, row_weight in zip(rows, sample_weights):
            label = int(row["label"])
            class_weight = pos_class_weight if label == 1 else neg_class_weight
            z = intercept
            standardized = {}
            for name in PRECONFIRM_FEATURE_NAMES:
                value = (safe_float(row["features"].get(name)) - means[name]) / stds[name]
                standardized[name] = value
                z += weights[name] * value
            error = (_preconfirm_sigmoid(z) - label) * class_weight * row_weight
            grad_b += error
            for name in PRECONFIRM_FEATURE_NAMES:
                grad_w[name] += error * standardized[name]
        lr = 0.18 / math.sqrt(1.0 + epoch / 40.0)
        intercept -= lr * grad_b
        for name in PRECONFIRM_FEATURE_NAMES:
            weights[name] -= lr * (grad_w[name] + 0.002 * weights[name])
    return {
        "valid": True,
        "means": means,
        "stds": stds,
        "weights": weights,
        "intercept": intercept,
        "weighted_sample_size": round(total_weight, 6),
        "sample_weight_policy": "RECENCY_EXPONENTIAL_PLUS_SCHEMA_WEIGHT",
    }


def _preconfirm_predict_model(model: dict[str, Any], features: dict[str, float]) -> float:
    if not model.get("valid"):
        return 0.5
    z = safe_float(model.get("intercept"), 0.0)
    for name in PRECONFIRM_FEATURE_NAMES:
        mean_value = safe_float((model.get("means") or {}).get(name), 0.0)
        std_value = max(safe_float((model.get("stds") or {}).get(name), 1.0), 1e-6)
        z += safe_float((model.get("weights") or {}).get(name), 0.0) * ((safe_float(features.get(name)) - mean_value) / std_value)
    return clamp(_preconfirm_sigmoid(z), 0.01, 0.99)


def _preconfirm_fit_platt(
    probabilities: list[float],
    labels: list[int],
    sample_weights: Optional[list[float]] = None,
) -> dict[str, float]:
    if len(probabilities) < 8 or len(set(labels)) < 2:
        return {"a": 1.0, "b": 0.0, "fitted": False}
    weights = list(sample_weights or [1.0] * len(labels))
    if len(weights) != len(labels):
        raise ValueError("Platt sample_weights must match labels")
    weights = [max(1e-6, safe_float(value, 1.0)) for value in weights]
    total_weight = max(sum(weights), 1e-9)
    a, b = 1.0, 0.0
    for epoch in range(240):
        grad_a = 0.0
        grad_b = 0.0
        for probability, label, weight in zip(probabilities, labels, weights):
            x = _preconfirm_logit(probability)
            error = (_preconfirm_sigmoid(a * x + b) - int(label)) * weight / total_weight
            grad_a += error * x
            grad_b += error
        lr = 0.08 / math.sqrt(1.0 + epoch / 50.0)
        # Calibration may adjust sharpness/intercept, but it must never reverse
        # the ordering learned by the classifier. Negative slope caused AUC 0.75
        # raw predictions to be reported as ~0.25 after calibration.
        a = max(0.05, a - lr * (grad_a + 0.001 * a))
        b -= lr * grad_b
    return {"a": a, "b": b, "fitted": True, "monotonic": True, "weighted": True}


def _preconfirm_apply_platt(probability: float, calibration: dict[str, Any]) -> float:
    if not calibration.get("fitted"):
        return clamp(probability, 0.01, 0.99)
    return clamp(_preconfirm_sigmoid(safe_float(calibration.get("a"), 1.0) * _preconfirm_logit(probability) + safe_float(calibration.get("b"), 0.0)), 0.01, 0.99)


def _preconfirm_orient_probability(probability: float, model: dict[str, Any]) -> float:
    """Apply an orientation chosen on calibration rows only, never on test rows."""
    p = clamp(safe_float(probability, 0.5), 0.01, 0.99)
    return 1.0 - p if int(model.get("probability_orientation") or 1) < 0 else p


def _preconfirm_auc(labels: list[int], probabilities: list[float]) -> Optional[float]:
    positives = [p for p, y in zip(probabilities, labels) if int(y) == 1]
    negatives = [p for p, y in zip(probabilities, labels) if int(y) == 0]
    if not positives or not negatives:
        return None
    wins = 0.0
    total = 0
    for positive in positives:
        for negative in negatives:
            total += 1
            wins += 1.0 if positive > negative else 0.5 if positive == negative else 0.0
    return wins / total if total else None


def _preconfirm_brier(labels: list[int], probabilities: list[float]) -> Optional[float]:
    if not labels:
        return None
    return mean((safe_float(p) - int(y)) ** 2 for p, y in zip(probabilities, labels))


def _preconfirm_scope_parts(model_family: str) -> tuple[str, str]:
    raw = str(model_family or "UNKNOWN:UNKNOWN").upper()
    if ":" not in raw:
        return raw or "UNKNOWN", "UNKNOWN"
    setup_family, event_kind = raw.split(":", 1)
    return setup_family or "UNKNOWN", event_kind or "UNKNOWN"


PRECONFIRM_TERMINAL_STATUSES = {"CONFIRMED", "FAILED", "EXPIRED"}
PRECONFIRM_VALID_STATUSES = {"PENDING", *PRECONFIRM_TERMINAL_STATUSES}


def _preconfirm_event_status(event: dict[str, Any]) -> str:
    """Read the canonical lifecycle status with v9.4 outcome compatibility."""
    raw = str(event.get("status") or event.get("outcome") or "PENDING").upper()
    aliases = {
        "INVALIDATED": "FAILED",
        "AMBIGUOUS": "FAILED",
        "SUCCESS": "CONFIRMED",
    }
    status = aliases.get(raw, raw)
    return status if status in PRECONFIRM_VALID_STATUSES else "PENDING"


def _preconfirm_legacy_outcome(status: str) -> str:
    """Keep old readers alive while status becomes the source of truth."""
    canonical = str(status or "PENDING").upper()
    return "INVALIDATED" if canonical == "FAILED" else canonical


def _preconfirm_set_status(
    event: dict[str, Any],
    status: str,
    *,
    reason: str = "",
    resolved_ts: Optional[int] = None,
    outcome_ts: Optional[int] = None,
    resolved_price: Optional[float] = None,
    evidence: Optional[dict[str, Any]] = None,
) -> None:
    canonical = str(status or "PENDING").upper()
    if canonical not in PRECONFIRM_VALID_STATUSES:
        raise ValueError(f"Unsupported preconfirmation status: {canonical}")
    event["status"] = canonical
    event["outcome"] = _preconfirm_legacy_outcome(canonical)
    if reason:
        event["resolution_reason"] = reason
    if canonical != "PENDING":
        event["resolved_ts"] = int(resolved_ts or int(now_utc().timestamp() * 1000))
        event["resolved_at"] = iso_now()
        if outcome_ts is not None:
            event["outcome_ts"] = int(outcome_ts)
        if resolved_price is not None:
            event["resolved_price"] = round_price(resolved_price)
        if evidence is not None:
            event["resolution_evidence"] = dict(evidence)

def _preconfirm_training_rows(
    journal: dict[str, Any],
    family: Optional[str] = None,
    *,
    setup_family: Optional[str] = None,
    event_kind: Optional[str] = None,
) -> list[dict[str, Any]]:
    """Return labels from resolved precursor events, never from closed trades."""
    exact_family = str(family or "").upper()
    setup_scope = str(setup_family or "").upper()
    event_scope = str(event_kind or "").upper()
    rows: list[dict[str, Any]] = []
    for event in journal.get("events", []) or []:
        if not isinstance(event, dict):
            continue
        event_family = str(event.get("model_family") or "UNKNOWN:UNKNOWN").upper()
        event_setup, event_kind_value = _preconfirm_scope_parts(event_family)
        if exact_family and event_family != exact_family:
            continue
        if setup_scope and event_setup != setup_scope:
            continue
        if event_scope and event_kind_value != event_scope:
            continue
        status = _preconfirm_event_status(event)
        if status == "CONFIRMED":
            label = 1
        elif status == "FAILED" or (status == "EXPIRED" and PRECONFIRM_EXPIRED_LABEL_MODE == "NEGATIVE"):
            label = 0
        else:
            continue
        features = event.get("features") or {}
        if not all(name in features for name in PRECONFIRM_FEATURE_NAMES):
            continue
        rows.append({
            "features": {name: safe_float(features.get(name)) for name in PRECONFIRM_FEATURE_NAMES},
            "label": label,
            "observed_ts": int(event.get("observed_ts") or event.get("created_ts") or 0),
            "model_family": event_family,
            "setup_family": event_setup,
            "event_kind": event_kind_value,
            "event_id": str(event.get("event_id") or event.get("id") or ""),
            "status": status,
            "feature_schema_version": str(event.get("feature_schema_version") or ""),
            "forecast_schema_version": str(event.get("forecast_schema_version") or ""),
            "bot_version_at_observation": str(event.get("bot_version_at_observation") or ""),
        })
    return sorted(rows, key=lambda row: row["observed_ts"])


def _preconfirm_weighted_brier(labels: list[int], probabilities: list[float], sample_weights: Optional[list[float]]=None) -> Optional[float]:
    if not labels or len(labels)!=len(probabilities): return None
    weights=list(sample_weights or [1.0]*len(labels))
    if len(weights)!=len(labels): return None
    total=sum(max(safe_float(w,1.0),1e-6) for w in weights); loss=0.0
    for y,p,w in zip(labels,probabilities,weights):
        ww=max(safe_float(w,1.0),1e-6); loss+=ww*(clamp(safe_float(p,0.5),0.0,1.0)-int(y))**2
    return loss/max(total,1e-9)


def _preconfirm_apply_calibration_champion(logistic_probability: float, heuristic_probability: float, champion: Optional[dict[str, Any]]) -> float:
    champion=dict(champion or {}); w=clamp(safe_float(champion.get("logistic_weight"),1.0),0.0,1.0); shrink=clamp(safe_float(champion.get("neutral_shrink"),1.0),0.05,1.0)
    combined=w*clamp(logistic_probability,0.01,0.99)+(1.0-w)*clamp(heuristic_probability,0.01,0.99)
    return clamp(0.50+shrink*(combined-0.50),0.01,0.99)


def _preconfirm_select_calibration_champion(
    logistic_probabilities: list[float], heuristic_probabilities: list[float], labels: list[int], sample_weights: list[float],
) -> dict[str, Any]:
    """Select calibration on the calibration slice without sacrificing discrimination.

    v9.5.30 treats AUC and Brier as different jobs: the ensemble may improve Brier,
    but it cannot win merely by flattening/reversing a more discriminative channel.
    OOS labels are never consulted for the choice.
    """
    if len(labels) < 6 or len(set(labels)) < 2:
        return {
            "logistic_weight": 1.0,
            "neutral_shrink": PRECONFIRM_UNTRUSTED_MODEL_SHRINK,
            "reason": "CALIBRATION_SLICE_TOO_SMALL",
            "selection_uses_oos_labels": False,
            "auc_preservation_enforced": True,
            "schema_version": "preconfirm_calibration_champion_v9.5.30_auc_preserving",
        }
    logistic_auc = _preconfirm_auc(labels, logistic_probabilities)
    heuristic_auc = _preconfirm_auc(labels, heuristic_probabilities)
    reference_auc = max(
        safe_float(logistic_auc, 0.50) if logistic_auc is not None else 0.50,
        safe_float(heuristic_auc, 0.50) if heuristic_auc is not None else 0.50,
    )
    auc_floor = max(PRECONFIRM_CHAMPION_MIN_AUC, reference_auc - PRECONFIRM_CHAMPION_MAX_AUC_DEGRADATION)
    candidates = []
    for logistic_weight in (0.0, 0.25, 0.50, 0.75, 1.0):
        for shrink in (0.35, 0.50, 0.75, 1.0):
            probs = [
                _preconfirm_apply_calibration_champion(
                    lp, hp, {"logistic_weight": logistic_weight, "neutral_shrink": shrink}
                )
                for lp, hp in zip(logistic_probabilities, heuristic_probabilities)
            ]
            brier = _preconfirm_weighted_brier(labels, probs, sample_weights)
            auc = _preconfirm_auc(labels, probs)
            eligible = bool(auc is not None and safe_float(auc, 0.0) + 1e-12 >= auc_floor)
            objective = safe_float(brier, 9.0) + 0.0025 * logistic_weight + 0.0015 * shrink
            candidates.append({
                "logistic_weight": logistic_weight,
                "neutral_shrink": shrink,
                "brier": brier,
                "auc": auc,
                "eligible": eligible,
                "objective": objective,
            })
    eligible = [row for row in candidates if row.get("eligible")]
    if not eligible:
        # Fail closed to the most discriminative unblended calibration channel.
        chosen = max(
            candidates,
            key=lambda row: (safe_float(row.get("auc"), -1.0), -safe_float(row.get("brier"), 9.0)),
        )
        reason = "NO_ENSEMBLE_PASSED_AUC_FLOOR_BEST_DISCRIMINATION_FALLBACK"
    else:
        chosen = min(
            eligible,
            key=lambda row: (
                safe_float(row.get("objective"), 9.0),
                -safe_float(row.get("auc"), 0.5),
                safe_float(row.get("logistic_weight"), 1.0),
            ),
        )
        reason = "AUC_PRESERVING_CALIBRATION_SLICE_CHAMPION"
    return {
        "logistic_weight": chosen["logistic_weight"],
        "neutral_shrink": chosen["neutral_shrink"],
        "calibration_brier": round(chosen["brier"], 6) if chosen["brier"] is not None else None,
        "calibration_auc": round(chosen["auc"], 6) if chosen["auc"] is not None else None,
        "reference_logistic_auc": round(logistic_auc, 6) if logistic_auc is not None else None,
        "reference_heuristic_auc": round(heuristic_auc, 6) if heuristic_auc is not None else None,
        "reference_auc": round(reference_auc, 6),
        "auc_floor": round(auc_floor, 6),
        "auc_degradation_allowance": PRECONFIRM_CHAMPION_MAX_AUC_DEGRADATION,
        "candidate_count": len(candidates),
        "eligible_candidate_count": len(eligible),
        "reason": reason,
        "selection_uses_oos_labels": False,
        "auc_preservation_enforced": True,
        "schema_version": "preconfirm_calibration_champion_v9.5.30_auc_preserving",
    }

def _preconfirm_build_model(journal: dict[str, Any], family: Optional[str] = None) -> dict[str, Any]:
    """Chronologically validated, schema-consistent logistic model.

    v9.5.25 permits an anti-correlated classifier to be *oriented* only from the
    calibration slice. The unseen OOS slice is never consulted to choose sign,
    window, family or calibration. This fixes persistent anti-discrimination
    without turning the test set into training data.
    """
    all_rows = _preconfirm_training_rows(journal, family)
    rows, population = _preconfirm_select_model_rows(all_rows)
    n = len(rows)
    scope = str(family or "GLOBAL_POOLED")
    if n < PRECONFIRM_MIN_TRAIN_ROWS:
        return {"trusted": False, "valid": False, "sample_size": n,
                "available_sample_size": len(all_rows), "scope": scope,
                "reason": "selected_rows_below_logistic_floor", "auc": None,
                "brier": None, "trust_level": "BOOTSTRAP", "training_population": population}
    train_end = max(12, int(n * 0.70))
    calibration_end = max(train_end + 4, int(n * 0.85))
    calibration_end = min(calibration_end, n - 4)
    if calibration_end <= train_end or n - calibration_end < 4:
        return {"trusted": False, "valid": False, "sample_size": n,
                "available_sample_size": len(all_rows), "scope": scope,
                "reason": "insufficient_chronological_holdout", "auc": None,
                "brier": None, "trust_level": "BOOTSTRAP", "training_population": population}
    train_rows = rows[:train_end]
    calibration_rows = rows[train_end:calibration_end]
    test_rows = rows[calibration_end:]
    base_model = _preconfirm_fit_logistic(train_rows)
    if not base_model.get("valid"):
        return {"trusted": False, "valid": False, "sample_size": n,
                "available_sample_size": len(all_rows), "scope": scope,
                "reason": base_model.get("reason", "fit_failed"), "auc": None,
                "brier": None, "trust_level": "BOOTSTRAP", "training_population": population}

    calibration_labels = [int(row["label"]) for row in calibration_rows]
    calibration_raw = [_preconfirm_predict_model(base_model, row["features"]) for row in calibration_rows]
    auc_raw = _preconfirm_auc(calibration_labels, calibration_raw)
    auc_inverted = _preconfirm_auc(calibration_labels, [1.0 - p for p in calibration_raw])
    probability_orientation = -1 if (
        auc_raw is not None and auc_inverted is not None
        and auc_raw < PRECONFIRM_ANTI_DISCRIMINATION_AUC
        and auc_inverted >= PRECONFIRM_AUC_GATE
        and auc_inverted >= auc_raw + 0.10
    ) else 1
    base_model["probability_orientation"] = probability_orientation
    calibration_oriented = [_preconfirm_orient_probability(p, base_model) for p in calibration_raw]
    calibration_auc_oriented = _preconfirm_auc(calibration_labels, calibration_oriented)
    calibration_weights=[safe_float(row.get("sample_weight"),1.0) for row in calibration_rows]
    calibration = _preconfirm_fit_platt(calibration_oriented, calibration_labels, calibration_weights)
    calibration_logistic=[_preconfirm_apply_platt(p,calibration) for p in calibration_oriented]
    calibration_heuristic=[_preconfirm_heuristic_probability(row["features"]) for row in calibration_rows]
    calibration_champion=_preconfirm_select_calibration_champion(calibration_logistic,calibration_heuristic,calibration_labels,calibration_weights)

    test_raw = [_preconfirm_predict_model(base_model, row["features"]) for row in test_rows]
    test_oriented = [_preconfirm_orient_probability(p, base_model) for p in test_raw]
    test_logistic = [_preconfirm_apply_platt(p, calibration) for p in test_oriented]
    test_heuristic = [_preconfirm_heuristic_probability(row["features"]) for row in test_rows]
    test_probabilities = [_preconfirm_apply_calibration_champion(lp,hp,calibration_champion) for lp,hp in zip(test_logistic,test_heuristic)]
    test_labels = [int(row["label"]) for row in test_rows]
    test_weights=[safe_float(row.get("sample_weight"),1.0) for row in test_rows]
    auc = _preconfirm_auc(test_labels, test_probabilities)
    brier = _preconfirm_weighted_brier(test_labels, test_probabilities, test_weights)
    raw_logistic_auc=_preconfirm_auc(test_labels,test_logistic); raw_logistic_brier=_preconfirm_weighted_brier(test_labels,test_logistic,test_weights)
    temporal_stability_passed = bool(calibration_champion.get("calibration_auc") is not None and safe_float(calibration_champion.get("calibration_auc"),0.0) >= 0.50)
    trusted = bool(
        auc is not None and auc >= PRECONFIRM_AUC_GATE
        and brier is not None and brier <= PRECONFIRM_BRIER_WARN
        and temporal_stability_passed
        and population.get("population") == "CURRENT_FEATURE_SCHEMA_RECENT_WINDOW"
    )
    return {
        **base_model,
        "trusted": trusted, "valid": True, "sample_size": n,
        "available_sample_size": len(all_rows), "scope": scope,
        "auc": round(auc, 6) if auc is not None else None,
        "brier": round(brier, 6) if brier is not None else None,
        "calibration": calibration,
        "calibration_champion": calibration_champion,
        "raw_logistic_oos_auc": round(raw_logistic_auc, 6) if raw_logistic_auc is not None else None,
        "raw_logistic_oos_brier": round(raw_logistic_brier, 6) if raw_logistic_brier is not None else None,
        "probability_orientation": probability_orientation,
        "calibration_auc_raw": round(auc_raw, 6) if auc_raw is not None else None,
        "calibration_auc_inverted": round(auc_inverted, 6) if auc_inverted is not None else None,
        "calibration_auc_oriented": round(calibration_auc_oriented, 6) if calibration_auc_oriented is not None else None,
        "orientation_policy": "CALIBRATION_SLICE_ONLY; OOS_LABELS_NEVER_SELECT_ORIENTATION_OR_ENSEMBLE",
        "ensemble_policy": "CALIBRATION_SLICE_SELECTS_LOGISTIC_HEURISTIC_NEUTRAL_SHRINK; OOS_IS_EVALUATION_ONLY",
        "temporal_stability_passed": temporal_stability_passed,
        "reason": "trusted" if trusted else "temporal_discrimination_instability" if not temporal_stability_passed else "validation_gate_not_passed",
        "trust_level": "FULL" if trusted and n >= PRECONFIRM_FULL_TRUST_ROWS else "PARTIAL" if trusted else "BOOTSTRAP",
        "chronological_split": {"train": len(train_rows), "calibration": len(calibration_rows), "test": len(test_rows)},
        "training_population": population,
        "forecast_schema_version": PRECONFIRM_FORECAST_SCHEMA_VERSION,
        "selection_uses_oos_labels": False,
    }



def _preconfirm_rate_posterior(
    rows: list[dict[str, Any]],
    prior_probability: float,
    prior_strength: float,
) -> dict[str, Any]:
    successes = sum(int(row.get("label", 0)) for row in rows)
    total = len(rows)
    prior_probability = clamp(prior_probability, 0.02, 0.98)
    prior_strength = max(float(prior_strength), 0.0)
    alpha = prior_probability * prior_strength + successes
    beta = (1.0 - prior_probability) * prior_strength + (total - successes)
    posterior = alpha / max(alpha + beta, 1e-9)
    return {
        "successes": successes,
        "total": total,
        "prior_probability": prior_probability,
        "prior_strength": prior_strength,
        "posterior_probability": clamp(posterior, 0.02, 0.98),
    }


def _preconfirm_hierarchical_calibration(
    journal: dict[str, Any],
    model_family: str,
    heuristic_probability: float,
) -> dict[str, Any]:
    """Calibrate in three stages without pretending six rows are a full model.

    0..5 resolved labels: heuristic only.
    6..11: weak global Bayesian correction with a strong neutral prior.
    12..23: global -> setup family -> exact family empirical-Bayes hierarchy.
    24+: this hierarchy remains the family guard while pooled logistic may become
    authoritative only after its chronological validation gate passes.
    """
    setup_family, event_kind = _preconfirm_scope_parts(model_family)
    global_rows = _preconfirm_training_rows(journal)
    setup_rows = _preconfirm_training_rows(journal, setup_family=setup_family)
    exact_rows = _preconfirm_training_rows(journal, model_family)
    global_n = len(global_rows)
    setup_n = len(setup_rows)
    exact_n = len(exact_rows)
    global_labels = {int(row["label"]) for row in global_rows}
    has_both_labels = len(global_labels) >= 2
    weak_available = bool(
        global_n >= PRECONFIRM_WEAK_MIN_CALIBRATION_ROWS
        and has_both_labels
    )
    hierarchical_available = bool(
        global_n >= PRECONFIRM_GLOBAL_MIN_CALIBRATION_ROWS
        and has_both_labels
    )

    if not weak_available:
        return {
            "calibrated": False,
            "calibration_tier": "HEURISTIC_ONLY",
            "probability": heuristic_probability,
            "global_sample_size": global_n,
            "setup_family_sample_size": setup_n,
            "exact_family_sample_size": exact_n,
            "setup_family": setup_family,
            "event_kind": event_kind,
            "reason": "insufficient_global_resolved_precursors",
            "downgrade_trusted": False,
            "promotion_trusted": False,
            "interval_low": 0.0,
            "interval_high": 1.0,
            "interval_scope": "NONE",
        }

    # The first layer intentionally borrows only from the global pool and keeps
    # a strong 50/50 prior. Six observations may inform a forecast; they may not
    # grant entry authority or family-specific confidence.
    if not hierarchical_available:
        global_post = _preconfirm_rate_posterior(
            global_rows,
            0.50,
            PRECONFIRM_WEAK_PRIOR_STRENGTH,
        )
        selected_rate = safe_float(global_post.get("posterior_probability"), 0.50)
        historical_heuristic = mean(
            _preconfirm_heuristic_probability(row["features"])
            for row in global_rows
        ) if global_rows else 0.50
        adjustment_weight = clamp(global_n / (global_n + 18.0), 0.10, 0.35)
        logit_offset = _preconfirm_logit(selected_rate) - _preconfirm_logit(historical_heuristic)
        calibrated_probability = _preconfirm_sigmoid(
            _preconfirm_logit(heuristic_probability) + adjustment_weight * logit_offset
        )
        successes = sum(int(row["label"]) for row in global_rows)
        low, high = _preconfirm_wilson(successes, global_n)
        return {
            "calibrated": True,
            "calibration_tier": "EARLY_WEAK_BAYES",
            "probability": clamp(calibrated_probability, 0.03, 0.97),
            "global_sample_size": global_n,
            "setup_family_sample_size": setup_n,
            "exact_family_sample_size": exact_n,
            "effective_sample_size": round(global_n * adjustment_weight, 3),
            "setup_family": setup_family,
            "event_kind": event_kind,
            "global_posterior": global_post,
            "selected_posterior_probability": round(selected_rate, 6),
            "historical_heuristic_probability": round(historical_heuristic, 6),
            "adjustment_weight": round(adjustment_weight, 6),
            "interval_low": round(low, 6),
            "interval_high": round(high, 6),
            "interval_scope": "GLOBAL_POOLED_WEAK",
            "downgrade_trusted": False,
            "promotion_trusted": False,
            "reason": "global_bayesian_weak_calibration",
        }

    global_post = _preconfirm_rate_posterior(global_rows, 0.50, 4.0)
    setup_post = _preconfirm_rate_posterior(
        setup_rows,
        safe_float(global_post.get("posterior_probability"), 0.50),
        PRECONFIRM_SETUP_PARENT_STRENGTH,
    )
    exact_post = _preconfirm_rate_posterior(
        exact_rows,
        safe_float(setup_post.get("posterior_probability"), 0.50),
        PRECONFIRM_EXACT_PARENT_STRENGTH,
    )

    if exact_n >= PRECONFIRM_EXACT_FAMILY_MIN_ROWS:
        selected_rows = exact_rows
        selected_post = exact_post
        interval_scope = "EXACT_MODEL_FAMILY"
    elif setup_n >= PRECONFIRM_SETUP_FAMILY_MIN_ROWS:
        selected_rows = setup_rows
        selected_post = setup_post
        interval_scope = "SETUP_FAMILY"
    else:
        selected_rows = global_rows
        selected_post = global_post
        interval_scope = "GLOBAL_POOLED"

    selected_rate = safe_float(selected_post.get("posterior_probability"), 0.50)
    historical_heuristic = mean(
        _preconfirm_heuristic_probability(row["features"])
        for row in selected_rows
    ) if selected_rows else 0.50
    effective_n = exact_n + 0.50 * setup_n + 0.25 * global_n
    adjustment_weight = clamp(effective_n / (effective_n + 8.0), 0.20, 0.90)
    logit_offset = _preconfirm_logit(selected_rate) - _preconfirm_logit(historical_heuristic)
    calibrated_probability = _preconfirm_sigmoid(
        _preconfirm_logit(heuristic_probability) + adjustment_weight * logit_offset
    )

    successes = sum(int(row["label"]) for row in selected_rows)
    low, high = _preconfirm_wilson(successes, len(selected_rows))
    promotion_trusted = bool(
        global_n >= PRECONFIRM_PROMOTION_MIN_GLOBAL_ROWS
        and exact_n >= PRECONFIRM_PROMOTION_MIN_EXACT_ROWS
        and low >= PRECONFIRM_PROMOTION_MIN_WILSON_LOW
        and has_both_labels
    )
    return {
        "calibrated": True,
        "calibration_tier": "HIERARCHICAL_EMPIRICAL_BAYES",
        "probability": clamp(calibrated_probability, 0.03, 0.97),
        "global_sample_size": global_n,
        "setup_family_sample_size": setup_n,
        "exact_family_sample_size": exact_n,
        "effective_sample_size": round(effective_n, 3),
        "setup_family": setup_family,
        "event_kind": event_kind,
        "global_posterior": global_post,
        "setup_family_posterior": setup_post,
        "exact_family_posterior": exact_post,
        "selected_posterior_probability": round(selected_rate, 6),
        "historical_heuristic_probability": round(historical_heuristic, 6),
        "adjustment_weight": round(adjustment_weight, 6),
        "interval_low": round(low, 6),
        "interval_high": round(high, 6),
        "interval_scope": interval_scope,
        "downgrade_trusted": True,
        "promotion_trusted": promotion_trusted,
        "reason": "hierarchical_empirical_bayes",
    }

def _preconfirm_wilson(successes: int, total: int, z: float = 1.96) -> tuple[float, float]:
    if total <= 0:
        return 0.0, 1.0
    p = successes / total
    denominator = 1.0 + z * z / total
    center = (p + z * z / (2.0 * total)) / denominator
    margin = z * math.sqrt((p * (1.0 - p) / total) + (z * z / (4.0 * total * total))) / denominator
    return clamp(center - margin, 0.0, 1.0), clamp(center + margin, 0.0, 1.0)


def _preconfirm_local_interval(rows: list[dict[str, Any]], features: dict[str, float], model: dict[str, Any]) -> tuple[float, float, int]:
    if not rows:
        return 0.0, 1.0, 0
    means = model.get("means") or {name: 0.0 for name in PRECONFIRM_FEATURE_NAMES}
    stds = model.get("stds") or {name: 1.0 for name in PRECONFIRM_FEATURE_NAMES}
    ranked = []
    for row in rows:
        distance = 0.0
        for name in PRECONFIRM_FEATURE_NAMES:
            scale = max(safe_float(stds.get(name), 1.0), 1e-6)
            distance += ((safe_float(row["features"].get(name)) - safe_float(features.get(name))) / scale) ** 2
        ranked.append((distance, int(row["label"])))
    neighbors = sorted(ranked, key=lambda item: item[0])[:PRECONFIRM_LOCAL_NEIGHBORS]
    successes = sum(label for _, label in neighbors)
    low, high = _preconfirm_wilson(successes, len(neighbors))
    return low, high, len(neighbors)


def _preconfirm_terminal_label(event: dict[str, Any]) -> Optional[int]:
    status = _preconfirm_event_status(event)
    if status == "CONFIRMED":
        return 1
    if status == "FAILED" or (status == "EXPIRED" and PRECONFIRM_EXPIRED_LABEL_MODE == "NEGATIVE"):
        return 0
    return None


def _preconfirm_feature_schema_forecasts(
    journal: dict[str, Any],
    *,
    forecast_schema: Optional[str] = None,
) -> list[dict[str, Any]]:
    """Frozen online forecasts for drift diagnostics or authority validation.

    Feature-schema rows from an older forecast policy may diagnose drift, but only
    rows from the exact current forecast schema can accumulate live authority.
    """
    rows: list[dict[str, Any]] = []
    for event in journal.get("events", []) or []:
        if not isinstance(event, dict):
            continue
        if str(event.get("feature_schema_version") or "") != PRECONFIRM_FEATURE_SCHEMA_VERSION:
            continue
        event_forecast_schema = str(event.get("forecast_schema_version") or "")
        if forecast_schema is not None and event_forecast_schema != str(forecast_schema):
            continue
        label = _preconfirm_terminal_label(event)
        if label is None:
            continue
        if forecast_schema == PRECONFIRM_FORECAST_SCHEMA_VERSION:
            probability = safe_float(event.get("validation_probability", event.get("probability", event.get("confirmation_probability"))), -1.0)
        else:
            probability = safe_float(event.get("probability", event.get("confirmation_probability")), -1.0)
        if not (0.0 <= probability <= 1.0):
            continue
        rows.append({
            "event_id": str(event.get("event_id") or event.get("id") or ""),
            "observed_ts": int(event.get("observed_ts") or event.get("created_ts") or 0),
            "resolved_ts": int(event.get("resolved_ts") or event.get("outcome_ts") or 0),
            "probability": probability,
            "label": label,
            "status": _preconfirm_event_status(event),
            "forecast_schema_version": event_forecast_schema,
        })
    return sorted(rows, key=lambda row: (row["observed_ts"], row["resolved_ts"], row["event_id"]))


def _preconfirm_current_schema_forecasts(journal: dict[str, Any]) -> list[dict[str, Any]]:
    """Authority-eligible forecasts from the exact current policy schema."""
    return _preconfirm_feature_schema_forecasts(
        journal,
        forecast_schema=PRECONFIRM_FORECAST_SCHEMA_VERSION,
    )


def _preconfirm_authority_gate(
    journal: dict[str, Any],
    global_model: dict[str, Any],
) -> dict[str, Any]:
    """Grant execution authority only after recent online validation is stable.

    Repeating the same journal does not increase the pass streak. A new validation
    epoch requires at least one newly resolved current-schema forecast.
    """
    rows = _preconfirm_current_schema_forecasts(journal)
    recent = rows[-PRECONFIRM_AUTHORITY_RECENT_WINDOW:]
    labels = [int(row["label"]) for row in recent]
    probabilities = [safe_float(row["probability"], 0.5) for row in recent]
    recent_auc = _preconfirm_auc(labels, probabilities) if len(set(labels)) >= 2 else None
    recent_brier = _preconfirm_brier(labels, probabilities) if labels else None
    current_n = len(rows)
    recent_n = len(recent)

    diagnostic_rows = _preconfirm_feature_schema_forecasts(journal)
    diagnostic_recent = diagnostic_rows[-PRECONFIRM_AUTHORITY_RECENT_WINDOW:]
    diagnostic_labels = [int(row["label"]) for row in diagnostic_recent]
    diagnostic_probabilities = [safe_float(row["probability"], 0.5) for row in diagnostic_recent]
    diagnostic_auc = _preconfirm_auc(diagnostic_labels, diagnostic_probabilities) if len(set(diagnostic_labels)) >= 2 else None
    diagnostic_brier = _preconfirm_brier(diagnostic_labels, diagnostic_probabilities) if diagnostic_labels else None
    # Before the new forecast policy has its own minimum sample, prior frozen
    # forecasts from the same feature schema remain valid drift evidence only.
    if recent_n >= PRECONFIRM_ANTI_DISCRIMINATION_MIN_ROWS:
        drift_auc = recent_auc
        drift_sample_size = recent_n
        drift_source = "CURRENT_FORECAST_SCHEMA"
    else:
        drift_auc = diagnostic_auc
        drift_sample_size = len(diagnostic_recent)
        drift_source = "PRIOR_FORECAST_SCHEMA_DIAGNOSTIC_ONLY"

    latest_resolved_ts = max((int(row.get("resolved_ts") or 0) for row in rows), default=0)
    validation_epoch = f"{PRECONFIRM_FEATURE_SCHEMA_VERSION}:{PRECONFIRM_FORECAST_SCHEMA_VERSION}:{current_n}:{latest_resolved_ts}"

    global_pass = bool(global_model.get("trusted"))
    sample_pass = current_n >= PRECONFIRM_AUTHORITY_MIN_SCHEMA_ROWS
    class_balance_pass = len(set(labels)) >= 2
    recent_auc_pass = bool(recent_auc is not None and recent_auc >= PRECONFIRM_AUTHORITY_RECENT_AUC_GATE)
    recent_brier_pass = bool(recent_brier is not None and recent_brier <= PRECONFIRM_AUTHORITY_RECENT_BRIER_GATE)
    recently_anti_discriminative = bool(
        drift_sample_size >= PRECONFIRM_ANTI_DISCRIMINATION_MIN_ROWS
        and drift_auc is not None
        and drift_auc < PRECONFIRM_ANTI_DISCRIMINATION_AUC
    )
    validation_pass = bool(
        global_pass and sample_pass and class_balance_pass
        and recent_auc_pass and recent_brier_pass
        and not recently_anti_discriminative
    )

    previous = ((journal.get("model_status") or {}).get("AUTHORITY_GATE") or {})
    previous_epoch = str(previous.get("validation_epoch") or "")
    previous_streak = max(0, int(previous.get("consecutive_passes") or 0))
    if validation_epoch == previous_epoch:
        consecutive = previous_streak
    elif validation_pass:
        consecutive = previous_streak + 1
    else:
        consecutive = 0
    authority_trusted = bool(
        validation_pass
        and consecutive >= PRECONFIRM_AUTHORITY_REQUIRED_CONSECUTIVE_PASSES
    )

    failed_conditions: list[str] = []
    if not global_pass:
        failed_conditions.append("GLOBAL_MODEL_UNTRUSTED")
    if not sample_pass:
        failed_conditions.append("CURRENT_SCHEMA_SAMPLE_BELOW_MINIMUM")
    if not class_balance_pass:
        failed_conditions.append("CURRENT_SCHEMA_SINGLE_CLASS_OR_EMPTY")
    if not recent_auc_pass:
        failed_conditions.append("RECENT_AUC_BELOW_GATE")
    if not recent_brier_pass:
        failed_conditions.append("RECENT_BRIER_ABOVE_GATE")
    if recently_anti_discriminative:
        failed_conditions.append("RECENTLY_ANTI_DISCRIMINATIVE")
    if validation_pass and consecutive < PRECONFIRM_AUTHORITY_REQUIRED_CONSECUTIVE_PASSES:
        failed_conditions.append("CONSECUTIVE_VALIDATION_EPOCHS_PENDING")

    return {
        "authority_trusted": authority_trusted,
        "global_model_trusted": global_pass,
        "validation_pass": validation_pass,
        "feature_schema_version": PRECONFIRM_FEATURE_SCHEMA_VERSION,
        "forecast_schema_version": PRECONFIRM_FORECAST_SCHEMA_VERSION,
        "current_schema_resolved_events": current_n,
        "minimum_current_schema_events": PRECONFIRM_AUTHORITY_MIN_SCHEMA_ROWS,
        "recent_window": PRECONFIRM_AUTHORITY_RECENT_WINDOW,
        "recent_sample_size": recent_n,
        "recent_auc": round(recent_auc, 6) if recent_auc is not None else None,
        "recent_auc_gate": PRECONFIRM_AUTHORITY_RECENT_AUC_GATE,
        "recent_brier": round(recent_brier, 6) if recent_brier is not None else None,
        "recent_brier_gate": PRECONFIRM_AUTHORITY_RECENT_BRIER_GATE,
        "diagnostic_feature_schema_sample_size": len(diagnostic_rows),
        "diagnostic_recent_sample_size": len(diagnostic_recent),
        "diagnostic_recent_auc": round(diagnostic_auc, 6) if diagnostic_auc is not None else None,
        "diagnostic_recent_brier": round(diagnostic_brier, 6) if diagnostic_brier is not None else None,
        "drift_evidence_source": drift_source,
        "drift_evidence_auc": round(drift_auc, 6) if drift_auc is not None else None,
        "drift_evidence_sample_size": drift_sample_size,
        "prior_forecast_schema_has_no_authority": True,
        "recently_anti_discriminative": recently_anti_discriminative,
        "anti_discrimination_auc_threshold": PRECONFIRM_ANTI_DISCRIMINATION_AUC,
        "anti_discrimination_min_rows": PRECONFIRM_ANTI_DISCRIMINATION_MIN_ROWS,
        "class_balance_pass": class_balance_pass,
        "consecutive_passes": consecutive,
        "required_consecutive_passes": PRECONFIRM_AUTHORITY_REQUIRED_CONSECUTIVE_PASSES,
        "validation_epoch": validation_epoch,
        "latest_resolved_ts": latest_resolved_ts,
        "failed_conditions": failed_conditions,
        "authority_policy": "GLOBAL_AND_CURRENT_FORECAST_SCHEMA_ROLLING_AND_CONSECUTIVE_WITH_ANTI_DISCRIMINATION_LOCK",
        "schema_version": "preconfirm_authority_gate_v9.5.27",
    }


def _preconfirm_recent_channel_router(journal: dict[str, Any]) -> dict[str, Any]:
    """Choose the next audit forecast channel from completed historical forecasts only.

    This is online model routing, not OOS leakage: the current pending event has no
    outcome yet and therefore cannot influence its own channel. Authority remains
    separately locked until new frozen forecasts pass the normal rolling gates.
    """
    completed=[]
    for event in journal.get("events", []) or []:
        if not isinstance(event, dict):
            continue
        status=_preconfirm_event_status(event)
        if status=="CONFIRMED": label=1
        elif status in {"FAILED","EXPIRED"}: label=0
        else: continue
        if str(event.get("feature_schema_version") or "") != PRECONFIRM_FEATURE_SCHEMA_VERSION:
            continue
        est=dict(event.get("estimate_at_observation") or {})
        completed.append((int(event.get("observed_ts") or 0),label,est))
    completed=sorted(completed,key=lambda row:row[0])[-PRECONFIRM_CHANNEL_ROUTER_WINDOW:]
    channel_extractors={
        "HIERARCHICAL_POSTERIOR": lambda est: safe_float((est.get("hierarchical_calibration") or {}).get("selected_posterior_probability"), float("nan")),
        "CALIBRATED_LOGISTIC": lambda est: safe_float(est.get("calibrated_logistic_probability"), float("nan")),
        "HEURISTIC": lambda est: safe_float(est.get("heuristic_probability"), float("nan")),
        "LEGACY_VALIDATION_POLICY": lambda est: safe_float(est.get("validation_probability"), float("nan")),
    }
    rows=[]
    for name,extract in channel_extractors.items():
        labels=[]; probs=[]
        for _,label,est in completed:
            try: value=extract(est)
            except Exception: continue
            if math.isfinite(value):
                labels.append(label); probs.append(clamp(value,0.0,1.0))
        auc=_preconfirm_auc(labels,probs) if len(labels)>=PRECONFIRM_CHANNEL_ROUTER_MIN_ROWS and len(set(labels))>=2 else None
        brier=_preconfirm_brier(labels,probs) if labels else None
        eligible=bool(
            len(labels)>=PRECONFIRM_CHANNEL_ROUTER_MIN_ROWS and auc is not None and auc>=PRECONFIRM_CHANNEL_ROUTER_MIN_AUC
            and brier is not None and brier<=PRECONFIRM_CHANNEL_ROUTER_MAX_BRIER
        )
        rows.append({"channel":name,"sample_size":len(labels),"auc":auc,"brier":brier,"eligible":eligible})
    eligible=[row for row in rows if row.get("eligible")]
    chosen=max(eligible,key=lambda row:(safe_float(row.get("auc"),0.0),-safe_float(row.get("brier"),9.0))) if eligible else None
    return {
        "selected_channel": str((chosen or {}).get("channel") or "NONE"),
        "selected_auc": round(safe_float((chosen or {}).get("auc")),6) if chosen else None,
        "selected_brier": round(safe_float((chosen or {}).get("brier")),6) if chosen else None,
        "selected_sample_size": int((chosen or {}).get("sample_size") or 0),
        "channel_rows": [{**row,"auc":round(row["auc"],6) if row.get("auc") is not None else None,"brier":round(row["brier"],6) if row.get("brier") is not None else None} for row in rows],
        "selection_uses_current_event_outcome": False,
        "authority_granted": False,
        "schema_version": "preconfirm_channel_router_v9.5.30_past_only",
    }


def _preconfirm_estimate(
    journal: dict[str, Any], candidate: Candidate, features: dict[str, float],
    model_cache: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    family = _preconfirm_model_family(candidate)
    global_model = model_cache.setdefault("__GLOBAL_POOLED__", _preconfirm_build_model(journal, None))
    family_key = f"__FAMILY__:{family}"
    family_model = model_cache.setdefault(family_key, _preconfirm_build_model(journal, family))
    authority_gate = ((journal.get("model_status") or {}).get("AUTHORITY_GATE") or {})
    authority_trusted = bool(authority_gate.get("authority_trusted"))
    heuristic = _preconfirm_heuristic_probability(features)
    hierarchy = _preconfirm_hierarchical_calibration(journal, family, heuristic)

    def model_rank(model: dict[str, Any]) -> tuple[float, float, int]:
        auc = safe_float(model.get("auc"), -1.0) if model.get("auc") is not None else -1.0
        brier = safe_float(model.get("brier"), 9.0) if model.get("brier") is not None else 9.0
        return (auc, -brier, int(model.get("sample_size") or 0))

    family_oos_usable = bool(
        family_model.get("valid")
        and family_model.get("auc") is not None
        and safe_float(family_model.get("auc"), 0.0) >= PRECONFIRM_AUC_GATE
        and family_model.get("brier") is not None
        and safe_float(family_model.get("brier"), 1.0) <= SETUP_CALIBRATION_VALIDATION_MAX_BRIER
    )
    global_oos_usable = bool(global_model.get("valid"))
    selected_model = global_model
    selected_scope = "GLOBAL_POOLED"
    if family_oos_usable and (
        not global_oos_usable
        or model_rank(family_model) > model_rank(global_model)
        or safe_float(family_model.get("auc"), 0.0) >= safe_float(global_model.get("auc"), 0.0) + 0.03
        or safe_float(family_model.get("brier"), 1.0) <= safe_float(global_model.get("brier"), 1.0) - 0.02
    ):
        selected_model = family_model
        selected_scope = "EXACT_MODEL_FAMILY_OOS"

    model_holdout_anti = bool(
        int(selected_model.get("sample_size") or 0) >= PRECONFIRM_ANTI_DISCRIMINATION_MIN_ROWS
        and selected_model.get("auc") is not None
        and safe_float(selected_model.get("auc"), 0.5) < PRECONFIRM_ANTI_DISCRIMINATION_AUC
    )
    anti_lock = bool(authority_gate.get("recently_anti_discriminative") or model_holdout_anti)
    validation_probability: Optional[float] = None
    raw_probability: Optional[float] = None
    calibrated_logistic_probability: Optional[float] = None
    if selected_model.get("valid"):
        raw_probability = _preconfirm_predict_model(selected_model, features)
        oriented_probability = _preconfirm_orient_probability(raw_probability, selected_model)
        calibrated_logistic_probability = _preconfirm_apply_platt(oriented_probability, selected_model.get("calibration") or {})
        validation_probability = _preconfirm_apply_calibration_champion(calibrated_logistic_probability, heuristic, selected_model.get("calibration_champion") or {})

    channel_router = _preconfirm_recent_channel_router(journal)
    routed_channel = str(channel_router.get("selected_channel") or "NONE")
    routed_probability: Optional[float] = None
    if routed_channel == "HIERARCHICAL_POSTERIOR" and hierarchy.get("calibrated"):
        routed_probability = safe_float(hierarchy.get("selected_posterior_probability"), safe_float(hierarchy.get("probability"), heuristic))
    elif routed_channel == "CALIBRATED_LOGISTIC" and calibrated_logistic_probability is not None:
        routed_probability = calibrated_logistic_probability
    elif routed_channel == "HEURISTIC":
        routed_probability = heuristic
    elif routed_channel == "LEGACY_VALIDATION_POLICY" and validation_probability is not None:
        routed_probability = validation_probability
    router_safe = bool(routed_probability is not None and safe_float(channel_router.get("selected_auc"),0.0) >= PRECONFIRM_CHANNEL_ROUTER_MIN_AUC)
    if router_safe:
        validation_probability = clamp(safe_float(routed_probability,0.5),0.01,0.99)
        # Past-only routing is diagnostic forecast selection, never live authority.
        anti_lock = False

    if anti_lock and validation_probability is not None:
        # v9.5.30: once past-only diagnostics declare this policy anti-discriminative,
        # the *new forecast schema* freezes a neutral validation forecast instead
        # of continuing to accumulate known-bad ranking probabilities. This cannot
        # create authority; it deliberately forces a clean future re-validation.
        validation_probability = 0.50
        probability, source, calibrated = 0.50, "ANTI_DISCRIMINATION_NEUTRALIZED_AUDIT_ONLY", True
        downgrade_trusted = promotion_trusted = False
        trust_level = "ANTI_DISCRIMINATION_LOCK"
    elif selected_model.get("trusted") and validation_probability is not None:
        probability = validation_probability
        source = "FAMILY_OOS_LOGISTIC_AUDIT_ONLY" if selected_scope != "GLOBAL_POOLED" else "CALIBRATED_RECENT_SCHEMA_LOGISTIC"
        calibrated = True
        # A family model can improve the audit forecast, but cannot borrow the
        # global authority token. New forecast-schema frozen rows must validate it first.
        downgrade_trusted = bool(authority_trusted and selected_scope == "GLOBAL_POOLED")
        promotion_trusted = bool(downgrade_trusted and hierarchy.get("promotion_trusted"))
        trust_level = "AUTHORITY_TRUSTED" if downgrade_trusted else "OOS_VALIDATED_AUDIT_ONLY"
    elif selected_model.get("valid") and validation_probability is not None:
        if router_safe:
            probability = validation_probability
            source = f"DRIFT_SAFE_{routed_channel}_AUDIT_ONLY"
            trust_level = "PAST_ONLY_CHANNEL_ROUTED_AUDIT"
        else:
            probability = 0.50 + (validation_probability - 0.50) * PRECONFIRM_UNTRUSTED_MODEL_SHRINK
            source = "FAMILY_OOS_LOGISTIC_AUDIT_ONLY" if selected_scope != "GLOBAL_POOLED" else "RECENT_SCHEMA_LOGISTIC_AUDIT_ONLY"
            trust_level = "RECENT_SCHEMA_BOOTSTRAP"
        calibrated = True; downgrade_trusted = promotion_trusted = False
    elif hierarchy.get("calibrated"):
        validation_probability = safe_float(hierarchy.get("probability"), heuristic)
        probability = validation_probability
        tier = str(hierarchy.get("calibration_tier") or "HIERARCHICAL_EMPIRICAL_BAYES")
        source = "GLOBAL_BAYES_WEAK_CALIBRATION" if tier == "EARLY_WEAK_BAYES" else "HIERARCHICAL_EMPIRICAL_BAYES"
        trust_level = "WEAK_BAYES_BOOTSTRAP" if tier == "EARLY_WEAK_BAYES" else "HIERARCHICAL_BOOTSTRAP"
        calibrated = True; downgrade_trusted = promotion_trusted = False
    else:
        validation_probability = heuristic; probability = heuristic
        source = "HEURISTIC_UNCALIBRATED"; trust_level = "HEURISTIC_ONLY"
        calibrated = False; downgrade_trusted = promotion_trusted = False

    exact_rows = _preconfirm_training_rows(journal, family)
    interval_low = safe_float(hierarchy.get("interval_low"), 0.0)
    interval_high = safe_float(hierarchy.get("interval_high"), 1.0)
    interval_scope = str(hierarchy.get("interval_scope") or "NONE")
    if selected_model.get("trusted"):
        low, high, neighbor_count = _preconfirm_local_interval(exact_rows, features, selected_model)
        if neighbor_count >= PRECONFIRM_EXACT_FAMILY_MIN_ROWS:
            interval_low, interval_high, interval_scope = low, high, "EXACT_NEIGHBORHOOD"
    else:
        neighbor_count = len(exact_rows)
    global_n = int(hierarchy.get("global_sample_size") or global_model.get("sample_size") or 0)
    setup_n = int(hierarchy.get("setup_family_sample_size") or 0)
    exact_n = int(hierarchy.get("exact_family_sample_size") or len(exact_rows))
    precursor_active = _preconfirm_should_log(candidate)
    return {
        "available": True, "probability": round(probability, 6), "probability_pct": round(probability * 100.0, 1),
        "raw_model_probability": round(raw_probability, 6) if raw_probability is not None else None,
        "calibrated_logistic_probability": round(calibrated_logistic_probability, 6) if selected_model.get("valid") and raw_probability is not None else None,
        "calibration_champion": json_safe(selected_model.get("calibration_champion") or {}),
        "channel_router": json_safe(channel_router),
        "routed_channel": routed_channel,
        "router_safe": router_safe,
        "validation_probability": round(validation_probability, 6) if validation_probability is not None else round(probability, 6),
        "validation_probability_policy": "FROZEN_AUC_PRESERVING_OR_NEUTRAL_FAIL_CLOSED_FORECAST_FOR_AUTHORITY_VALIDATION_ONLY",
        "heuristic_probability": round(heuristic, 6), "wilson_low": round(interval_low, 6), "wilson_high": round(interval_high, 6),
        "wilson_neighbors": neighbor_count, "interval_scope": interval_scope, "calibrated": calibrated,
        "trusted": authority_trusted, "authority_trusted": authority_trusted,
        "global_model_trusted": bool(global_model.get("trusted")), "selected_model_trusted": bool(selected_model.get("trusted")),
        "selected_model_scope": selected_scope, "selected_model_family": family if selected_scope != "GLOBAL_POOLED" else "GLOBAL_POOLED",
        "downgrade_trusted": downgrade_trusted, "promotion_trusted": promotion_trusted,
        "PRECONFIRM_MODEL_TRUSTED": authority_trusted, "trust_level": trust_level, "source": source,
        "drift_shrinkage_applied": bool(selected_model.get("valid") and not selected_model.get("trusted") and not anti_lock),
        "anti_discrimination_neutralized": anti_lock, "untrusted_model_shrink": PRECONFIRM_UNTRUSTED_MODEL_SHRINK,
        "training_population": dict(selected_model.get("training_population") or {}),
        "global_training_population": dict(global_model.get("training_population") or {}),
        "family_training_population": dict(family_model.get("training_population") or {}),
        "model_family": family, "event_kind": _preconfirm_event_kind(candidate), "sample_size": global_n,
        "global_sample_size": global_n, "setup_family_sample_size": setup_n, "exact_family_sample_size": exact_n,
        "effective_sample_size": hierarchy.get("effective_sample_size", float(global_n)),
        "auc": selected_model.get("auc"), "global_auc": global_model.get("auc"), "family_auc": family_model.get("auc"),
        "auc_gate": PRECONFIRM_AUC_GATE, "brier": selected_model.get("brier"), "global_brier": global_model.get("brier"), "family_brier": family_model.get("brier"),
        "brier_warning": bool(selected_model.get("brier") is not None and safe_float(selected_model.get("brier")) > PRECONFIRM_BRIER_WARN),
        "authority_gate": dict(authority_gate), "hierarchical_calibration": hierarchy, "precursor_active": precursor_active,
        "decision_authority": "TRUSTED_RECENT_GATE" if authority_trusted else "AUDIT_ONLY_UNTIL_RECENT_TRUST",
        "can_initiate_entry": False, "probability_orientation": int(selected_model.get("probability_orientation") or 1),
        "calibration_auc_raw": selected_model.get("calibration_auc_raw"),
        "calibration_auc_oriented": selected_model.get("calibration_auc_oriented"),
        "discrimination_status": "AUTHORITY_TRUSTED" if authority_trusted else "OOS_VALIDATED_AUDIT_ONLY" if selected_model.get("trusted") else "TEMPORAL_DRIFT",
        # v9.5.28: persist the exact frozen feature vector that produced this forecast.
        # _preconfirm_make_event() reads it from the profile; without this field the
        # event ledger silently stored {}, making every resolved row unusable for
        # logistic/hierarchical retraining while rolling heuristic AUC still looked healthy.
        "features": {name: round(safe_float(features.get(name), 0.0), 6) for name in PRECONFIRM_FEATURE_NAMES},
        "feature_snapshot_complete": all(name in features for name in PRECONFIRM_FEATURE_NAMES),
        "feature_snapshot_count": sum(1 for name in PRECONFIRM_FEATURE_NAMES if name in features),
        "forecast_schema_version": PRECONFIRM_FORECAST_SCHEMA_VERSION,
    }


def _merge_preconfirmation_events(*event_lists: list[Any]) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for events in event_lists:
        for event in events or []:
            if not isinstance(event, dict):
                continue
            normalized = dict(event)
            normalized.setdefault("event_id", normalized.get("id"))
            normalized.setdefault("id", normalized.get("event_id"))
            normalized["status"] = _preconfirm_event_status(normalized)
            normalized["outcome"] = _preconfirm_legacy_outcome(normalized["status"])
            key = str(normalized.get("event_id") or normalized.get("id") or normalized.get("dedup_key") or "").strip()
            if not key:
                continue
            existing = merged.get(key)
            if existing is None:
                merged[key] = normalized
                continue
            # Prefer a terminal/newer representation over a pending mirror copy.
            existing_resolved = _preconfirm_event_status(existing) != "PENDING"
            event_resolved = _preconfirm_event_status(normalized) != "PENDING"
            existing_ts = int(existing.get("resolved_ts") or existing.get("observed_ts") or existing.get("created_ts") or 0)
            event_ts = int(normalized.get("resolved_ts") or normalized.get("observed_ts") or normalized.get("created_ts") or 0)
            if (event_resolved and not existing_resolved) or event_ts >= existing_ts:
                merged[key] = normalized
    return sorted(merged.values(), key=lambda event: int(event.get("observed_ts") or event.get("created_ts") or 0))

def _retain_preconfirmation_events(events: list[Any], cap: int = PRECONFIRM_EMBEDDED_JOURNAL_LIMIT) -> list[dict[str, Any]]:
    """Keep pending lifecycle rows and fill the remaining FIFO room with resolved rows."""
    cleaned = [dict(event) for event in events or [] if isinstance(event, dict)]
    for event in cleaned:
        event.setdefault("event_id", event.get("id"))
        event.setdefault("id", event.get("event_id"))
        event["status"] = _preconfirm_event_status(event)
        event["outcome"] = _preconfirm_legacy_outcome(event["status"])
    pending = [event for event in cleaned if _preconfirm_event_status(event) == "PENDING"]
    resolved = [event for event in cleaned if _preconfirm_event_status(event) != "PENDING"]
    if len(pending) >= cap:
        return pending[-cap:]
    return resolved[-(cap - len(pending)):] + pending


def load_preconfirmation_journal(main_journal: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    """Load the confirmation ledger from the main journal only.

    Journal v2 deliberately removes the sidecar file so the bot has one source
    of truth: signal_journal_v6_4.json.
    """
    source = main_journal if isinstance(main_journal, dict) else load_json(JOURNAL_FILE, {})
    journal = {
        "events": _retain_preconfirmation_events(list(source.get("preconfirmation_events") or [])),
        "model_status": dict(source.get("preconfirmation_model_status") or {}),
        "version": BOT_VERSION,
        "architecture_version": ARCHITECTURE_VERSION,
        "schema_version": "preconfirmation_journal_v9.5_lifecycle_embedded_v2",
        "lifecycle_contract": {
            "created_status": "PENDING",
            "terminal_statuses": ["CONFIRMED", "FAILED", "EXPIRED"],
            "fixed_horizon_minutes": PRECONFIRM_WINDOW_MINUTES,
            "acceptance_closes_required": PRECONFIRM_ACCEPTANCE_CLOSES,
            "calibration_source": "RESOLVED_PRECONFIRMATION_EVENTS_ONLY",
            "closed_trades_used": False,
        },
        "persistence_sources": {
            "mode": "MAIN_JOURNAL_ONLY",
            "main_journal": str(JOURNAL_FILE),
            "merged_event_count": len(source.get("preconfirmation_events") or []),
        },
    }
    return journal


def sync_preconfirmation_to_main_journal(
    preconfirmation_journal: dict[str, Any],
    main_journal: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    target = main_journal if isinstance(main_journal, dict) else load_json(JOURNAL_FILE, {})
    retained = _retain_preconfirmation_events(
        list(preconfirmation_journal.get("events") or []),
        PRECONFIRM_EMBEDDED_JOURNAL_LIMIT,
    )
    pending_count = sum(1 for event in retained if _preconfirm_event_status(event) == "PENDING")
    target["preconfirmation_events"] = retained
    target["preconfirmation_model_status"] = dict(preconfirmation_journal.get("model_status") or {})
    target["preconfirmation_persistence"] = {
        "mode": "MAIN_JOURNAL_ONLY",
        "event_count": len(retained),
        "pending_count": pending_count,
        "resolved_count": len(retained) - pending_count,
        "limit": PRECONFIRM_EMBEDDED_JOURNAL_LIMIT,
        "updated_at": str(preconfirmation_journal.get("updated_at") or iso_now()),
        "disk_synced": True,
    }
    target["journal_version"] = JOURNAL_VERSION
    atomic_json_write(JOURNAL_FILE, target)
    return {
        "synced": True,
        "event_count": len(retained),
        "pending_count": pending_count,
        "resolved_count": len(retained) - pending_count,
    }


def save_preconfirmation_journal(
    journal: dict[str, Any],
    main_journal: Optional[dict[str, Any]] = None,
) -> None:
    journal["updated_at"] = iso_now()
    journal["events"] = _retain_preconfirmation_events(
        list(journal.get("events") or []),
        PRECONFIRM_EMBEDDED_JOURNAL_LIMIT,
    )
    journal["retention_audit"] = {
        "mode": "MAIN_JOURNAL_ONLY_FIFO",
        "max_events": PRECONFIRM_EMBEDDED_JOURNAL_LIMIT,
        "event_count": len(journal["events"]),
    }
    sync_preconfirmation_to_main_journal(journal, main_journal)


def _preconfirm_should_log(candidate: Candidate) -> bool:
    """Every valid directional candidate receives a forecast row.

    The previous implementation only logged confirmation-pending/low-score
    candidates. That left model families visible in signals but absent from the
    precursor ledger, making calibration permanently sample_size=0.
    """
    if not PRECONFIRMATION_LAYER_ENABLED or candidate is None:
        return False
    if str(getattr(candidate, "side", "")).upper() not in {Side.LONG.value, Side.SHORT.value}:
        return False
    if str(getattr(candidate, "hard_reject_reason", "") or "").strip():
        return False
    return True

def _preconfirm_make_event(
    context: dict[str, Any],
    candidate: Candidate,
    profile: dict[str, Any],
    *,
    probability: Optional[float] = None,
    status: str = "PENDING",
) -> dict[str, Any]:
    observation_candle_ts = _preconfirm_as_of_ts(context)
    # OKX candle timestamps are bar-open times. The forecast exists only after
    # the latest confirmed 3M candle has closed, so the lifecycle starts at the
    # candle close rather than three minutes in the past.
    observed_ts = observation_candle_ts + PRECONFIRM_RESOLUTION_BAR_MS
    created_at = iso_now()
    price = safe_float(context.get("price"), 0.0)
    c3 = _preconfirm_candles(context, "3m", observed_ts)
    if c3:
        price = safe_float(c3[-1].close, price)
    atr15 = max(safe_float(context.get("atr15"), 0.0), price * 0.001, 1e-6)
    side = str(candidate.side).upper()
    sign = 1.0 if side == Side.LONG.value else -1.0
    state = getattr(candidate, "confirmation_state", {}) or {}
    anchor = safe_float(
        state.get("anchor"),
        safe_float(state.get("level"), safe_float(candidate.trigger_level, safe_float(candidate.execution_anchor, price))),
    )
    if anchor <= 0:
        anchor = price
    confirmation_level = (
        max(anchor, price + atr15 * PRECONFIRM_CONFIRM_BUFFER_ATR)
        if sign > 0
        else min(anchor, price - atr15 * PRECONFIRM_CONFIRM_BUFFER_ATR)
    )
    invalidation = safe_float(candidate.invalidation_level, 0.0)
    if sign > 0 and (invalidation <= 0 or invalidation >= price):
        invalidation = price - atr15 * PRECONFIRM_INVALIDATION_BUFFER_ATR
    if sign < 0 and invalidation <= price:
        invalidation = price + atr15 * PRECONFIRM_INVALIDATION_BUFFER_ATR
    family = _preconfirm_model_family(candidate)
    thesis_key = str(getattr(candidate, "thesis_key", "") or f"{side}|{candidate.setup_type}|{candidate.ict_model}")
    dedup_key = f"{thesis_key}|{family}"
    event_id = uuid.uuid4().hex[:16]
    canonical_status = str(status or "PENDING").upper()
    event = {
        "event_id": event_id,
        "id": event_id,  # v9.4 compatibility
        "dedup_key": dedup_key,
        "thesis_key": thesis_key,
        "side": side,
        "setup_type": str(candidate.setup_type),
        "setup_family": str(candidate.setup_family).upper(),
        "ict_model": str(candidate.ict_model),
        "model_family": family,
        "event_kind": _preconfirm_event_kind(candidate),
        "bot_version_at_observation": BOT_VERSION,
        "architecture_version_at_observation": ARCHITECTURE_VERSION,
        "feature_schema_version": PRECONFIRM_FEATURE_SCHEMA_VERSION,
        "forecast_schema_version": PRECONFIRM_FORECAST_SCHEMA_VERSION,
        "created_at": created_at,
        "created_ts": observed_ts,
        "observation_candle_ts": observation_candle_ts,
        "observed_at": created_at,
        "observed_ts": observed_ts,
        "resolve_after_ts": observed_ts + PRECONFIRM_WINDOW_MINUTES * 60_000,
        "expires_ts": observed_ts + PRECONFIRM_WINDOW_MINUTES * 60_000,  # compatibility alias
        "resolution_window_minutes": PRECONFIRM_WINDOW_MINUTES,
        "acceptance_required_closes": PRECONFIRM_ACCEPTANCE_CLOSES,
        "observed_price": round_price(price),
        "atr15_at_observation": round(atr15, 8),
        "anchor": round_price(anchor),
        "confirmation_level": round_price(confirmation_level),
        "invalidation_level": round_price(invalidation),
        "probability": round(clamp(safe_float(probability, safe_float(profile.get("probability"), 0.0)), 0.0, 1.0), 6),
        "confirmation_probability": round(clamp(safe_float(probability, safe_float(profile.get("probability"), 0.0)), 0.0, 1.0), 6),
        "validation_probability": round(clamp(safe_float(profile.get("validation_probability"), safe_float(probability, 0.5)), 0.0, 1.0), 6),
        "status": canonical_status,
        "outcome": _preconfirm_legacy_outcome(canonical_status),
        "outcome_contract": "FIXED_45M_WINDOW; FIRST_ACCEPTANCE_VS_INVALIDATION; NO_TERMINAL_EVIDENCE=EXPIRED",
        "features": dict(profile.get("features") or {}),
        "feature_snapshot_complete": bool(
            profile.get("feature_snapshot_complete")
            and all(name in (profile.get("features") or {}) for name in PRECONFIRM_FEATURE_NAMES)
        ),
        "feature_snapshot_count": len(profile.get("features") or {}),
        "estimate_at_observation": {k: v for k, v in profile.items() if k != "features"},
        "signal_link": None,
    }
    return event

def record_preconfirmation_event(
    *,
    candidate: Candidate,
    probability: float,
    status: str = "PENDING",
    context: dict[str, Any],
    journal: dict[str, Any],
    profile: Optional[dict[str, Any]] = None,
) -> Optional[dict[str, Any]]:
    """Append one forecast snapshot for a candidate, with horizon-level dedup."""
    canonical_status = str(status or "PENDING").upper()
    if canonical_status not in PRECONFIRM_VALID_STATUSES:
        raise ValueError(f"Unsupported preconfirmation status: {canonical_status}")
    if canonical_status == "PENDING" and not _preconfirm_should_log(candidate):
        return None
    profile = dict(profile or getattr(candidate, "preconfirmation_profile", {}) or {})
    event = _preconfirm_make_event(
        context,
        candidate,
        profile,
        probability=probability,
        status=canonical_status,
    )
    observed_ts = int(event.get("observed_ts") or 0)
    horizon_ms = PRECONFIRM_WINDOW_MINUTES * 60_000
    for existing in reversed(journal.get("events", []) or []):
        if not isinstance(existing, dict) or str(existing.get("dedup_key") or "") != event["dedup_key"]:
            continue
        existing_ts = int(existing.get("observed_ts") or existing.get("created_ts") or 0)
        # One forecast per thesis/family per fixed horizon. A new event is allowed
        # only after the prior observation window has elapsed.
        if abs(observed_ts - existing_ts) < horizon_ms:
            return existing
    journal.setdefault("events", []).append(event)
    return event


def resolve_preconfirmation_events(
    journal: dict[str, Any],
    context: dict[str, Any],
    candidates: Optional[list[Candidate]] = None,
) -> int:
    """Resolve PENDING events only when their complete 45-minute horizon exists.

    Labels are derived from candles inside the frozen observation window. Closed
    trades are intentionally irrelevant to this lifecycle.
    """
    as_of_candle_ts = _preconfirm_as_of_ts(context)
    data_available_through_ts = as_of_candle_ts + PRECONFIRM_RESOLUTION_BAR_MS
    all_candles = _preconfirm_candles(context, "3m", as_of_candle_ts)
    as_of_ts = data_available_through_ts
    resolved_count = 0
    for event in journal.get("events", []) or []:
        if not isinstance(event, dict) or _preconfirm_event_status(event) != "PENDING":
            continue
        observed_ts = int(event.get("observed_ts") or event.get("created_ts") or 0)
        resolve_after_ts = int(event.get("resolve_after_ts") or event.get("expires_ts") or 0)
        if observed_ts <= 0:
            _preconfirm_set_status(
                event,
                "FAILED",
                reason="missing_observed_ts",
                resolved_ts=as_of_ts,
                outcome_ts=as_of_ts,
                evidence={"data_error": True},
            )
            resolved_count += 1
            continue
        if resolve_after_ts <= observed_ts:
            resolve_after_ts = observed_ts + PRECONFIRM_WINDOW_MINUTES * 60_000
            event["resolve_after_ts"] = resolve_after_ts
            event["expires_ts"] = resolve_after_ts
        if data_available_through_ts < resolve_after_ts:
            continue

        candles = [
            candle for candle in all_candles
            if observed_ts <= int(getattr(candle, "ts", 0) or 0)
            and int(getattr(candle, "ts", 0) or 0) + PRECONFIRM_RESOLUTION_BAR_MS <= resolve_after_ts
        ]
        if not candles:
            _preconfirm_set_status(
                event,
                "EXPIRED",
                reason="resolution_window_elapsed_without_candles",
                resolved_ts=as_of_ts,
                outcome_ts=resolve_after_ts,
                evidence={"directional_close": False, "acceptance": False, "price_moved_direction": False, "thesis_invalidated": False},
            )
            resolved_count += 1
            continue

        side = str(event.get("side") or "").upper()
        sign = 1.0 if side == Side.LONG.value else -1.0
        observed_price = safe_float(event.get("observed_price"), safe_float(candles[0].open, 0.0))
        atr15 = max(safe_float(event.get("atr15_at_observation"), 0.0), observed_price * 0.001, 1e-6)
        confirm_level = safe_float(event.get("confirmation_level"), observed_price + sign * atr15 * PRECONFIRM_CONFIRM_BUFFER_ATR)
        invalidation_level = safe_float(event.get("invalidation_level"), observed_price - sign * atr15 * PRECONFIRM_INVALIDATION_BUFFER_ATR)
        required_closes = max(1, int(event.get("acceptance_required_closes") or PRECONFIRM_ACCEPTANCE_CLOSES))

        directional_close_ts: Optional[int] = None
        acceptance_ts: Optional[int] = None
        invalidation_ts: Optional[int] = None
        acceptance_streak = 0
        max_favorable_price = observed_price
        final_close = safe_float(candles[-1].close, observed_price)

        for candle in candles:
            candle_ts = int(getattr(candle, "ts", 0) or 0)
            close = safe_float(candle.close)
            low = safe_float(candle.low)
            high = safe_float(candle.high)
            directional_close = close >= confirm_level if sign > 0 else close <= confirm_level
            invalidated = low <= invalidation_level if sign > 0 else high >= invalidation_level
            if directional_close:
                directional_close_ts = directional_close_ts or candle_ts
                acceptance_streak += 1
                if acceptance_streak >= required_closes and acceptance_ts is None:
                    acceptance_ts = candle_ts
            else:
                acceptance_streak = 0
            if invalidated and invalidation_ts is None:
                invalidation_ts = candle_ts
            max_favorable_price = max(max_favorable_price, high) if sign > 0 else min(max_favorable_price, low)

        mfe_atr = sign * (max_favorable_price - observed_price) / atr15
        final_move_atr = sign * (final_close - observed_price) / atr15
        price_moved_direction = bool(mfe_atr >= PRECONFIRM_CONFIRM_BUFFER_ATR)
        directional_close_seen = directional_close_ts is not None
        acceptance_seen = acceptance_ts is not None
        thesis_invalidated = invalidation_ts is not None
        evidence = {
            "directional_close": directional_close_seen,
            "directional_close_ts": directional_close_ts,
            "acceptance": acceptance_seen,
            "acceptance_ts": acceptance_ts,
            "acceptance_required_closes": required_closes,
            "price_moved_direction": price_moved_direction,
            "mfe_atr": round(mfe_atr, 6),
            "final_move_atr": round(final_move_atr, 6),
            "thesis_invalidated": thesis_invalidated,
            "invalidation_ts": invalidation_ts,
            "window_candles": len(candles),
            "window_end_ts": resolve_after_ts,
        }

        if thesis_invalidated and (acceptance_ts is None or int(invalidation_ts or 0) <= int(acceptance_ts or 0)):
            status = "FAILED"
            reason = "thesis_invalidated_before_directional_acceptance"
            outcome_ts = invalidation_ts
        elif acceptance_seen and directional_close_seen and price_moved_direction:
            status = "CONFIRMED"
            reason = "directional_close_and_acceptance_completed_within_fixed_window"
            outcome_ts = acceptance_ts
            if invalidation_ts is not None and acceptance_ts is not None and invalidation_ts > acceptance_ts:
                evidence["post_confirmation_invalidation"] = True
        elif thesis_invalidated:
            status = "FAILED"
            reason = "thesis_invalidated_without_valid_acceptance"
            outcome_ts = invalidation_ts
        else:
            status = "EXPIRED"
            reason = "fixed_window_elapsed_without_complete_directional_acceptance"
            outcome_ts = resolve_after_ts

        _preconfirm_set_status(
            event,
            status,
            reason=reason,
            resolved_ts=as_of_ts,
            outcome_ts=outcome_ts,
            resolved_price=final_close,
            evidence=evidence,
        )
        resolved_count += 1
    return resolved_count


def _preconfirm_build_model_status(
    journal: dict[str, Any],
    candidates: Optional[list[Candidate]] = None,
    model_cache: Optional[dict[str, dict[str, Any]]] = None,
) -> dict[str, Any]:
    model_cache = model_cache or {}
    global_model = model_cache.setdefault("__GLOBAL_POOLED__", _preconfirm_build_model(journal, None))
    authority_gate = _preconfirm_authority_gate(journal, global_model)
    global_training_rows = _preconfirm_training_rows(journal)
    global_training_labels = {int(row["label"]) for row in global_training_rows}
    global_has_both_labels = len(global_training_labels) >= 2
    resolved_event_count = sum(
        1 for event in journal.get("events", []) or []
        if isinstance(event, dict) and _preconfirm_event_status(event) in PRECONFIRM_TERMINAL_STATUSES
    )
    expired_event_count = sum(
        1 for event in journal.get("events", []) or []
        if isinstance(event, dict) and _preconfirm_event_status(event) == "EXPIRED"
    )
    resolved_current_feature_events = [
        event for event in (journal.get("events", []) or [])
        if isinstance(event, dict)
        and _preconfirm_event_status(event) in PRECONFIRM_TERMINAL_STATUSES
        and str(event.get("feature_schema_version") or "") == PRECONFIRM_FEATURE_SCHEMA_VERSION
    ]
    feature_complete_current = [
        event for event in resolved_current_feature_events
        if isinstance(event.get("features"), dict)
        and all(name in (event.get("features") or {}) for name in PRECONFIRM_FEATURE_NAMES)
    ]
    resolved_current_forecast_events = [
        event for event in resolved_current_feature_events
        if str(event.get("forecast_schema_version") or "") == PRECONFIRM_FORECAST_SCHEMA_VERSION
    ]
    feature_complete_current_forecast = [
        event for event in resolved_current_forecast_events
        if isinstance(event.get("features"), dict)
        and all(name in (event.get("features") or {}) for name in PRECONFIRM_FEATURE_NAMES)
    ]
    missing_current_forecast_features = max(0, len(resolved_current_forecast_events) - len(feature_complete_current_forecast))
    feature_persistence_integrity = (
        "OBSERVING_NEW_FORECAST_SCHEMA" if not resolved_current_forecast_events
        else "OK" if missing_current_forecast_features == 0
        else "BROKEN_MISSING_FEATURE_SNAPSHOTS"
    )
    families = {
        str(event.get("model_family") or "").upper()
        for event in journal.get("events", []) or []
        if isinstance(event, dict) and str(event.get("model_family") or "").strip()
    }
    candidate_profiles: dict[str, dict[str, Any]] = {}
    for candidate in candidates or []:
        profile = dict(getattr(candidate, "preconfirmation_profile", {}) or {})
        family = str(profile.get("model_family") or _preconfirm_model_family(candidate)).upper()
        if family:
            families.add(family)
            candidate_profiles[family] = profile

    by_family: dict[str, Any] = {}
    for family in sorted(families):
        profile = candidate_profiles.get(family, {})
        hierarchy = _preconfirm_hierarchical_calibration(journal, family, safe_float(profile.get("heuristic_probability"), 0.50))
        by_family[family] = {
            "source": profile.get("source", "RESOLVED_EVENT_LEDGER"),
            "calibrated": bool(profile.get("calibrated", hierarchy.get("calibrated"))),
            "global_sample_size": int(profile.get("global_sample_size") or hierarchy.get("global_sample_size") or 0),
            "setup_family_sample_size": int(profile.get("setup_family_sample_size") or hierarchy.get("setup_family_sample_size") or 0),
            "exact_family_sample_size": int(profile.get("exact_family_sample_size") or hierarchy.get("exact_family_sample_size") or 0),
            "promotion_trusted": bool(
                authority_gate.get("authority_trusted")
                and profile.get("promotion_trusted", hierarchy.get("promotion_trusted"))
            ),
            "pending_events": sum(
                1 for event in journal.get("events", []) or []
                if isinstance(event, dict)
                and str(event.get("model_family") or "").upper() == family
                and _preconfirm_event_status(event) == "PENDING"
            ),
            "resolved_events": sum(
                1 for event in journal.get("events", []) or []
                if isinstance(event, dict)
                and str(event.get("model_family") or "").upper() == family
                and _preconfirm_event_status(event) in PRECONFIRM_TERMINAL_STATUSES
            ),
        }

    return {
        "GLOBAL_POOLED": {
            "trusted": bool(global_model.get("trusted")),
            "execution_authority_trusted": bool(authority_gate.get("authority_trusted")),
            "sample_size": int(global_model.get("sample_size") or 0),
            "calibration_sample_size": len(global_training_rows),
            "resolved_events": resolved_event_count,
            "expired_events": expired_event_count,
            "expired_label_mode": PRECONFIRM_EXPIRED_LABEL_MODE,
            "auc": global_model.get("auc"),
            "brier": global_model.get("brier"),
            "trust_level": global_model.get("trust_level", "BOOTSTRAP"),
            "logistic_floor": PRECONFIRM_MIN_TRAIN_ROWS,
            "hierarchical_floor": PRECONFIRM_GLOBAL_MIN_CALIBRATION_ROWS,
            "weak_calibration_floor": PRECONFIRM_WEAK_MIN_CALIBRATION_ROWS,
            "calibration_tier": (
                "POOLED_LOGISTIC_VALIDATED" if global_model.get("trusted")
                else "HIERARCHICAL_EMPIRICAL_BAYES" if len(global_training_rows) >= PRECONFIRM_GLOBAL_MIN_CALIBRATION_ROWS and global_has_both_labels
                else "EARLY_WEAK_BAYES" if len(global_training_rows) >= PRECONFIRM_WEAK_MIN_CALIBRATION_ROWS and global_has_both_labels
                else "HEURISTIC_ONLY"
            ),
            "training_source": "RESOLVED_PRECONFIRMATION_EVENTS_ONLY",
            "training_population": dict(global_model.get("training_population") or {}),
            "resolved_current_feature_schema_events": len(resolved_current_feature_events),
            "feature_complete_current_feature_schema_events": len(feature_complete_current),
            "resolved_current_forecast_schema_events": len(resolved_current_forecast_events),
            "feature_complete_current_forecast_schema_events": len(feature_complete_current_forecast),
            "missing_feature_snapshots_current_forecast_schema": missing_current_forecast_features,
            "feature_persistence_integrity": feature_persistence_integrity,
            "legacy_missing_feature_rows_are_not_current_authority": True,
            "forecast_schema_version": PRECONFIRM_FORECAST_SCHEMA_VERSION,
            "closed_trades_used": False,
        },
        "AUTHORITY_GATE": authority_gate,
        "BY_MODEL_FAMILY": by_family,
    }

def apply_confirmation_probability_layer(
    context: dict[str, Any],
    candidates: list[Candidate],
    main_journal: Optional[dict[str, Any]] = None,
) -> list[Candidate]:
    if not PRECONFIRMATION_LAYER_ENABLED:
        for candidate in candidates:
            candidate.preconfirmation_profile = {"available": False, "reason": "disabled", "can_initiate_entry": False}
            candidate.confirmation_probability = 0.0
        return candidates

    journal = load_preconfirmation_journal(main_journal)
    resolve_preconfirmation_events(journal, context, candidates)
    model_cache: dict[str, dict[str, Any]] = {}
    # Persist the authority gate before profiles are built. Rebuilding later on
    # the same validation epoch cannot increment the consecutive-pass streak.
    journal["model_status"] = _preconfirm_build_model_status(journal, None, model_cache)
    as_of_ts = _preconfirm_as_of_ts(context)

    for candidate in candidates:
        features = _preconfirm_feature_vector(context, candidate, journal, as_of_ts=as_of_ts)
        profile = _preconfirm_estimate(journal, candidate, features, model_cache)
        candidate.confirmation_probability = safe_float(profile.get("probability"), 0.0)
        candidate.preconfirmation_profile = profile
        candidate.score_components["preconfirmation"] = profile
        candidate.score_components["confirmation_probability"] = candidate.confirmation_probability

        # Lifecycle creation happens immediately after the forecast is calculated.
        event = record_preconfirmation_event(
            candidate=candidate,
            probability=candidate.confirmation_probability,
            status="PENDING",
            context=context,
            journal=journal,
            profile=profile,
        )
        if event is not None:
            profile["ledger_event_id"] = str(event.get("event_id") or event.get("id") or "")
            profile["ledger_event_status"] = _preconfirm_event_status(event)

    journal["model_status"] = _preconfirm_build_model_status(journal, candidates, model_cache)
    save_preconfirmation_journal(journal, main_journal)
    return candidates


def link_preconfirmation_event_to_signal(
    journal: dict[str, Any],
    candidate: Optional[Candidate],
    signal_id: str,
    action: str,
) -> str:
    """Attach the frozen precursor event to the exact published signal."""
    if candidate is None or not signal_id:
        return ""
    profile = getattr(candidate, "preconfirmation_profile", {}) or {}
    event_id = str(profile.get("ledger_event_id") or "").strip()
    if not event_id:
        return ""
    for event in reversed(journal.get("preconfirmation_events", []) or []):
        if not isinstance(event, dict):
            continue
        current_id = str(event.get("event_id") or event.get("id") or "").strip()
        if current_id != event_id:
            continue
        event["signal_link"] = signal_id
        event["signal_id"] = signal_id
        event["signal_action"] = str(action or "")
        event["linked_at"] = iso_now()
        event["bot_version_at_signal"] = BOT_VERSION
        event["architecture_version_at_signal"] = ARCHITECTURE_VERSION
        return event_id
    return ""


def link_preconfirmation_event_to_trade(
    journal: dict[str, Any],
    active: Optional[ActiveTrade],
    result_class: str,
    close_action: str,
) -> str:
    """Complete event -> signal -> trade lineage after the trade closes."""
    if active is None:
        return ""
    event_id = str(getattr(active, "preconfirmation_event_id", "") or "").strip()
    if not event_id:
        return ""
    for event in reversed(journal.get("preconfirmation_events", []) or []):
        if not isinstance(event, dict):
            continue
        current_id = str(event.get("event_id") or event.get("id") or "").strip()
        if current_id != event_id:
            continue
        event["trade_link"] = str(getattr(active, "id", "") or "")
        event["trade_id"] = str(getattr(active, "id", "") or "")
        event["trade_result_class"] = str(result_class or "")
        event["trade_close_action"] = str(close_action or "")
        event["trade_linked_at"] = iso_now()
        return event_id
    return ""



# v9.5.49 Hidden Gate Sweep: classify every execution blocker source.
# Hard blockers are execution safety conditions. Quality/advisory signals cannot veto.
HIDDEN_GATE_ALLOWED_HARD_BLOCKERS = {
    "INVALIDATION",
    "RISK",
    "DATA",
    "EXECUTION_FAILURE",
}

HIDDEN_GATE_FORBIDDEN_VETO_SOURCES = {
    "SCORE",
    "CALIBRATION",
    "PRECONFIRMATION",
    "ADVISORY_MODEL",
    "ROUTER_PREFERENCE",
}

def hidden_gate_sweep_audit(blocking: list[str], allow_execution: bool = False) -> dict[str, object]:
    classified = [classify_execution_blocker(x) for x in (blocking or [])]
    forbidden = [x for x in classified if x in HIDDEN_GATE_FORBIDDEN_VETO_SOURCES]
    hard = [x for x in classified if x in HIDDEN_GATE_ALLOWED_HARD_BLOCKERS]
    counter_keys = {
        "SCORE": "canonical_score_reject_attempts",
        "CALIBRATION": "calibration_reject_attempts",
        "PRECONFIRMATION": "preconfirm_reject_attempts",
    }
    for source in forbidden:
        key = counter_keys.get(source)
        if key:
            DEAD_GATE_REMOVAL_AUDIT[key] = int(DEAD_GATE_REMOVAL_AUDIT.get(key, 0) or 0) + 1
    DEAD_GATE_REMOVAL_AUDIT["quality_limitations_observed"] = int(
        DEAD_GATE_REMOVAL_AUDIT.get("quality_limitations_observed", 0) or 0
    ) + max(0, len(classified) - len(hard))
    return {
        "blocking_count": len(classified),
        "hard_blockers": hard,
        "forbidden_veto_sources": forbidden,
        "execution_allowed": bool(allow_execution),
        "single_authority": "FINAL_EXECUTION_AUTHORITY",
        "status": "CLEAN" if not forbidden else "LEGACY_GATE_FOUND",
    }

def _preconfirm_stage_gate(
    state: str,
    candidate: Candidate,
    evaluation: EvaluationBundle,
    required: Optional[str],
    blocking: list[str],
    warnings: list[str],
) -> tuple[str, Optional[str], list[str], list[str], dict[str, Any]]:
    profile = evaluation.preconfirmation or {}
    calibrated = bool(profile.get("calibrated") or profile.get("trusted"))
    requested_downgrade_authority = bool(profile.get("downgrade_trusted") or profile.get("trusted"))
    # A bootstrap/hierarchical estimate may inform audit, but it must not veto
    # a live path until the pooled model passes AUC/Brier trust gates.
    downgrade_trusted = bool(profile.get("trusted"))
    promotion_trusted = bool(profile.get("trusted") and profile.get("promotion_trusted", True))
    audit = {
        "hidden_gate_policy": "PRECONFIRMATION_AUDIT_ONLY_NO_VETO",
        "applied": False,
        "calibrated": calibrated,
        "trusted": bool(profile.get("trusted")),
        "downgrade_trusted": downgrade_trusted,
        "requested_downgrade_authority": requested_downgrade_authority,
        "downgrade_authority_policy": "GLOBAL_PLUS_CURRENT_SCHEMA_ROLLING_TRUST",
        "promotion_trusted": promotion_trusted,
        "precursor_active": bool(profile.get("precursor_active")),
        "probability": safe_float(profile.get("probability"), 0.0),
        "can_initiate_entry": False,
        "policy": "authority requires global trust, current-schema rolling metrics and consecutive validation epochs; otherwise probability is audit-only; never execution veto",
    }
    setup_shadow = ((getattr(candidate, "score_components", {}) or {}).get("time_of_day_shadow") or {})
    if setup_shadow.get("shadow_active"):
        audit["effect"] = "SETUP_SHADOW_SUPERSEDES_PRECONFIRMATION"
        audit["setup_shadow"] = dict(setup_shadow)
        audit["trusted"] = False
        audit["downgrade_trusted"] = False
        audit["promotion_trusted"] = False
        return state, required, blocking, warnings, audit
    if not calibrated or not profile.get("precursor_active"):
        return state, required, blocking, warnings, audit
    probability = safe_float(profile.get("probability"), 0.0)
    probe_profile = fresh_probe_candidate_profile(candidate)
    audit["applied"] = True
    audit["fresh_probe_eligible"] = bool(probe_profile.get("eligible"))
    executable_states = {
        EntryStage.PROBE.value,
        EntryStage.ACCEPTANCE.value,
        EntryStage.RETEST_ADD.value,
        EntryStage.CORE.value,
        EntryStage.ADD_POSITION.value,
    }
    if (
        downgrade_trusted
        and probability <= PRECONFIRM_PROBE_WAIT_PROBABILITY
        and state in executable_states
        and probe_profile.get("eligible")
    ):
        # v9.5.47: preconfirmation is not an execution veto.
        # Preserve visibility as audit only.
        audit["effect"] = "PRECONFIRM_LOW_PROBABILITY_AUDIT_ONLY"
        warnings.append("PRECONFIRM_LOW_NO_EXECUTION_BLOCK")
    elif (
        promotion_trusted
        and probability >= PRECONFIRM_PROBE_MIN_PROBABILITY
        and probe_profile.get("eligible")
        and not bool(getattr(candidate, "confirmation_pending", False))
        and state in {ExecutiveDecisionState.WATCH.value, ExecutiveDecisionState.EARLY_SIGNAL.value, ExecutiveDecisionState.WAIT_CONFIRMATION.value}
        and evaluation.philosophy.recommendation in {"ACCEPT", "ACCEPT_STAGED"}
        and not evaluation.conflict_report.actual_conflict
        and not evaluation.conflict_report.capital_blocked
        and evaluation.timing_quality >= 45
        and evaluation.entry_quality >= 42
        and evaluation.trade_quality >= 55
    ):
        state = EntryStage.PROBE.value
        required = None
        blocking = [reason for reason in blocking if reason not in {"CANONICAL_SCORE_BELOW_RISKY"}]
        warnings.append("PRECONFIRM_HIGH_PROBABILITY_FRESH_PROBE_ONLY")
        audit["effect"] = "PROMOTE_EXISTING_FRESH_PROBE_PATH"
    else:
        audit["effect"] = "CALIBRATED_AUDIT_ONLY" if calibrated else "AUDIT_ONLY"
        if calibrated and not promotion_trusted and probability >= PRECONFIRM_PROBE_MIN_PROBABILITY:
            warnings.append("PRECONFIRM_HIGH_BUT_BOOTSTRAP_NO_PROMOTION")
    return state, required, blocking, warnings, audit

def _preconfirm_telegram_line(candidate: Optional[Candidate]) -> str:
    profile = getattr(candidate, "preconfirmation_profile", {}) if candidate else {}
    if not profile or not profile.get("available"):
        return ""
    probability = safe_float(profile.get("probability"), 0.0) * 100.0
    low = safe_float(profile.get("wilson_low"), 0.0) * 100.0
    high = safe_float(profile.get("wilson_high"), 1.0) * 100.0
    global_n = int(profile.get("global_sample_size") or profile.get("sample_size") or 0)
    exact_n = int(profile.get("exact_family_sample_size") or 0)
    if profile.get("trusted"):
        gate = profile.get("authority_gate") or {}
        label = (
            f"authority trusted, recent n={int(gate.get('recent_sample_size') or 0)}, "
            f"AUC={safe_float(gate.get('recent_auc'), 0.0):.2f}"
        )
    elif profile.get("global_model_trusted"):
        gate = profile.get("authority_gate") or {}
        label = (
            f"pooled logistic audit-only, current-schema n={int(gate.get('current_schema_resolved_events') or 0)}, "
            f"global AUC={safe_float(profile.get('auc'), 0.0):.2f}"
        )
    elif profile.get("calibrated"):
        label = f"hierarchical bootstrap, global n={global_n}, exact n={exact_n}"
    else:
        label = f"heuristic only, global n={global_n}"
    return f"<b>Ймовірність підтвердження:</b> {probability:.0f}% | CI {low:.0f}–{high:.0f}% ({html.escape(label)})"






















