def compute_liquidity_ladder_execution_audit(journal: dict[str, Any]) -> dict[str, Any]:
    """Summarize route geometry separately from raw and selected execution facts."""
    row = dict(((((journal or {}).get("setup_lifecycle_counters") or {}).get("detector_reachability") or {}).get(SetupType.LIQUIDITY_LADDER.value) or {}))
    path_true = dict(row.get("path_true_counts") or {})
    path_obs = dict(row.get("path_observation_counts") or {})
    path_rates = {
        name: {
            "observations": int(path_obs.get(name) or 0),
            "true": int(path_true.get(name) or 0),
            "true_rate": round(int(path_true.get(name) or 0) / max(int(path_obs.get(name) or 0), 1), 6),
        }
        for name in sorted(path_obs)
    }
    reasons = dict(row.get("current_schema_diagnostic_reason_counts") or {})
    conditions = _reachability_rate_summary(row)
    live_path = path_rates.get("LIVE_3M_AVAILABLE") or {}
    route_condition = conditions.get("route_active") or {}
    stale_ready_count = int(reasons.get("SCAN_STAGE_READY_BUT_TRIGGER_AGE_EXPIRED") or 0)
    raw_live_count = int(reasons.get("RAW_LIVE_3M_TRIGGER_AVAILABLE") or 0)
    return {
        "current_schema_evaluated": int(row.get("current_schema_evaluated") or 0),
        "current_schema_fired": int(row.get("current_schema_fired") or 0),
        "conditions": conditions,
        "paths": path_rates,
        "diagnostic_reason_counts": reasons,
        "margin_statistics": dict(row.get("margin_statistics") or {}),
        "health_status": str(row.get("health_status") or "OBSERVING"),
        "predicate_schema_version": str(row.get("predicate_schema_version") or ""),
        "last_diagnostics": dict(((row.get("last_observation") or {}).get("diagnostics") or {})),
        "interpretation_flags": {
            "route_geometry_often_inactive": bool(int(route_condition.get("observations") or 0) >= 20 and safe_float(route_condition.get("false_rate"), 0.0) >= 0.80),
            "raw_live_3m_never_observed": bool(int(live_path.get("observations") or 0) >= 20 and int(live_path.get("true") or 0) == 0),
            "stale_ready_stage_observed": stale_ready_count > 0,
            "raw_live_3m_observed": raw_live_count > 0,
            "priority_preemption_is_separate_from_raw_trigger": True,
            "model_local_3m_is_first_class_confirmation": bool((path_rates.get("MODEL_LOCAL_3M_AVAILABLE") or {}).get("true", 0)),
            "legacy_live_3m_staleness_does_not_make_ladder_dormant": True,
        },
        "authority": "AUDIT_ONLY_NO_EXECUTION_POLICY_CHANGE",
        "schema_version": "liquidity_ladder_execution_audit_v9.5.27_model_local_priority",
        "updated_at": iso_now(),
    }



def _fresh_execution_outcome_target_setups() -> frozenset[str]:
    return frozenset({
        SetupType.BREAKOUT_RETEST.value,
        SetupType.FRESH_BASE_CONTINUATION.value,
        SetupType.PULLBACK_CONTINUATION.value,
        SetupType.MOMENTUM_NO_PULLBACK_CONTINUATION.value,
        SetupType.FAILED_BREAKOUT_SHORT.value,
    })


def _fresh_execution_outcome_anchor(row: dict[str, Any], context: dict[str, Any]) -> tuple[float, str]:
    diagnostics = dict(row.get("diagnostics") or {})
    setup = str(row.get("setup_type") or "")
    profile = dict(diagnostics.get("profile") or {})
    if setup == SetupType.FAILED_BREAKOUT_SHORT.value:
        profile = dict(diagnostics.get("model_local_3m") or profile)
    if setup == SetupType.MOMENTUM_NO_PULLBACK_CONTINUATION.value:
        momentum_anchor = dict(profile.get("momentum_execution_anchor") or diagnostics.get("selected_anchor") or {})
        value = safe_float(momentum_anchor.get("anchor"), safe_float(profile.get("execution_anchor"), 0.0))
        return value, str(momentum_anchor.get("anchor_source") or momentum_anchor.get("source") or "MOMENTUM_CURRENT_ANCHOR")
    for key in ("anchor", "entry_anchor", "breakout_level", "resistance", "level"):
        value = safe_float(profile.get(key), 0.0)
        if value > 0:
            return value, str(profile.get("anchor_source") or profile.get("source") or key.upper())
    return safe_float(context.get("price"), 0.0), "OBSERVED_PRICE_FALLBACK"


def record_fresh_execution_outcome_events(
    journal: dict[str, Any], context: dict[str, Any], reachability_rows: list[dict[str, Any]],
) -> int:
    """Record one market path per side/anchor/time episode, with setup memberships.

    Multiple setup labels may recognize the same underlying move. v9.5.30 merges
    those memberships instead of counting the same future MFE/MAE path twice.
    """
    targets = _fresh_execution_outcome_target_setups()
    rows = [dict(row) for row in (reachability_rows or []) if isinstance(row, dict) and bool(row.get("fired")) and str(row.get("setup_type") or "") in targets]
    if not rows:
        return 0
    c3 = _recent_confirmed(((context.get("candles") or {}).get("3m") or []), 6)
    if not c3:
        return 0
    observation_candle_ts = int(c3[-1].ts)
    observed_ts = observation_candle_ts + PRECONFIRM_RESOLUTION_BAR_MS
    observed_price = safe_float(c3[-1].close, safe_float(context.get("price"), 0.0))
    atr15 = max(safe_float(context.get("atr15"), 0.0), observed_price * 0.001, 1e-6)
    store = journal.setdefault("fresh_execution_outcome_events", [])
    added = 0
    bucket_ms = FRESH_EXECUTION_OUTCOME_EPISODE_BUCKET_MINUTES * 60_000
    anchor_step = max(atr15 * FRESH_EXECUTION_OUTCOME_ANCHOR_BUCKET_ATR, observed_price * 0.0005, 1e-6)
    for row in rows:
        setup = str(row.get("setup_type") or "")
        side = str(row.get("side") or "").upper()
        if side not in {Side.LONG.value, Side.SHORT.value}:
            continue
        anchor, anchor_source = _fresh_execution_outcome_anchor(row, context)
        anchor_bucket = int(round(anchor / anchor_step)) if anchor > 0 else 0
        time_bucket = observed_ts // max(bucket_ms, 1)
        market_episode_key = f"{side}|A{anchor_bucket}|T{time_bucket}"
        duplicate = next((
            event for event in reversed(store)
            if isinstance(event, dict)
            and str(event.get("market_episode_key") or event.get("episode_key") or "") == market_episode_key
            and str(event.get("status") or "PENDING") in {"PENDING", "RESOLVED"}
        ), None)
        if duplicate:
            memberships = list(dict.fromkeys([str(x) for x in (duplicate.get("setup_types") or [duplicate.get("setup_type")]) if x] + [setup]))
            duplicate["setup_types"] = memberships
            duplicate["cross_setup_membership_count"] = len(memberships)
            duplicate.setdefault("setup_anchor_sources", {})[setup] = anchor_source
            continue
        event_id = uuid.uuid4().hex[:16]
        store.append({
            "event_id": event_id,
            "episode_key": market_episode_key,
            "market_episode_key": market_episode_key,
            "setup_type": setup,
            "setup_types": [setup],
            "cross_setup_membership_count": 1,
            "setup_anchor_sources": {setup: anchor_source},
            "side": side,
            "observed_at": iso_now(),
            "observation_candle_ts": observation_candle_ts,
            "observed_ts": observed_ts,
            "resolve_after_ts": observed_ts + FRESH_EXECUTION_OUTCOME_HORIZON_MINUTES * 60_000,
            "horizon_minutes": FRESH_EXECUTION_OUTCOME_HORIZON_MINUTES,
            "observed_price": round_price(observed_price),
            "atr15_at_observation": round(atr15, 8),
            "execution_anchor": round_price(anchor),
            "anchor_source": anchor_source,
            "status": "PENDING",
            "source_reachability_schema": str(row.get("schema_version") or DETECTOR_REACHABILITY_SCHEMA_VERSION),
            "bot_version_at_observation": BOT_VERSION,
            "architecture_version_at_observation": ARCHITECTURE_VERSION,
            "counterfactual_pnl_claimed": False,
            "authority": "AUDIT_ONLY_NO_THRESHOLD_WEIGHT_SIZING_OR_ENTRY_MUTATION",
            "schema_version": "fresh_execution_outcome_event_v9.5.30_cross_setup_market_episode",
        })
        added += 1
    if len(store) > FRESH_EXECUTION_OUTCOME_LEDGER_LIMIT:
        del store[:-FRESH_EXECUTION_OUTCOME_LEDGER_LIMIT]
    return added

def resolve_fresh_execution_outcome_events(journal: dict[str, Any], context: dict[str, Any]) -> int:
    store = journal.get("fresh_execution_outcome_events") or []
    if not store:
        return 0
    all_candles = sorted(
        [c for c in ((context.get("candles") or {}).get("3m") or []) if getattr(c, "confirmed", True)],
        key=lambda c: int(getattr(c, "ts", 0) or 0),
    )
    if not all_candles:
        return 0
    available_through = int(all_candles[-1].ts) + PRECONFIRM_RESOLUTION_BAR_MS
    resolved = 0
    for event in store:
        if not isinstance(event, dict) or str(event.get("status") or "PENDING") != "PENDING":
            continue
        observed_ts = int(event.get("observed_ts") or 0)
        resolve_after_ts = int(event.get("resolve_after_ts") or 0)
        if observed_ts <= 0 or resolve_after_ts <= observed_ts or available_through < resolve_after_ts:
            continue
        candles = [
            c for c in all_candles
            if int(getattr(c, "ts", 0) or 0) >= observed_ts
            and int(getattr(c, "ts", 0) or 0) + PRECONFIRM_RESOLUTION_BAR_MS <= resolve_after_ts
        ]
        if not candles:
            event.update({
                "status": "NO_DATA",
                "resolved_at": iso_now(),
                "resolved_ts": resolve_after_ts,
                "resolution_reason": "HORIZON_ELAPSED_WITHOUT_3M_CANDLES",
            })
            resolved += 1
            continue
        side = str(event.get("side") or "").upper()
        sign = 1.0 if side == Side.LONG.value else -1.0
        observed_price = safe_float(event.get("observed_price"), safe_float(candles[0].open, 0.0))
        atr15 = max(safe_float(event.get("atr15_at_observation"), 0.0), observed_price * 0.001, 1e-6)
        if sign > 0:
            favorable_price = max(safe_float(c.high) for c in candles)
            adverse_price = min(safe_float(c.low) for c in candles)
            mfe_atr = (favorable_price - observed_price) / atr15
            mae_atr = (observed_price - adverse_price) / atr15
        else:
            favorable_price = min(safe_float(c.low) for c in candles)
            adverse_price = max(safe_float(c.high) for c in candles)
            mfe_atr = (observed_price - favorable_price) / atr15
            mae_atr = (adverse_price - observed_price) / atr15
        final_close = safe_float(candles[-1].close, observed_price)
        final_move_atr = sign * (final_close - observed_price) / atr15
        total_excursion = max(mfe_atr, 0.0) + max(mae_atr, 0.0)
        event.update({
            "status": "RESOLVED",
            "resolved_at": iso_now(),
            "resolved_ts": resolve_after_ts,
            "window_candles": len(candles),
            "mfe_atr": round(max(mfe_atr, 0.0), 6),
            "mae_atr": round(max(mae_atr, 0.0), 6),
            "final_move_atr": round(final_move_atr, 6),
            "path_dominance_atr": round(max(mfe_atr, 0.0) - max(mae_atr, 0.0), 6),
            "mfe_share_of_total_excursion": round(max(mfe_atr, 0.0) / max(total_excursion, 1e-9), 6),
            "favorable_price": round_price(favorable_price),
            "adverse_price": round_price(adverse_price),
            "final_price": round_price(final_close),
            "counterfactual_pnl_claimed": False,
            "resolution_reason": "FIXED_HORIZON_DIRECTIONAL_PATH_OBSERVED",
        })
        resolved += 1
    return resolved


def compute_fresh_execution_outcome_audit(journal: dict[str, Any]) -> dict[str, Any]:
    events = [event for event in (journal.get("fresh_execution_outcome_events") or []) if isinstance(event, dict)]
    def memberships(event: dict[str, Any]) -> list[str]:
        values = [str(x) for x in (event.get("setup_types") or []) if str(x)]
        if not values and event.get("setup_type"):
            values = [str(event.get("setup_type"))]
        return list(dict.fromkeys(values))
    by_setup: dict[str, Any] = {}
    for setup in sorted(_fresh_execution_outcome_target_setups()):
        scoped = [event for event in events if setup in memberships(event)]
        # old pre-v9.5.30 rows can duplicate the same path. Collapse only for audit maturity.
        unique_map: dict[str, dict[str, Any]] = {}
        for event in scoped:
            key = str(event.get("market_episode_key") or "")
            if not key:
                # legacy key begins with setup|side; strip setup for best-effort lineage.
                legacy = str(event.get("episode_key") or event.get("event_id") or "")
                parts = legacy.split("|")
                key = "|".join(parts[1:]) if len(parts) > 3 else legacy
            unique_map.setdefault(key, event)
        unique = list(unique_map.values())
        resolved = [event for event in unique if str(event.get("status") or "") == "RESOLVED"]
        pending = [event for event in unique if str(event.get("status") or "PENDING") == "PENDING"]
        mfe = [safe_float(event.get("mfe_atr"), 0.0) for event in resolved]
        mae = [safe_float(event.get("mae_atr"), 0.0) for event in resolved]
        final = [safe_float(event.get("final_move_atr"), 0.0) for event in resolved]
        dominance = [safe_float(event.get("path_dominance_atr"), 0.0) for event in resolved]
        by_setup[setup] = {
            "raw_membership_observations": len(scoped),
            "unique_market_episodes": len(unique),
            "cross_setup_or_legacy_duplicates_removed_for_maturity": max(0, len(scoped) - len(unique)),
            "resolved": len(resolved),
            "pending": len(pending),
            "mean_mfe_atr": round(mean(mfe), 6) if mfe else None,
            "median_mfe_atr": round(median(mfe), 6) if mfe else None,
            "mean_mae_atr": round(mean(mae), 6) if mae else None,
            "median_mae_atr": round(median(mae), 6) if mae else None,
            "mean_final_move_atr": round(mean(final), 6) if final else None,
            "positive_final_move_rate": round(sum(value > 0 for value in final) / len(final), 6) if final else None,
            "mfe_exceeds_mae_rate": round(sum(m > a for m, a in zip(mfe, mae)) / len(resolved), 6) if resolved else None,
            "mean_path_dominance_atr": round(mean(dominance), 6) if dominance else None,
        }
    unique_market_keys = set()
    for event in events:
        key = str(event.get("market_episode_key") or "")
        if not key:
            legacy = str(event.get("episode_key") or event.get("event_id") or "")
            parts = legacy.split("|")
            key = "|".join(parts[1:]) if len(parts) > 3 else legacy
        unique_market_keys.add(key)
    return {
        "events_total": len(events),
        "unique_market_episodes_total": len(unique_market_keys),
        "cross_setup_duplicate_rows_or_memberships": max(0, len(events) - len(unique_market_keys)),
        "by_setup": by_setup,
        "horizon_minutes": FRESH_EXECUTION_OUTCOME_HORIZON_MINUTES,
        "interpretation": "PROSPECTIVE MARKET-EPISODE PATH EVIDENCE; CROSS-SETUP DUPLICATES DO NOT INFLATE MATURITY; NOT PNL",
        "authority": "AUDIT_ONLY_NO_THRESHOLD_WEIGHT_SIZING_OR_ENTRY_MUTATION",
        "schema_version": "fresh_execution_outcome_audit_v9.5.30_cross_setup_episode_dedup",
        "updated_at": iso_now(),
    }

def compute_fresh_execution_conversion_audit(journal: dict[str, Any]) -> dict[str, Any]:
    reachability=((((journal or {}).get("setup_lifecycle_counters") or {}).get("detector_reachability") or {}))
    setup_types=(SetupType.BREAKOUT_RETEST.value,SetupType.FRESH_BASE_CONTINUATION.value,SetupType.PULLBACK_CONTINUATION.value,SetupType.MOMENTUM_NO_PULLBACK_CONTINUATION.value,SetupType.FAILED_BREAKOUT_SHORT.value)
    setups={}
    for setup in setup_types:
        row=dict(reachability.get(setup) or {})
        stored_schema=str(row.get("predicate_schema_version") or "")
        schema_current=stored_schema==DETECTOR_REACHABILITY_SCHEMA_VERSION
        setups[setup]={
            "current_schema_evaluated":int(row.get("current_schema_evaluated") or 0) if schema_current else 0,
            "current_schema_fired":int(row.get("current_schema_fired") or 0) if schema_current else 0,
            "stored_pre_migration_evaluated":int(row.get("current_schema_evaluated") or 0) if not schema_current else 0,
            "stored_pre_migration_fired":int(row.get("current_schema_fired") or 0) if not schema_current else 0,
            "stored_predicate_schema_version":stored_schema,
            "expected_predicate_schema_version":DETECTOR_REACHABILITY_SCHEMA_VERSION,
            "schema_current":schema_current,
            "conditions":_reachability_rate_summary(row) if schema_current else {},
            "blockers":dict(row.get("current_schema_blocker_counts") or {}) if schema_current else {},
            "health_status":str(row.get("health_status") or "OBSERVING") if schema_current else "AWAITING_V9_5_28_SCHEMA_MIGRATION",
            "last_diagnostics":dict(((row.get("last_observation") or {}).get("diagnostics") or {})) if schema_current else {},
        }
    return {
        "setups":setups,
        "contract":"CURRENT_CONFIRMED_MODEL_LOCAL_EVIDENCE; PENDING_LEASE_IS_NON_EXECUTABLE; STALE_SCAN_EVENT_CANNOT_RESET_CLOCK; OLD_SCHEMA_COUNTERS_ARE_NOT_CURRENT_AUTHORITY",
        "authority":"AUDIT_ONLY_NO_THRESHOLD_MUTATION",
        "schema_version":"fresh_execution_conversion_audit_v9.5.28",
        "updated_at":iso_now(),
    }


def compute_execution_source_authority_audit(journal: dict[str, Any]) -> dict[str, Any]:
    """Audit realized economics by setup -> execution_source -> side."""
    keys: set[tuple[str, str]] = set()
    for trade in journal.get("trades", []) or []:
        if not isinstance(trade, dict) or _journal_result_r(trade) is None:
            continue
        setup_type = str(trade.get("setup_type") or "")
        source = str(trade.get("execution_source") or "").upper()
        if setup_type and source:
            keys.add((setup_type, source))
    rows = []
    for setup_type, source in sorted(keys):
        pooled = execution_source_trade_statistics(journal, setup_type, source)
        side_rows = {}
        guard_modes = {}
        for side in (Side.LONG.value, Side.SHORT.value):
            side_rows[side] = execution_source_trade_statistics(journal, setup_type, source, side)
            dummy = Candidate(
                side=side, setup_type=setup_type, setup_family=SetupFamily.NONE.value,
                raw_score=0, final_score=0, execution_source=source,
            )
            guard = execution_source_empirical_profile(journal, dummy)
            guard_modes[side] = {
                "mode": guard.get("mode"),
                "guard_active": bool(guard.get("guard_active")),
                "evidence_scope": guard.get("evidence_scope"),
                "expectancy_r": guard.get("expectancy_r"),
                "risk_cap_pct": guard.get("risk_cap_pct"),
                "selection_cap": guard.get("selection_cap"),
            }
        rows.append({
            "setup_type": setup_type,
            "execution_source": source,
            "pooled": pooled,
            "by_side": side_rows,
            "authority_by_side": guard_modes,
        })
    return {
        "rows": rows,
        "row_count": len(rows),
        "authority_key": "setup_type + side + execution_source",
        "negative_lane_can_borrow_parent_reputation": False,
        "raw_quality_authority": False,
        "schema_version": "execution_source_authority_audit_v9.5.29",
        "updated_at": iso_now(),
    }


def compute_calibration_authority_audit(journal: dict[str, Any]) -> dict[str, Any]:
    # Always recompute with the running code. Persisted learning_status may have
    # been produced by an older schema and is evidence, not current authority.
    status=compute_learning_status(journal)
    by_setup=dict(status.get("by_setup") or {})
    validated=sorted(setup for setup,row in by_setup.items() if bool((row or {}).get("learned_authority_allowed")))
    directional=sorted(
        f"{setup}:{side}"
        for setup,row in by_setup.items()
        for side in ((row or {}).get("directional_authority_sides") or [])
    )
    acceptance_short_confirmed = execution_source_trade_statistics(
        journal, SetupType.ACCEPTANCE_RETEST_CONTINUATION.value, ExecutionSource.ACCEPTANCE_RETEST.value, Side.SHORT.value
    )
    keep_directional_split = bool(
        int(acceptance_short_confirmed.get("closed_trades") or 0) >= SETUP_CALIBRATION_SIDE_AUDIT_MIN_TRADES
        and safe_float(acceptance_short_confirmed.get("expectancy_r"), 0.0) < 0.0
    )
    return {
        "global_model_fit_ready":bool(status.get("global_ready")),
        "global_theoretical_learned_weight":safe_float(status.get("global_learned_weight"),0.0),
        "global_validation":dict(status.get("validation") or {}),
        "validated_exact_setups":validated,
        "validated_directional_setup_sides":directional,
        "live_learned_authority_active":bool(validated or directional),
        "acceptance_directional_split_review":{
            "relax_directional_split_recommended": False if keep_directional_split else None,
            "confirmed_short_execution_source_expectancy_r": safe_float(acceptance_short_confirmed.get("expectancy_r"),0.0),
            "confirmed_short_execution_source_closed_trades": int(acceptance_short_confirmed.get("closed_trades") or 0),
            "reason":"KEEP_DIRECTIONAL_SPLIT_BECAUSE_CONFIRMED_SHORT_LANE_IS_NEGATIVE" if keep_directional_split else "INSUFFICIENT_OR_NONNEGATIVE_LANE_EVIDENCE_FOR_DECISION",
            "pooled_positive_setup_does_not_override_negative_lane": True,
        },
        "authority_contract":"GLOBAL_FIT_IS_AUDIT_ONLY; POOLED EXACT SETUP REQUIRES SIDE-SAFE OOS; MATERIAL SIDE DIVERGENCE MAY USE ONLY INDEPENDENT SIDE-SPECIFIC NESTED OOS AUTHORITY; NEGATIVE EXECUTION-SOURCE LANE CANNOT BORROW POOLED SETUP REPUTATION",
        "schema_version":"calibration_authority_audit_v9.5.30_lane_aware_directional",
        "updated_at":iso_now(),
    }


def compute_setup_statistics(journal: dict[str, Any]) -> dict[str, Any]:
    """Performance memory by setup type and family.

    Both keys are emitted so callers can evaluate a precise setup_type or the
    broader setup_family without inventing a second statistics pipeline.
    """
    stats: dict[str, dict[str, Any]] = {}
    signals = {
        str(s.get("id")): s
        for s in journal.get("signals", []) or []
        if isinstance(s, dict) and s.get("id")
    }

    def _record(key: str, result_r: float, path_category: str = "UNKNOWN") -> None:
        if not key:
            return
        bucket = stats.setdefault(
            key,
            {
                "trades": 0, "closed_trades": 0, "wins": 0, "net_r": 0.0,
                "standard_path": 0, "revalidation_or_innovation_path": 0, "unknown_path": 0,
            },
        )
        bucket["trades"] += 1
        bucket["closed_trades"] += 1
        bucket["net_r"] += result_r
        if result_r > 0:
            bucket["wins"] += 1
        if path_category == "STANDARD":
            bucket["standard_path"] += 1
        elif path_category in {"REVALIDATION", "INNOVATION_FALLBACK"}:
            bucket["revalidation_or_innovation_path"] += 1
        else:
            bucket["unknown_path"] += 1

    for trade in journal.get("trades", []):
        if not isinstance(trade, dict):
            continue
        result = _journal_result_r(trade)
        if result is None:
            continue
        setup_type = str(trade.get("setup_type", "UNKNOWN") or "UNKNOWN")
        setup_family = str(trade.get("setup_family", "") or "")
        signal = signals.get(str(trade.get("signal_id") or ""))
        path_category = _signal_execution_path(signal).get("category", "UNKNOWN") if signal else "UNKNOWN"
        _record(setup_type, result, path_category)
        if setup_family and setup_family != setup_type:
            _record(setup_family, result, path_category)

    for bucket in stats.values():
        closed = int(bucket.get("closed_trades", 0) or 0)
        bucket["net_r"] = round(float(bucket.get("net_r", 0.0) or 0.0), 4)
        bucket["win_rate"] = round(bucket["wins"] / closed * 100, 2) if closed else 0.0
        bucket["expectancy_r"] = round(bucket["net_r"] / closed, 4) if closed else 0.0
        bucket["standard_path_pct"] = round(bucket["standard_path"] / closed * 100, 2) if closed else 0.0
        bucket["fallback_path_pct"] = round(bucket["revalidation_or_innovation_path"] / closed * 100, 2) if closed else 0.0

    return stats



def _wilson_interval(wins: int, total: int, z: float = WEEKEND_RANGE_WILSON_Z) -> tuple[float, float]:
    """Wilson score interval for a binomial win rate, returned in [0, 1]."""
    if total <= 0:
        return 0.0, 1.0
    p = wins / total
    denom = 1.0 + (z * z / total)
    centre = (p + (z * z / (2.0 * total))) / denom
    margin = (z / denom) * math.sqrt((p * (1.0 - p) / total) + (z * z / (4.0 * total * total)))
    return max(0.0, centre - margin), min(1.0, centre + margin)


def compute_calendar_statistics(journal: dict[str, Any]) -> dict[str, Any]:
    """Compare RANGE trades opened on weekends versus weekdays.

    This is deliberately observational. It does not mutate Regime.RANGE or its
    thresholds. A split is merely marked as statistically supported after both
    buckets have enough samples and 95% Wilson win-rate intervals do not overlap.
    """
    buckets = {
        "weekend": {"closed_trades": 0, "wins": 0, "net_result": 0.0},
        "weekday": {"closed_trades": 0, "wins": 0, "net_result": 0.0},
    }
    for trade in journal.get("trades", []) or []:
        if not isinstance(trade, dict):
            continue
        if str(trade_open_regime_lineage(trade).get("regime") or "") != Regime.RANGE.value:
            continue
        opened = _parse_iso_datetime(trade.get("opened_at", trade.get("time")))
        if opened is None:
            continue
        key = "weekend" if opened.weekday() >= 5 else "weekday"
        result = _journal_result_r(trade)
        if result is None:
            continue
        bucket = buckets[key]
        bucket["closed_trades"] += 1
        bucket["wins"] += 1 if result > 0 else 0
        bucket["net_result"] += result

    for bucket in buckets.values():
        total = int(bucket["closed_trades"])
        wins = int(bucket["wins"])
        lo, hi = _wilson_interval(wins, total)
        bucket["win_rate_pct"] = round((wins / total * 100.0) if total else 0.0, 2)
        bucket["expectancy"] = round((bucket["net_result"] / total) if total else 0.0, 4)
        bucket["net_result"] = round(bucket["net_result"], 4)
        bucket["win_rate_wilson_95"] = [round(lo * 100.0, 2), round(hi * 100.0, 2)]

    weekend = buckets["weekend"]
    weekday = buckets["weekday"]
    enough = (
        weekend["closed_trades"] >= WEEKEND_RANGE_MIN_TRADES_PER_BUCKET
        and weekday["closed_trades"] >= WEEKEND_RANGE_MIN_TRADES_PER_BUCKET
    )
    w_lo, w_hi = [x / 100.0 for x in weekend["win_rate_wilson_95"]]
    d_lo, d_hi = [x / 100.0 for x in weekday["win_rate_wilson_95"]]
    intervals_separate = bool(w_hi < d_lo or d_hi < w_lo)
    split_supported = bool(enough and intervals_separate)
    return {
        "range_weekend_vs_weekday": {
            "weekend": weekend,
            "weekday": weekday,
            "minimum_trades_per_bucket": WEEKEND_RANGE_MIN_TRADES_PER_BUCKET,
            "enough_samples": enough,
            "wilson_intervals_separate": intervals_separate,
            "split_supported": split_supported,
            "decision": "SPLIT_SUPPORTED" if split_supported else "KEEP_SHARED_RANGE",
            "reason": (
                "statistically distinct RANGE win rates"
                if split_supported
                else "insufficient evidence for a separate weekend regime"
            ),
        }
    }

def _parse_iso_datetime(value: Any) -> Optional[datetime]:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except (TypeError, ValueError):
        return None


def compute_daily_risk_used(journal: dict[str, Any], at: Optional[datetime] = None) -> float:
    """Return risk already consumed by trades closed on the UTC trading day.

    Open exposure is intentionally excluded and is handled separately by
    compute_open_position_risk(), preventing the same trade from being counted
    twice. Legacy trade rows without a timestamp cannot be assigned to a day
    safely and are therefore ignored rather than guessed.
    """
    day = (at or now_utc()).astimezone(timezone.utc).date()
    total = 0.0
    seen: set[tuple[str, str]] = set()

    for trade in journal.get("trades", []) or []:
        if not isinstance(trade, dict):
            continue
        closed_at = _parse_iso_datetime(trade.get("closed_at"))
        if closed_at is None or closed_at.date() != day:
            continue
        key = (str(trade.get("id") or ""), str(trade.get("signal_id") or ""))
        if key != ("", "") and key in seen:
            continue
        seen.add(key)
        total += max(0.0, safe_float(trade.get("position_risk_pct", trade.get("risk_pct")), 0.0))

    return round(total, 4)


def compute_open_position_risk(state: dict[str, Any]) -> float:
    """Return current open risk in the same percentage-point units as the cap."""
    raw = (state or {}).get("active_trade")
    if not isinstance(raw, dict):
        return 0.0
    if str(raw.get("status", "OPEN")).upper() == "CLOSED":
        return 0.0
    return round(max(0.0, safe_float(raw.get("position_risk_pct"), 0.0)), 4)

def atomic_json_write(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    backup = path.with_suffix(path.suffix + ".bak")
    payload = json_safe(data)
    with temp.open("w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, separators=(",", ":"))
    os.replace(temp, path)
    with backup.open("w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, separators=(",", ":"))


def load_json(path: Path, default: dict[str, Any]) -> dict[str, Any]:
    try:
        if not path.exists():
            return default
        with path.open("r", encoding="utf-8") as fh:
            value = json.load(fh)
        return value if isinstance(value, dict) else default
    except Exception as exc:
        print(f"[WARN] JSON read failed {path}: {exc}")
        return default


