def send_telegram(text: str) -> bool:
    text = clean_telegram_message(text)
    
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        print("[ERROR] Telegram credentials absent")
        print(plain_telegram_text(text)[:500])
        return False

    url = f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage"
    payload = {
        "chat_id": TELEGRAM_CHAT_ID,
        "text": text[:TELEGRAM_MAX_LENGTH],
        "parse_mode": "HTML",
        "disable_web_page_preview": True,
    }
    
    try:
        response = requests.post(url, json=payload, timeout=REQUEST_TIMEOUT)
        if response.ok:
            print(f"Telegram status: {response.status_code}")
            return True
        else:
            print(f"[ERROR] Telegram failed {response.status_code}: {response.text[:300]}")
            fallback = dict(payload)
            fallback.pop("parse_mode", None)
            fallback["text"] = plain_telegram_text(text)[:TELEGRAM_MAX_LENGTH]
            retry = requests.post(url, json=fallback, timeout=REQUEST_TIMEOUT)
            if retry.ok:
                print(f"Telegram fallback status: {retry.status_code}")
                return True
            return False
    except Exception as exc:
        print(f"[ERROR] Telegram exception: {exc}")
        return False


def clean_telegram_message(text: str) -> str:
    forbidden_prefixes = (
        "Варіант:", "Сімейство:", "Стадія:", "Карта входу:",
        "Де очікувати", "Робоча зона входу:", "Тригер:", "Логіка виконання:",
        "Основа стопа:", "Таймфрейм стопа:", "Старший сценарій:",
        "Прийняття рівня:", "Основа тейків:", "Протилежна зона:",
        "Проміжні бар’єри", "Проміжні бар'єри", "Найближча реальна ліквідність:",
        "Оптимальний вхід", "Оптимальний орієнтир", "Скасування:", "Ризики:",
        "Edge-модель:", "Статус виконання:", "Статус:", "Орієнтир входу",
    )
    cleaned: list[str] = []
    for line in str(text or "").splitlines():
        plain = html.unescape(line.replace("<b>", "").replace("</b>", "")).strip()
        if plain.startswith(forbidden_prefixes) or plain.startswith("⚠️"):
            continue
        cleaned.append(line)
    message = "\n".join(cleaned)
    replacements = {
        "Regime.RANGE": "ДІАПАЗОН", "Regime.TREND": "ТРЕНД",
        "Regime.TRANSITION": "ПЕРЕХІДНИЙ РЕЖИМ",
        "Regime.SHOCK": "ІМПУЛЬСНИЙ РЕЖИМ", "Regime.NORMAL": "ЗВИЧАЙНИЙ РИНОК",
    }
    for raw, translated in replacements.items():
        message = message.replace(raw, translated)
    while "\n\n\n" in message:
        message = message.replace("\n\n\n", "\n\n")
    return message.strip()


def plain_telegram_text(text: str) -> str:
    return html.unescape(text.replace("<b>", "").replace("</b>", ""))


def build_decision_message(context: dict, decision: Decision) -> str:
    current_price = decision.current_price or context.get("price", 0)
    
    action_names = {
        "ENTRY": "ВХІД У УГОДУ",
        "RISKY_ENTRY": "РАННІЙ / СТАДІЙНИЙ ВХІД",
        "PROBE_ENTRY": "ПРОБНИЙ ВХІД",
        "NO_SETUP": "СИГНАЛУ НЕМАЄ",
    }
    action_label = action_names.get(decision.action, decision.action)

    if decision.action == Action.NO_SETUP.value:
        confirmation_pending = bool(
            decision.candidate and getattr(decision.candidate, "confirmation_pending", False)
        )
        if confirmation_pending:
            lines = [
                "🟡 <b>Вхід наближається: готовність висока.</b>",
                f"{decision.side}-сценарій сформований, але execution чекає один підтверджувальний бар.",
            ]
            confirmation = getattr(decision.candidate, "confirmation_state", {}) or {}
            level = safe_float(confirmation.get("anchor"), safe_float(confirmation.get("level"), 0.0))
            source = str(confirmation.get("anchor_source") or confirmation.get("level_name") or decision.candidate.execution_source)
            if level > 0:
                lines.append(f"<b>Контрольний рівень:</b> {_fmt_price(level)} | {html.escape(source)}")
        else:
            lines = [
                "<b>Входу зараз немає.</b>",
            ]

            if decision.side and decision.side != Side.NEUTRAL.value:
                lines.append(
                    f"{decision.side}-сценарій залишається, але свіжого підтвердження "
                    "для відкриття позиції немає."
                )
            else:
                lines.append(
                    "Немає достатнього підтвердження для відкриття позиції."
                )

        lines.append(
            f"<b>Ціна зараз:</b> {_fmt_price(current_price)}"
        )
        # Telegram only: compact user-facing summary.
        # Preconfirm, detector audit details and close-miss diagnostics remain
        # available internally and are not changed.
        quality = safe_float(
            getattr(decision.candidate, "entry_quality", 0),
            safe_float(getattr(decision.candidate, "final_score", 0), 0.0)
        ) if decision.candidate else 0.0
        if quality > 0:
            lines.append(f"<b>Якість:</b> {quality:.0f}/100")
        rejected = ((decision.audit or {}).get("rejected_hypotheses") or [])
        if rejected:
            top = rejected[0]
            lines.append(f"<b>Найближча гіпотеза:</b> {html.escape(str(top.get('side', '')))} {html.escape(str(top.get('model', '')))} | score {html.escape(str(top.get('final_score', '')))}")
            lines.append(f"<b>Чому ні:</b> {html.escape(str(top.get('failed_gate', ''))[:180])}")
        for warning in context.get("learning_warnings", [])[:2]:
            lines.append(f"⚠️ {html.escape(warning)}")
        return "\n".join(lines)[:TELEGRAM_MAX_LENGTH]
    
    decision_audit = decision.audit or {}
    adaptive = (
        decision_audit.get("legacy_adaptive_conflict_override")
        or decision_audit.get("adaptive_conflict_resolver")
        or {}
    )
    decision_variant = adaptive.get("decision_variant")
    conflict_override = bool(adaptive.get("conflict_override", False))

    learning_status = context.get("learning_status") or {}
    mode = scoring_mode_profile(learning_status)
    components = (decision.candidate.score_components or {}) if decision.candidate else {}
    entry_q = int(safe_float(
        getattr(decision.candidate, "entry_quality_score", 0) if decision.candidate else 0,
        safe_float(components.get("entry_quality"), decision.quality),
    ))
    durability_q = int(safe_float(
        getattr(decision.candidate, "durability_quality_score", 0) if decision.candidate else 0,
        safe_float(components.get("durability_quality"), 0),
    ))

    lines = [
        f"<b>{action_label}</b> | {side_word(decision.side)} | {setup_label(decision.setup_type)}",
        f"<b>Overall quality:</b> {decision.quality}/100 | Режим: {regime_label(decision.regime)}",
        f"<b>Entry quality:</b> {entry_q}/100 | <b>Durability:</b> {durability_q}/100",
        f"<b>Scoring:</b> {html.escape(mode['label'])} | rows {mode['training_rows']}/{mode['minimum_rows']}",
        f"<b>Ціна зараз:</b> {_fmt_price(current_price)}"
    ]
    preconfirm_line = _preconfirm_telegram_line(decision.candidate)
    if preconfirm_line:
        lines.append(preconfirm_line)

    if decision_variant == "PROBE_REDUCED" or conflict_override:
        lines.append("⚠️ <b>Тип входу:</b> PROBE_REDUCED (conflict override, знижений ризик)")
    
    if decision.candidate and decision.action != Action.NO_SETUP.value:
        c = decision.candidate
        # Показуємо тільки одне найсильніше підтвердження.
        # Не виводимо список з декількох тез, щоб Telegram-повідомлення
        # не виглядало як внутрішній debug-log.
        priority_confirmation = None

        confirmations = [
            str(x).strip()
            for x in (c.confirmations or [])
            if str(x).strip()
        ]

        # Пріоритет: активний execution trigger > модель > інші пояснення.
        priority_keywords = (
            "LIMIT_ARMED",
            "LIVE",
            "CHoCH",
            "FVG",
            "OB",
            "RECLAIM",
            "RETEST",
            "TRIGGER",
        )

        for keyword in priority_keywords:
            for item in confirmations:
                if keyword.lower() in item.lower():
                    priority_confirmation = item
                    break
            if priority_confirmation:
                break

        if priority_confirmation is None and confirmations:
            priority_confirmation = confirmations[0]

        if priority_confirmation:
            lines.append("")
            lines.append("<b>Підтвердження:</b>")
            lines.append(f"✅ {html.escape(priority_confirmation)}")
    for warning in context.get("learning_warnings", [])[:2]:
        lines.append(f"⚠️ {html.escape(warning)}")
    
    show_plan = decision.plan and decision.plan.valid and decision.action in EXECUTABLE_ENTRY_ACTIONS
    
    if show_plan:
        p = decision.plan
        lines.append("")
        lines.append("<b>План:</b>")
        lines.append(f"Вхід <b>{_fmt_price(p.entry)}</b> | Стоп <b>{_fmt_price(p.stop)}</b>")
        if getattr(p, "tp0", 0):
            lines.append(f"TP0 {_fmt_price(p.tp0)} (RR {p.rr0}) | TP1 {_fmt_price(p.tp1)} (RR {p.rr1})")
            lines.append(f"TP2 {_fmt_price(p.tp2)} | TP3 {_fmt_price(p.tp3)}")
        else:
            lines.append(f"TP1 {_fmt_price(p.tp1)} (RR {p.rr1}) | TP2 {_fmt_price(p.tp2)} | TP3 {_fmt_price(p.tp3)}")
        if getattr(p, "entry_stage", ""):
            lines.append(f"Стадія: <b>{html.escape(p.entry_stage)}</b> | Джерело: {html.escape(p.execution_source)} | Ризик: {p.position_risk_pct}%")
    
    return "\n".join(lines)[:TELEGRAM_MAX_LENGTH]




def _bias_label(block: dict) -> str:
    value = str((block or {}).get("bias") or Side.NEUTRAL.value).upper()
    if value in {Side.LONG.value, Side.SHORT.value}:
        return value
    return Side.NEUTRAL.value


def _opposite_side(side: str) -> str:
    return Side.SHORT.value if side == Side.LONG.value else Side.LONG.value


def _follow_reversal_risk(trade: ActiveTrade, result: dict, context: dict) -> tuple[str, int]:
    opposite = _opposite_side(trade.side)
    current_pct = float(result.get("current_pct") or 0)
    score = 10
    if current_pct < 0:
        score += 16
    if current_pct <= -0.50:
        score += 10
    for block, weight in ((context.get("tf3", {}), 18), (context.get("tf15", {}), 22), (context.get("flow", {}), 8), (context.get("cvd", {}), 8)):
        if _bias_label(block) == opposite:
            score += weight
    if result.get("action") == Action.PROTECT.value:
        score += 14
    if result.get("closed"):
        score = max(score, 80)
    score = max(0, min(100, int(score)))
    if score < 20:
        label = "НИЗЬКИЙ"
    elif score < 45:
        label = "ПОМІРНИЙ"
    elif score < 70:
        label = "ВИСОКИЙ"
    else:
        label = "КРИТИЧНИЙ"
    return label, score


def _follow_title(trade: ActiveTrade, result: dict, context: dict) -> str:
    side = side_word(trade.side)
    action = str(result.get("action") or Action.HOLD.value)
    current_pct = float(result.get("current_pct") or 0)
    opposite = _opposite_side(trade.side)
    tf3_opposite = _bias_label(context.get("tf3", {})) == opposite
    tf15_opposite = _bias_label(context.get("tf15", {})) == opposite

    if result.get("closed") or action in {Action.STOP.value, Action.EXIT.value}:
        return f"🔴 СУПРОВІД {side} — УГОДУ ЗАКРИТО"
    if action == Action.TP3.value:
        return f"🟢 СУПРОВІД {side} — TP3 ВЗЯТО"
    if action == Action.TP2.value:
        return f"🟢 СУПРОВІД {side} — TP2 ВЗЯТО"
    if action == Action.TP1.value:
        return f"🟢 СУПРОВІД {side} — TP1 ВЗЯТО"
    management_state = str(result.get("management_state") or getattr(trade, "management_state", "SUPPORTED"))
    if action == Action.PROTECT.value or management_state == "PROTECT":
        return f"🟠 СУПРОВІД {side} — PROTECT / ПРИБУТОК ЗАХИЩЕНО"
    if management_state == "WEAKENING":
        return f"🟠 СУПРОВІД {side} — WEAKENING / СЕТАП СЛАБШАЄ"
    if current_pct < 0 or tf3_opposite or tf15_opposite:
        return f"🟠 СУПРОВІД {side} — СЕТАП СЛАБШАЄ"
    return f"🟢 СУПРОВІД {side} — СЕТАП ТРИМАЄТЬСЯ"


def build_follow_message(context: dict, trade: ActiveTrade, result: dict) -> str:
    price = context.get("price", 0)
    recommended_stop = result.get("recommended_stop")
    stop_to_show = recommended_stop if recommended_stop is not None else trade.stop_current
    reversal_side = side_word(_opposite_side(trade.side))
    reversal_label, reversal_score = _follow_reversal_risk(trade, result, context)
    tp_status = f"TP0 {'✅' if getattr(trade, 'tp0_hit', False) else '—'} | TP1 {'✅' if trade.tp1_hit else '—'} | TP2 {'✅' if trade.tp2_hit else '—'} | TP3 {'✅' if trade.tp3_hit else '—'}"

    lines = [
        _follow_title(trade, result, context),
        "",
        f"Ціна: {_fmt_price(price)}",
        f"Від входу: {result.get('current_pct', 0):.3f}% | Макс. прибуток: {result.get('best_pct', 0):.2f}% | Відкат від макс.: {result.get('giveback_pct', 0):.2f}%",
        "",
        f"Ризик розвороту в {reversal_side}: {reversal_label} ({reversal_score}%)",
        "",
        "Позиція:",
        f"Вхід {_fmt_price(trade.entry)} | Стоп {_fmt_price(stop_to_show)}",
        f"TP0 {_fmt_price(getattr(trade, 'tp0', 0.0)) if getattr(trade, 'tp0', 0.0) else '—'} | TP1 {_fmt_price(trade.tp1)} | TP2 {_fmt_price(trade.tp2)} | TP3 {_fmt_price(trade.tp3)}",
        f"Стадія: {html.escape(getattr(trade, 'entry_stage', ''))} | Джерело: {html.escape(getattr(trade, 'execution_source', ''))}",
        f"Стан супроводу: <b>{html.escape(str(result.get('management_state') or getattr(trade, 'management_state', 'SUPPORTED')))}</b>",
        tp_status,
    ]

    if result.get("stop_changed"):
        lines.insert(
            1,
            f"🔔 <b>СТОП ЛОСС ЗМІНЕНО!</b> {_fmt_price(result.get('stop_before'))} → {_fmt_price(result.get('stop_after'))}",
        )

    return "\n".join(lines)[:TELEGRAM_MAX_LENGTH]


def side_word(side: str) -> str:
    return {"LONG": "ЛОНГ", "SHORT": "ШОРТ"}.get(side, "НЕЙТРАЛЬНО")


def _fmt_price(v: Any) -> str:
    if v is None:
        return "-"
    return f"{float(v):.4f}".rstrip("0").rstrip(".")


# ==========================================================
# ADAPTIVE PARAMETER ENGINE
# ==========================================================

def get_adaptive_params(regime: str) -> dict:
    base = {
        "entry_score": ENTRY_SCORE_BASE,
        "risky_entry_score": RISKY_ENTRY_SCORE_BASE,
        "probe_entry_score": ARMED_SCORE_BASE,
        "armed_score": ARMED_SCORE_BASE,
        "min_evidence": MIN_ENTRY_EVIDENCE_BASE,
        "mfe_giveback_threshold": 0.42,
        "min_mfe_for_protect": 2.0,
        "reentry_aggressiveness": 1.30,
    }

    # Regime adapts evidence, protection and re-entry behavior, not the canonical
    # 75/68 score cutoffs. Hidden regime-specific score thresholds were another
    # parallel policy and are intentionally removed.
    if regime == Regime.TREND.value:
        base["min_evidence"] = max(4, MIN_ENTRY_EVIDENCE_BASE - 1)
        base["mfe_giveback_threshold"] = 0.38
        base["min_mfe_for_protect"] = 1.8
        base["reentry_aggressiveness"] = 1.40

    elif regime == Regime.RANGE.value:
        base["min_evidence"] = MIN_ENTRY_EVIDENCE_BASE + 1
        base["mfe_giveback_threshold"] = 0.52
        base["min_mfe_for_protect"] = 2.6
        base["reentry_aggressiveness"] = 0.90

    elif regime == Regime.SHOCK.value:
        base["min_evidence"] = MIN_ENTRY_EVIDENCE_BASE + 2
        base["mfe_giveback_threshold"] = 0.55
        base["min_mfe_for_protect"] = 2.8
        base["reentry_aggressiveness"] = 0.75

    elif regime == Regime.TRANSITION.value:
        base["reentry_aggressiveness"] = 1.20

    return base


# ==========================================================
# CANONICAL SCORE / AGE POLICY
# ==========================================================

def candidate_market_thesis_age_minutes(candidate: Optional[Candidate]) -> float:
    if candidate is None:
        return 0.0
    explicit = safe_float(getattr(candidate, "market_thesis_age_minutes", -1.0), -1.0)
    if explicit >= 0.0:
        return explicit
    components = getattr(candidate, "score_components", {}) or {}
    if "market_thesis_age_minutes" in components:
        return max(0.0, safe_float(components.get("market_thesis_age_minutes"), 0.0))
    if "original_trigger_age_minutes" in components:
        return max(0.0, safe_float(components.get("original_trigger_age_minutes"), 0.0))
    explicit_legacy = safe_float(getattr(candidate, "thesis_age_minutes", -1.0), -1.0)
    if explicit_legacy >= 0.0:
        return explicit_legacy
    return max(0.0, safe_float(getattr(candidate, "trigger_age_minutes", 0.0), 0.0))


def candidate_model_thesis_age_minutes(candidate: Optional[Candidate]) -> float:
    """Return model-local thesis age while preserving the -1 unknown sentinel.

    The previous ``max(0, value)`` fallback converted a persisted ``-1`` into
    ``0.0``. That manufactured a fresh model thesis even when the candidate
    still declared ``MARKET_SCAN`` origin, producing an impossible audit state.
    """
    if candidate is None:
        return -1.0
    explicit = safe_float(getattr(candidate, "model_thesis_age_minutes", -1.0), -1.0)
    if explicit >= 0.0:
        return explicit
    components = getattr(candidate, "score_components", {}) or {}
    if "model_thesis_age_minutes" in components:
        component_age = safe_float(components.get("model_thesis_age_minutes"), -1.0)
        return component_age if component_age >= 0.0 else -1.0
    return -1.0


def candidate_thesis_age_minutes(candidate: Optional[Candidate]) -> float:
    """Return the effective thesis lease without conflating two clocks.

    A model-local thesis is authoritative only when the candidate explicitly
    declares ``MODEL_LOCAL`` origin and carries its own non-negative age. Old
    scan/market age remains visible for audit, but cannot hard-expire a newly
    formed model-local setup. Legacy candidates continue using the old field.
    """
    if candidate is None:
        return 0.0
    origin = str(getattr(candidate, "thesis_origin", "") or "").upper()
    model_age = candidate_model_thesis_age_minutes(candidate)
    if origin.startswith("MODEL_LOCAL") and model_age >= 0.0:
        return model_age
    explicit = safe_float(getattr(candidate, "thesis_age_minutes", -1.0), -1.0)
    if explicit >= 0.0:
        return explicit
    return candidate_market_thesis_age_minutes(candidate)


def candidate_execution_trigger_age_minutes(candidate: Optional[Candidate]) -> float:
    if candidate is None:
        return 0.0
    explicit = safe_float(getattr(candidate, "execution_trigger_age_minutes", -1.0), -1.0)
    if explicit >= 0.0:
        return explicit
    components = getattr(candidate, "score_components", {}) or {}
    if "effective_trigger_age_minutes" in components:
        return max(0.0, safe_float(components.get("effective_trigger_age_minutes"), 0.0))
    return max(0.0, safe_float(getattr(candidate, "trigger_age_minutes", 0.0), 0.0))




# ==========================================================
# PROFESSIONAL GATE (ADVISORY EVIDENCE, CANONICAL SCORE POLICY)
# ==========================================================

def evaluate_professional_gate(context: dict, candidate: Candidate) -> dict:
    score = candidate.final_score
    score_policy = canonical_score_admission_profile(candidate)
    layers = len(candidate.evidence_families)
    trigger_ready = candidate.trigger_ready
    strong_ict = "ICT_LOCATION" in candidate.evidence_families or "PRICE_STRUCTURE" in candidate.evidence_families
    gates = ((candidate.score_components or {}).get("gates") or {})
    gate_product = safe_float(gates.get("product"), 1.0)
    trigger_gate = safe_float(gates.get("trigger_gate"), 1.0)
    pattern_gate = safe_float(gates.get("pattern_gate"), 1.0)
    location_gate = safe_float(gates.get("location_gate"), 1.0)
    
    # ПЕРЕВІРКА ТРЕНДУ (Новий логічний блок)
    tf1h_bias = context.get("tf1h", {}).get("bias")
    tf4h_bias = context.get("tf4h", {}).get("bias")
    htf_aligned = (tf1h_bias == candidate.side) or (tf4h_bias == candidate.side)
    directional_htf = [
        bias for bias in (tf1h_bias, tf4h_bias)
        if bias in {Side.LONG.value, Side.SHORT.value}
    ]
    # A genuinely neutral HTF is acceptable in the shadow experiment. A
    # directional HTF with no same-side vote is still treated as opposition.
    shadow_htf_not_opposed = bool(htf_aligned or not directional_htf)

    advisory_allow_entry = bool(
        score_policy["full_entry_eligible"]
        and layers >= MIN_PRO_LAYERS_ENTRY
        and trigger_ready
        and strong_ict
        and gate_product >= 0.62
        and trigger_gate >= 0.95
        and pattern_gate >= 0.95
        and location_gate >= 0.74
    )

    advisory_allow_risky = bool(
        score_policy["risky_entry_eligible"]
        and layers >= max(3, MIN_PRO_LAYERS_ENTRY - 1)
        and (trigger_ready or strong_ict)
        and htf_aligned
        and gate_product >= 0.46
        and pattern_gate >= 0.70
    )

    shadow_gates = dict(gates.get("shadow_experiment") or {})
    shadow_gate_product = safe_float(shadow_gates.get("product"), gate_product)
    shadow_trigger_gate = safe_float(shadow_gates.get("trigger_gate"), trigger_gate)
    shadow_pattern_gate = safe_float(shadow_gates.get("pattern_gate"), pattern_gate)
    shadow_location_gate = safe_float(shadow_gates.get("location_gate"), location_gate)
    shadow_allow_entry = bool(
        score >= SHADOW_ENTRY_SCORE
        and layers >= SHADOW_MIN_PRO_LAYERS_ENTRY
        and trigger_ready
        and strong_ict
        and shadow_gate_product >= 0.55
        and shadow_trigger_gate >= 0.88
        and shadow_pattern_gate >= 0.88
        and shadow_location_gate >= 0.65
    )
    shadow_allow_risky = bool(
        score >= SHADOW_RISKY_ENTRY_SCORE
        and layers >= max(3, SHADOW_MIN_PRO_LAYERS_ENTRY - 1)
        and (trigger_ready or strong_ict)
        and shadow_htf_not_opposed
        and shadow_gate_product >= 0.46
        and shadow_pattern_gate >= 0.70
    )

    if advisory_allow_entry and score >= A_PLUS_ENTRY_MIN and strong_ict:
        grade = "A+"
    elif advisory_allow_entry:
        grade = "A"
    elif advisory_allow_risky:
        grade = "B"
    else:
        grade = "WATCH"

    reason = f"gate v7 data-driven: {grade} | {layers} шарів | score {score} | gates x{gate_product:.2f}"
    if not htf_aligned and not advisory_allow_entry:
        reason += " | БЛОК: HTF проти risky-входу"
    if pattern_gate < 0.95 and not advisory_allow_entry:
        reason += " | generic pattern penalty"

    return {
        "advisory_advisory_allow_entry": advisory_allow_entry,
        "advisory_advisory_allow_risky": advisory_allow_risky,
        "authority": "ADVISORY_ONLY",
        "grade": grade,
        "score": score,
        "layers": layers,
        "gate_product": gate_product,
        "score_policy": score_policy,
        "shadow_experiment": {
            "audit_only": True,
            "can_authorize_trade": False,
            "allow_entry": shadow_allow_entry,
            "allow_risky": shadow_allow_risky,
            "grade": (
                "A+" if shadow_allow_entry and score >= SHADOW_A_PLUS_ENTRY_MIN
                else "A" if shadow_allow_entry
                else "B" if shadow_allow_risky
                else "WATCH"
            ),
            "score_thresholds": {
                "armed": SHADOW_ARMED_SCORE,
                "risky": SHADOW_RISKY_ENTRY_SCORE,
                "entry": SHADOW_ENTRY_SCORE,
                "a_plus": SHADOW_A_PLUS_ENTRY_MIN,
            },
            "minimum_entry_layers": SHADOW_MIN_PRO_LAYERS_ENTRY,
            "gate_thresholds": {
                "product": 0.55,
                "trigger": 0.88,
                "pattern": 0.88,
                "location": 0.65,
            },
            "htf_not_opposed": shadow_htf_not_opposed,
            "neutral_htf_is_eligible": True,
            "gate_product": round(shadow_gate_product, 3),
        },
        "reason": reason,
    }

# ==========================================================
# ICT UTILITIES (NEW)
# ==========================================================

def identify_liquidity_and_range(candles: list[Candle], left_bars: int = 5, right_bars: int = 5) -> dict:
    """Визначає Premium/Discount зони та пули ліквідності."""
    if len(candles) < left_bars + right_bars + 1:
        return {"bsl": [], "ssl": [], "eq": 0.0, "premium_low": 0.0, "discount_high": 0.0}

    bsl_pools = []
    ssl_pools = []
    
    for i in range(left_bars, len(candles) - right_bars):
        window = candles[i - left_bars : i + right_bars + 1]
        center = candles[i]
        
        if center.high == max(c.high for c in window):
            bsl_pools.append(center.high)
        if center.low == min(c.low for c in window):
            ssl_pools.append(center.low)
            
    recent_high = max([c.high for c in candles[-60:]]) if len(candles) >= 60 else max([c.high for c in candles])
    recent_low = min([c.low for c in candles[-60:]]) if len(candles) >= 60 else min([c.low for c in candles])
    
    eq = (recent_high + recent_low) / 2
    
    return {
        "bsl": sorted(list(set(bsl_pools)))[-5:],
        "ssl": sorted(list(set(ssl_pools)))[:5],
        "range_high": recent_high,
        "range_low": recent_low,
        "eq": eq,
    }

def detect_smt_divergence_profile(asset_candles: list[Candle], smt_candles: list[Candle]) -> dict[str, Any]:
    """Timestamp-aligned SMT profile for the BZ/WTI commodity-proxy pair.

    A missing feed is not the same fact as a neutral divergence. The old
    implementation collapsed both cases to NEUTRAL, which made the sweep audit
    blame market structure when SMT candles had actually disappeared upstream.
    """
    asset = [c for c in asset_candles if getattr(c, "confirmed", True)]
    smt = [c for c in smt_candles if getattr(c, "confirmed", True)]
    if len(asset) < 20 or len(smt) < 20:
        return {
            "bias": Side.NEUTRAL.value,
            "data_available": False,
            "aligned_candles": 0,
            "asset_candles": len(asset),
            "smt_candles": len(smt),
            "reason": "INSUFFICIENT_SOURCE_CANDLES",
            "schema_version": "smt_profile_v9.5.24_timestamp_aligned",
        }

    asset_by_ts = {int(c.ts): c for c in asset}
    smt_by_ts = {int(c.ts): c for c in smt}
    common_ts = sorted(set(asset_by_ts).intersection(smt_by_ts))
    aligned = [(asset_by_ts[ts], smt_by_ts[ts]) for ts in common_ts]
    if len(aligned) < 20:
        return {
            "bias": Side.NEUTRAL.value,
            "data_available": False,
            "aligned_candles": len(aligned),
            "asset_candles": len(asset),
            "smt_candles": len(smt),
            "reason": "INSUFFICIENT_TIMESTAMP_ALIGNMENT",
            "schema_version": "smt_profile_v9.5.24_timestamp_aligned",
        }

    recent = aligned[-10:]
    asset_recent = [pair[0] for pair in recent]
    smt_recent = [pair[1] for pair in recent]
    asset_lows = [c.low for c in asset_recent]
    smt_lows = [c.low for c in smt_recent]
    asset_highs = [c.high for c in asset_recent]
    smt_highs = [c.high for c in smt_recent]

    asset_current_low = min(asset_lows[-3:])
    asset_prev_low = min(asset_lows[:-3])
    smt_current_low = min(smt_lows[-3:])
    smt_prev_low = min(smt_lows[:-3])
    if smt_current_low < smt_prev_low and asset_current_low >= asset_prev_low:
        bias = Side.LONG.value
        reason = "BULLISH_SMT_DIVERGENCE"
    else:
        asset_current_high = max(asset_highs[-3:])
        asset_prev_high = max(asset_highs[:-3])
        smt_current_high = max(smt_highs[-3:])
        smt_prev_high = max(smt_highs[:-3])
        if smt_current_high > smt_prev_high and asset_current_high <= asset_prev_high:
            bias = Side.SHORT.value
            reason = "BEARISH_SMT_DIVERGENCE"
        else:
            bias = Side.NEUTRAL.value
            reason = "NO_DIVERGENCE"

    return {
        "bias": bias,
        "data_available": True,
        "aligned_candles": len(aligned),
        "asset_candles": len(asset),
        "smt_candles": len(smt),
        "latest_aligned_ts": common_ts[-1] if common_ts else 0,
        "reason": reason,
        "schema_version": "smt_profile_v9.5.24_timestamp_aligned",
    }


# ==========================================================
# DATA SOURCES: TradingView ПРІОРИТЕТ
# ==========================================================

def http_get(url: str, timeout: int = REQUEST_TIMEOUT, retries: int = 2) -> Optional[requests.Response]:
    headers = {"User-Agent": "Mozilla/5.0 BZU-Pro-v6.6/1.0", "Accept": "*/*"}
    last_err = None
    for attempt in range(max(1, retries)):
        try:
            resp = requests.get(url, headers=headers, timeout=timeout)
            if resp.status_code < 400:
                return resp
            last_err = f"HTTP {resp.status_code}"
        except Exception as e:
            last_err = str(e)
        time.sleep(0.3 * attempt)
    return None


def http_post(url: str, payload: dict, timeout: int = REQUEST_TIMEOUT) -> Optional[requests.Response]:
    headers = {
        "User-Agent": "Mozilla/5.0 BZU-Pro-v6.6/1.0",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    last_error = ""
    try:
        resp = requests.post(url, headers=headers, json=payload, timeout=timeout)
        if resp.status_code < 400:
            return resp
        last_error = f"HTTP {resp.status_code}"
    except Exception as exc:
        last_error = f"{type(exc).__name__}: {exc}"
    if os.getenv("BZU_HTTP_DEBUG", "").lower() in {"1", "true", "yes"}:
        print(f"[HTTP POST unavailable] {url}: {last_error}")
    return None


def get_okx_candles(inst_id: str = "BZ-USDT", bar: str = "15m", limit: int = 200) -> list[Candle]:
    url = f"{OKX_BASE_URL}/candles?instId={inst_id}&bar={bar}&limit={limit}"
    resp = http_get(url)
    if not resp:
        return []
    try:
        data = resp.json()
        if data.get("code") != "0":
            return []
        out = []
        for row in data.get("data", []):
            try:
                out.append(Candle(
                    ts=int(row[0]),
                    open=float(row[1]),
                    high=float(row[2]),
                    low=float(row[3]),
                    close=float(row[4]),
                    volume=float(row[5] or 0),
                    confirmed=(len(row) > 8 and str(row[8]) == "1")
                ))
            except Exception:
                continue
        out.sort(key=lambda c: c.ts)
        return out
    except Exception:
        return []


def get_okx_ticker(inst_id: str = "BZ-USDT") -> dict:
    url = f"{OKX_BASE_URL}/ticker?instId={inst_id}"
    resp = http_get(url)
    if not resp:
        return {}
    try:
        data = resp.json()
        if data.get("code") != "0" or not data.get("data"):
            return {}
        ticker = data["data"][0]
        last = safe_float(ticker.get("last"))
        open24h = safe_float(ticker.get("open24h"))
        return {
            "price": last,
            "change24h": pct(last, open24h) if open24h else 0.0,
            "volume24h": safe_float(ticker.get("volCcy24h")),
            "source": "OKX"
        }
    except Exception:
        return {}


