CONTEXT_EDGE_SCHEMA_VERSION = "contextual_edge_authority_v9.5.31_partial_pooling_oos"
CONTEXT_EDGE_PRIOR_SETUP = 18.0
CONTEXT_EDGE_PRIOR_SOURCE = 14.0
CONTEXT_EDGE_PRIOR_SIDE = 10.0
CONTEXT_EDGE_PRIOR_REGIME = 8.0
CONTEXT_EDGE_MAX_SELECTION_ADJUSTMENT = 3.0
CONTEXT_EDGE_EXPECTANCY_SCALE_R = 0.30
CONTEXT_EDGE_RECENCY_HALF_LIFE_TRADES = 45.0
CONTEXT_EDGE_EXPECTANCY_PROBABILITY_WEIGHT = 0.12
CONTEXT_EDGE_OOS_MIN_PREDICTIONS = 20
CONTEXT_EDGE_OOS_MIN_AUC = 0.58
CONTEXT_EDGE_OOS_MAX_BRIER = 0.24
RESEARCH_PROBE_FORWARD_MIN_TRADES = 6
RESEARCH_PROBE_FORWARD_MIN_WINS = 4
RESEARCH_PROBE_FORWARD_MIN_EXPECTANCY_R = 0.08
RESEARCH_PROBE_FORWARD_MIN_WIN_RATE = 0.55
RESEARCH_PROBE_HORIZON_MINUTES = 120
RESEARCH_PROBE_LEDGER_LIMIT = 800
PROBE_INFORMATION_MFE_TRIGGER_R = 0.75
PROBE_INFORMATION_GIVEBACK_RATIO = 0.40
ACCEPTANCE_CONFIRM_MAX_ZONE_DISTANCE_ATR = 0.70
ACCEPTANCE_WAIT_RETEST_MAX_ZONE_DISTANCE_ATR = 1.10
# v9.5.38: signed favorable-direction extension is stricter than absolute zone
# distance. This prevents late chase while preserving value-side retests.
V9538_NATIVE_PROBE_MAX_FAVORABLE_CHASE_ATR = min(
    ACCEPTANCE_CONFIRM_MAX_ZONE_DISTANCE_ATR,
    max(0.20, float(os.getenv("V9538_NATIVE_PROBE_MAX_FAVORABLE_CHASE_ATR", "0.40") or 0.40)),
)
V9538_CONFIRMED_ACCEPTANCE_MAX_FAVORABLE_CHASE_ATR = min(
    ACCEPTANCE_CONFIRM_MAX_ZONE_DISTANCE_ATR,
    max(V9538_NATIVE_PROBE_MAX_FAVORABLE_CHASE_ATR, float(os.getenv("V9538_CONFIRMED_ACCEPTANCE_MAX_FAVORABLE_CHASE_ATR", "0.50") or 0.50)),
)
SESSION_MEAN_RANGE_MIN_ESCAPE_ATR = 0.18
SESSION_MEAN_RANGE_MAX_ESCAPE_ATR = 0.90


def _trade_execution_source_lineage(trade: dict[str, Any], signals: Optional[dict[str, dict[str, Any]]] = None) -> str:
    source = str((trade or {}).get("execution_source") or "").upper()
    if not source and signals is not None:
        signal = signals.get(str((trade or {}).get("signal_id") or "")) or {}
        source = str(signal.get("execution_source") or "").upper()
    return source or ExecutionSource.NONE.value


def _context_edge_rows(journal: Optional[dict[str, Any]]) -> list[dict[str, Any]]:
    journal = journal or {}
    signals = {str(x.get("id")): x for x in (journal.get("signals") or []) if isinstance(x, dict) and x.get("id")}
    rows: list[dict[str, Any]] = []
    for idx, trade in enumerate(journal.get("trades") or []):
        if not isinstance(trade, dict):
            continue
        result_r = _journal_result_r(trade)
        if result_r is None:
            continue
        setup = str(trade.get("setup_type") or "")
        side = str(trade.get("side") or "").upper()
        if not setup or side not in {Side.LONG.value, Side.SHORT.value}:
            continue
        regime = str(trade_open_regime_lineage(trade).get("regime") or "UNKNOWN").upper()
        source = _trade_execution_source_lineage(trade, signals)
        opened = _parse_iso_datetime(trade.get("opened_at", trade.get("time")))
        if opened is None:
            sig = signals.get(str(trade.get("signal_id") or "")) or {}
            opened = _parse_iso_datetime(sig.get("time"))
        order_key = opened.timestamp() if opened is not None else float(idx)
        rows.append({
            "setup_type": setup, "execution_source": source, "side": side, "regime": regime,
            "result_r": float(result_r), "score": safe_float(trade.get("score"), 70.0), "order_key": order_key,
            "trade_id": str(trade.get("id") or idx),
        })
    rows.sort(key=lambda r: (r["order_key"], r["trade_id"]))
    return rows


def _edge_layer_statistics(rows: list[dict[str, Any]], **filters: str) -> dict[str, Any]:
    selected: list[tuple[dict[str, Any], float]] = []
    # Age is measured in closed trades, not wall-clock time. This keeps the
    # update deterministic while letting current market behavior outrank stale
    # history. The same prior-only row order is used in live and OOS replay.
    for age, row in enumerate(reversed(rows)):
        if all(not value or str(row.get(key) or "") == str(value) for key, value in filters.items()):
            weight = 0.5 ** (age / max(CONTEXT_EDGE_RECENCY_HALF_LIFE_TRADES, 1e-9))
            selected.append((row, weight))
    values = [safe_float(r.get("result_r"), 0.0) for r, _ in selected]
    wins = sum(v > 0 for v in values); n = len(values)
    weighted_n = sum(w for _, w in selected)
    weighted_wins = sum(w for r, w in selected if safe_float(r.get("result_r"), 0.0) > 0)
    weighted_net = sum(safe_float(r.get("result_r"), 0.0) * w for r, w in selected)
    return {
        "n": n, "wins": wins, "win_rate": wins / n if n else 0.0,
        "net_r": sum(values), "expectancy_r": mean(values) if values else 0.0,
        "weighted_n": weighted_n, "weighted_wins": weighted_wins, "weighted_net_r": weighted_net,
        "recency_half_life_trades": CONTEXT_EDGE_RECENCY_HALF_LIFE_TRADES,
    }


def _contextual_route_edge_from_rows(rows: list[dict[str, Any]], setup_type: str, execution_source: str, side: str, regime: str) -> dict[str, Any]:
    global_stats = _edge_layer_statistics(rows)
    # Neutral prior prevents a lucky tiny global sample from becoming certainty.
    gp = 12.0
    global_wr = (safe_float(global_stats.get("weighted_wins"), 0.0) + 0.5 * gp) / max(safe_float(global_stats.get("weighted_n"), 0.0) + gp, 1e-9)
    global_exp = safe_float(global_stats.get("weighted_net_r"), 0.0) / max(safe_float(global_stats.get("weighted_n"), 0.0) + gp, 1e-9)
    parent_wr, parent_exp = global_wr, global_exp
    layers = [{"name": "GLOBAL", **global_stats, "posterior_win_rate": global_wr, "posterior_expectancy_r": global_exp}]
    definitions = [
        ("SETUP", CONTEXT_EDGE_PRIOR_SETUP, {"setup_type": setup_type}),
        ("SOURCE", CONTEXT_EDGE_PRIOR_SOURCE, {"setup_type": setup_type, "execution_source": execution_source}),
        ("SIDE", CONTEXT_EDGE_PRIOR_SIDE, {"setup_type": setup_type, "execution_source": execution_source, "side": side}),
        ("REGIME", CONTEXT_EDGE_PRIOR_REGIME, {"setup_type": setup_type, "execution_source": execution_source, "side": side, "regime": regime}),
    ]
    for name, prior, flt in definitions:
        st = _edge_layer_statistics(rows, **flt)
        post_wr = (parent_wr * prior + safe_float(st.get("weighted_wins"), 0.0)) / max(prior + safe_float(st.get("weighted_n"), 0.0), 1e-9)
        post_exp = (parent_exp * prior + safe_float(st.get("weighted_net_r"), 0.0)) / max(prior + safe_float(st.get("weighted_n"), 0.0), 1e-9)
        layers.append({"name": name, **st, "prior_strength": prior, "posterior_win_rate": post_wr, "posterior_expectancy_r": post_exp})
        parent_wr, parent_exp = post_wr, post_exp
    leaf = layers[-1]
    exact_support = int(layers[-2]["n"])  # source+side support before regime split
    edge_probability = clamp(parent_wr + CONTEXT_EDGE_EXPECTANCY_PROBABILITY_WEIGHT * math.tanh(parent_exp / max(CONTEXT_EDGE_EXPECTANCY_SCALE_R, 1e-9)), 0.01, 0.99)
    return {
        "posterior_win_rate": round(parent_wr, 6),
        "posterior_expectancy_r": round(parent_exp, 6),
        "edge_probability": round(edge_probability, 6),
        "leaf_n": int(leaf["n"]), "source_side_n": exact_support,
        "layers": layers, "schema_version": CONTEXT_EDGE_SCHEMA_VERSION,
    }


def _auc_binary(scores: list[float], labels: list[int]) -> float:
    if not scores or len(scores) != len(labels) or len(set(labels)) < 2:
        return 0.5
    pos = [s for s, y in zip(scores, labels) if y == 1]
    neg = [s for s, y in zip(scores, labels) if y == 0]
    if not pos or not neg:
        return 0.5
    wins = 0.0
    for p in pos:
        for n in neg:
            wins += 1.0 if p > n else 0.5 if abs(p-n) <= 1e-12 else 0.0
    return wins / (len(pos) * len(neg))


_CONTEXT_EDGE_OOS_CACHE: dict[tuple[int, str], dict[str, Any]] = {}
def contextual_edge_chronological_oos(journal: Optional[dict[str, Any]]) -> dict[str, Any]:
    rows = _context_edge_rows(journal)
    key = (len(rows), str(rows[-1].get("trade_id") if rows else ""))
    if key in _CONTEXT_EDGE_OOS_CACHE:
        return copy.deepcopy(_CONTEXT_EDGE_OOS_CACHE[key])
    scores: list[float] = []
    labels: list[int] = []
    for i in range(12, len(rows)):
        row = rows[i]
        profile = _contextual_route_edge_from_rows(
            rows[:i], row["setup_type"], row["execution_source"], row["side"], row["regime"]
        )
        scores.append(clamp(safe_float(profile.get("edge_probability"), safe_float(profile.get("posterior_win_rate"), 0.5)), 0.01, 0.99))
        labels.append(1 if safe_float(row.get("result_r"), 0.0) > 0 else 0)
    n = len(scores)
    auc = _auc_binary(scores, labels) if n else 0.5
    brier = mean((p-y)**2 for p, y in zip(scores, labels)) if n else 0.25
    enabled = n >= CONTEXT_EDGE_OOS_MIN_PREDICTIONS
    passed = bool(enabled and auc >= CONTEXT_EDGE_OOS_MIN_AUC and brier <= CONTEXT_EDGE_OOS_MAX_BRIER)
    result = {
        "enabled": enabled, "predictions": n, "auc": round(auc, 6), "brier": round(brier, 6),
        "validation_pass": passed,
        "influence_multiplier": 1.0 if passed else 0.25 if enabled else 0.35,
        "selection_uses_future_labels": False,
        "policy": "STRICT_CHRONOLOGICAL_WALK_FORWARD; EACH_PREDICTION_USES_PRIOR_CLOSED_TRADES_ONLY",
        "schema_version": CONTEXT_EDGE_SCHEMA_VERSION,
    }
    _CONTEXT_EDGE_OOS_CACHE.clear(); _CONTEXT_EDGE_OOS_CACHE[key] = copy.deepcopy(result)
    return result


def contextual_route_edge_profile(journal: Optional[dict[str, Any]], candidate: Optional[Candidate]) -> dict[str, Any]:
    if candidate is None:
        return {"active": False, "reason": "NO_CANDIDATE", "schema_version": CONTEXT_EDGE_SCHEMA_VERSION}
    components = dict(getattr(candidate, "score_components", {}) or {})
    setup = str(getattr(candidate, "setup_type", "") or "")
    source = str(getattr(candidate, "execution_source", "") or ExecutionSource.NONE.value).upper()
    side = str(getattr(candidate, "side", "") or "").upper()
    regime = str(components.get("current_regime") or components.get("regime") or Regime.NORMAL.value).upper()
    rows = _context_edge_rows(journal)
    profile = _contextual_route_edge_from_rows(rows, setup, source, side, regime)
    oos = contextual_edge_chronological_oos(journal)
    exp_r = safe_float(profile.get("posterior_expectancy_r"), 0.0)
    wr = safe_float(profile.get("posterior_win_rate"), 0.5)
    raw_signal = 0.65 * math.tanh(exp_r / CONTEXT_EDGE_EXPECTANCY_SCALE_R) + 0.35 * clamp((wr - 0.5) / 0.20, -1.0, 1.0)
    adjustment = CONTEXT_EDGE_MAX_SELECTION_ADJUSTMENT * raw_signal * safe_float(oos.get("influence_multiplier"), 0.35)
    profile.update({
        "active": True, "setup_type": setup, "execution_source": source, "side": side, "regime": regime,
        "selection_adjustment": round(clamp(adjustment, -CONTEXT_EDGE_MAX_SELECTION_ADJUSTMENT, CONTEXT_EDGE_MAX_SELECTION_ADJUSTMENT), 6),
        "oos_validation": oos,
        "raw_quality_mutated": False,
        "policy": "PARTIAL_POOLING_SELECTION_CONTEXT; NO_HARD_SAMPLE_CLIFF; RAW_SCORE_IMMUTABLE",
    })
    return profile


