    base.setdefault("components", {})["contextual_edge_adjustment"] = round(adjustment, 6)
    base.setdefault("evidence", {})["contextual_route_edge"] = contextual
    base["policy"] = str(base.get("policy") or "") + "; CONTEXT_PARTIAL_POOLING_OOS_BOUNDED"
    base["schema_version"] = "evidence_adjusted_selection_v9.5.31_contextual_route_edge"
