# Buyer Exhaustion 2.0: exhaustion is hypothesis; seller control is execution.
def buyer_exhaustion_seller_control_profile(c3: list[Candle], atr15: float) -> dict[str, Any]:
    q = _recent_confirmed(c3, 8)
    if len(q) < 6 or atr15 <= 0:
        return {"ready": False, "reason": "NEED_SIX_CONFIRMED_3M_BARS", "schema_version": "buyer_exhaustion_control_v9.5.31"}
    recent = q[-6:]
    protected_low = min(c.low for c in recent[:3])
    micro_low_break = any(c.close < protected_low - atr15 * 0.025 for c in recent[3:])
    last = recent[-1]; shape = _candle_shape(last)
    displacement_atr = (last.open - last.close) / max(atr15, 1e-9)
    bearish_displacement = bool(last.close < last.open and displacement_atr >= 0.12 and safe_float(shape.get("body_ratio"), 0.0) >= 0.50)
    lower_high = max(c.high for c in recent[-3:]) < max(c.high for c in recent[:3]) - atr15 * 0.02
    bearish_closes = sum(c.close < c.open for c in recent)
    net = (recent[0].open - recent[-1].close) / max(atr15, 1e-9)
    control = bool(micro_low_break and bearish_displacement and (lower_high or bearish_closes >= 4) and net >= 0.10)
    return {
        "ready": control, "required": True, "protected_micro_low": round_price(protected_low),
        "micro_low_break": micro_low_break, "bearish_displacement": bearish_displacement,
        "displacement_atr": round(displacement_atr, 4), "lower_high": lower_high,
        "bearish_closes": bearish_closes, "signed_net_move_atr": round(net, 4),
        "reason": "SELLER_CONTROL_TRANSFER_CONFIRMED" if control else "WAIT_FRESH_3M_SELLER_CONTROL_TRANSFER",
        "schema_version": "buyer_exhaustion_control_v9.5.31",
    }




# Acceptance 2.0: confirmation must preserve location and include current 3M control.


# Session Mean 2.0: equilibrium semantics differ by regime and execution is always fresh 3M.


# Range Compression causal order: post-breakout evidence only.




def true_post_close_market_refresh(old_context: dict[str, Any], state: dict[str, Any], journal: dict[str, Any]) -> dict[str, Any]:
    old_ts = _preconfirm_as_of_ts(old_context)
    try:
        data = collect_market_data()
        fresh = build_context(data, state, journal)
    except Exception as exc:
        return {"accepted": False, "reason": "REFRESH_FETCH_FAILED", "audit": {"error": str(exc), "old_3m_ts": old_ts}}
    new_ts = _preconfirm_as_of_ts(fresh)
    trusted = bool(fresh.get("price") and fresh.get("execution_price_trusted", False))
    newer = new_ts > old_ts
    audit = {
        "old_3m_ts": old_ts, "new_3m_ts": new_ts, "newer_confirmed_3m": newer,
        "execution_price_trusted": trusted, "price_source": fresh.get("price_source"),
        "policy": "SECOND_MARKET_FETCH_AFTER_CLOSE; SAME_RUN_ENTRY_REQUIRES_NEW_CONFIRMED_3M",
        "schema_version": "post_close_refresh_v9.5.31",
    }
    if not trusted:
        return {"accepted": False, "reason": "REFRESH_PRICE_UNTRUSTED", "audit": audit}
    if not newer:
        return {"accepted": False, "reason": "NO_NEW_CONFIRMED_3M_AFTER_CLOSE", "audit": audit}
    journal["learning_status"] = compute_learning_status(journal)
    warnings = learning_health_warnings(journal)
    fresh["learning_status"] = journal.get("learning_status", {})
    fresh["learning_warnings"] = warnings
    fresh["preconfirmation_events"] = list(journal.get("preconfirmation_events") or [])
    return {"accepted": True, "reason": "FRESH_SNAPSHOT_ACCEPTED", "context": fresh, "audit": audit}


# New policy invariants are validated through the same runtime audit entry point.
_validate_runtime_configuration_v9530 = validate_runtime_configuration
def validate_runtime_configuration() -> dict[str, Any]:
    report = _validate_runtime_configuration_v9530()
    errors = list(report.get("errors") or [])
    if not (ARMED_SCORE_BASE < RISKY_ENTRY_SCORE_BASE < ENTRY_SCORE_BASE):
        errors.append("Research/risky/full score floors must remain strictly ordered")
    if not (0.50 <= RESEARCH_PROBE_FORWARD_MIN_WIN_RATE <= 0.80):
        errors.append("Research probe forward win-rate gate is outside safe range")
    if RESEARCH_PROBE_FORWARD_MIN_TRADES < 4 or RESEARCH_PROBE_FORWARD_MIN_WINS < 3:
        errors.append("Research probe forward evidence floor is too small")
    if not (0.50 <= CONTEXT_EDGE_OOS_MIN_AUC <= 0.70 and 0.15 <= CONTEXT_EDGE_OOS_MAX_BRIER <= 0.40):
        errors.append("Context edge OOS gates are outside safe range")
    if not (0.50 <= ACCEPTANCE_CONFIRM_MAX_ZONE_DISTANCE_ATR < ACCEPTANCE_WAIT_RETEST_MAX_ZONE_DISTANCE_ATR <= 1.50):
        errors.append("Acceptance location-preservation envelope is invalid")
    if not (0.50 <= PROBE_INFORMATION_MFE_TRIGGER_R <= 1.0 and 0.20 <= PROBE_INFORMATION_GIVEBACK_RATIO <= 0.60):
        errors.append("PROBE information-protection thresholds are invalid")
    return {"valid": not errors, "errors": errors}


# Research shadow simulation for technically executable but not-yet-live 58-67 probes.
def _research_probe_episode_key(candidate: Candidate, context: dict[str, Any]) -> str:
    anchor = safe_float(getattr(candidate, "execution_anchor", 0.0), safe_float(getattr(candidate, "trigger_level", 0.0), safe_float(context.get("price"), 0.0)))
    atr = max(safe_float(context.get("atr15"), 0.0), 1e-6); bucket = int(round(anchor/max(atr*0.25, 1e-6)))
    ts = _preconfirm_as_of_ts(context) // (60*60_000)
    return f"{candidate.side}|{candidate.setup_type}|{candidate.execution_source}|A{bucket}|T{ts}"


def resolve_research_probe_shadow_events(journal: dict[str, Any], context: dict[str, Any]) -> int:
    events = journal.setdefault("research_probe_shadow_events", [])
    c3 = _confirmed_candles((context.get("candles") or {}).get("3m", []) or [], 80)
    if not c3:
        return 0
    now_ts = int(c3[-1].ts); resolved = 0
    for ev in events:
        if not isinstance(ev, dict) or ev.get("status") != "PENDING":
            continue
        observed = int(ev.get("observed_ts") or 0); horizon = int(ev.get("horizon_ts") or 0)
        if now_ts < horizon:
            continue
        path = [c for c in c3 if observed < int(c.ts) <= horizon]
        if not path:
            continue
        entry=safe_float(ev.get("entry"),0.0); stop=safe_float(ev.get("stop"),0.0); tp0=safe_float(ev.get("tp0"),0.0); tp1=safe_float(ev.get("tp1"),0.0)
        risk=max(abs(entry-stop),1e-9); sign=1 if ev.get("side")==Side.LONG.value else -1
        best=max(sign*(c.high-entry) if sign>0 else sign*(c.low-entry) for c in path)/risk
        worst=max(-sign*(c.low-entry) if sign>0 else -sign*(c.high-entry) for c in path)/risk
        terminal="HORIZON"; simulated_r=sign*(path[-1].close-entry)/risk
        for c in path:
            stop_hit = c.low <= stop if sign>0 else c.high >= stop
            tp1_hit = c.high >= tp1 if sign>0 else c.low <= tp1
            tp0_hit = c.high >= tp0 if sign>0 else c.low <= tp0
            if stop_hit:
                terminal="STOP"; simulated_r=-1.0; break
            if tp1_hit:
                terminal="TP1"; simulated_r=max(1.0, abs(tp1-entry)/risk); break
            if tp0_hit and terminal=="HORIZON":
                terminal="TP0_THEN_HORIZON"
        ev.update({"status":"RESOLVED","resolved_at":iso_now(),"mfe_r":round(max(0.0,best),6),"mae_r":round(max(0.0,worst),6),"terminal":terminal,"simulated_result_r":round(simulated_r,6),"simulator":"CONSERVATIVE_OHLC_STOP_FIRST_NO_INTRABAR_MAGIC"})
        resolved += 1
    return resolved


def record_research_probe_shadow_event(journal: dict[str, Any], context: dict[str, Any], candidate: Candidate, plan: Optional[TradePlan], policy: dict[str, Any]) -> bool:
    if not plan or not plan.valid or not plan.execution_ready or not policy.get("technical_probe") or policy.get("live_allowed"):
        return False
    key = _research_probe_episode_key(candidate, context); store=journal.setdefault("research_probe_shadow_events", [])
    if any(isinstance(x,dict) and x.get("episode_key")==key for x in store[-300:]):
        return False
    ts=_preconfirm_as_of_ts(context)
    store.append({"episode_key":key,"observed_ts":ts,"horizon_ts":ts+RESEARCH_PROBE_HORIZON_MINUTES*60_000,"status":"PENDING","side":candidate.side,"setup_type":candidate.setup_type,"execution_source":candidate.execution_source,"regime":str((candidate.score_components or {}).get("current_regime") or context.get("regime") or "UNKNOWN"),"score":candidate.final_score,"entry":plan.entry,"stop":plan.stop,"tp0":plan.tp0,"tp1":plan.tp1,"policy_snapshot":json_safe(policy),"schema_version":"research_probe_shadow_v9.5.31"})
    if len(store)>RESEARCH_PROBE_LEDGER_LIMIT: del store[:-RESEARCH_PROBE_LEDGER_LIMIT]
    return True


_evaluate_new_setup_v9530 = evaluate_new_setup
def evaluate_new_setup(context: dict, state: dict, journal: dict) -> Decision:
    resolve_research_probe_shadow_events(journal, context)
    decision = _evaluate_new_setup_v9530(context, state, journal)
    if decision.candidate is not None and decision.plan is not None:
        policy = production_research_probe_profile(journal, decision.candidate)
        if policy.get("mode") == "RESEARCH_SHADOW_ONLY":
            recorded = record_research_probe_shadow_event(journal, context, decision.candidate, decision.plan, policy)
            decision.audit.setdefault("production_research_separation", {}).update({**policy, "research_shadow_recorded": recorded})
    return decision


# PROBE MFE information protection is independent from actual TP0 partial realization.
_tp0_profit_protection_v9530 = _tp0_profit_protection
def _tp0_profit_protection(trade: ActiveTrade, context: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    is_probe = str(getattr(trade, "entry_stage", "") or "").upper() == EntryStage.PROBE.value
    if TP0_PROTECT_ENABLED and is_probe and not getattr(trade,"tp0_hit",False) and not getattr(trade,"tp1_hit",False):
        peak = _protection_mfe_r(trade); price=safe_float(context.get("price"),trade.entry); current=_protection_current_r(trade,price)
        giveback=max(0.0,(peak-current)/max(peak,1e-9)) if peak>0 else 0.0
        profile={"eligible":peak>=PROBE_INFORMATION_MFE_TRIGGER_R,"activated":bool(getattr(trade,"pre_tp1_protection_locked",False)),"information_only":True,"profit_partial_taken":False,"peak_mfe_r":round(peak,6),"current_r":round(current,6),"giveback_ratio":round(giveback,6),"threshold":PROBE_INFORMATION_GIVEBACK_RATIO,"mfe_trigger_r":PROBE_INFORMATION_MFE_TRIGGER_R,"threshold_scope":"PROBE_INFORMATION_MFE","policy":"INFORMATION_PROTECTION_BEFORE_TP0; TP0_PARTIAL_UNCHANGED"}
        result["mfe_giveback_ratio"]=round(giveback,6)
        if peak < PROBE_INFORMATION_MFE_TRIGGER_R:
            result["profit_protection"]=profile; return profile
        trade.protection_peak_mfe_r=round(max(safe_float(getattr(trade,"protection_peak_mfe_r",0.0),0.0),peak),6)
        if giveback < PROBE_INFORMATION_GIVEBACK_RATIO:
            trade.management_state="SUPPORTED"; result["management_state"]="SUPPORTED"; result["profit_protection"]=profile; return profile
        target=_strict_breakeven_stop(trade)
        applied=_apply_protective_stop(trade,context,target)
        if applied or _stop_locked_r(trade)>=_stop_locked_r(trade,target)-1e-6:
            trade.pre_tp1_protection_locked=True; trade.pre_tp1_protection_at=trade.pre_tp1_protection_at or iso_now(); trade.pre_tp1_protection_ratio=round(giveback,6); trade.pre_tp1_protection_threshold=PROBE_INFORMATION_GIVEBACK_RATIO; trade.pre_tp1_protection_scope="PROBE_INFORMATION_MFE"; trade.management_state="PROTECT"
            trade.protection_activation_mfe_r=round(peak,6); trade.protection_activation_current_r=round(current,6); trade.protection_activation_stop=round_price(trade.stop_current)
            profile.update({"activated":True,"state":"PROTECT","recommended_stop":round_price(trade.stop_current),"tp0_hit_remains":False})
            result["recommended_stop"]=round_price(trade.stop_current); result["recommended_stop_reason"]="PROBE information MFE protection; no TP0 partial taken"; result["management_state"]="PROTECT"
            _append_ratchet_evidence(trade,context,"PROBE_INFORMATION_PROTECTION_ACTIVATED",peak_mfe_r=round(peak,6),current_r=round(current,6),giveback_ratio=round(giveback,6),stop=round_price(trade.stop_current),tp0_hit=False)
        else:
            profile["state"]="WEAKENING"; result["management_state"]="WEAKENING"
        result["profit_protection"]=profile; return profile
    return _tp0_profit_protection_v9530(trade, context, result)


_compute_learning_status_v9530 = compute_learning_status
def compute_learning_status(journal: dict[str, Any]) -> dict[str, Any]:
    status = _compute_learning_status_v9530(journal)
