def _v9532_softmax(scores: dict[str, float]) -> dict[str, float]:
    if not scores:
        return {}
    m = max(scores.values())
    exps = {k: math.exp(clamp(v - m, -30.0, 30.0)) for k, v in scores.items()}
    total = sum(exps.values()) or 1.0
    return {k: v / total for k, v in exps.items()}


def _v9532_recent_confirmed(context: dict[str, Any], timeframe: str, n: int) -> list[Candle]:
    rows = [c for c in ((context.get("candles") or {}).get(timeframe) or []) if getattr(c, "confirmed", True)]
    return sorted(rows, key=lambda c: int(getattr(c, "ts", 0) or 0))[-n:]



def regime_probability_vector(context: dict[str, Any]) -> dict[str, Any]:
    """Probabilistic market-state representation with explicit direction.

    The legacy categorical regime is only a prior. Trend probability is split
    into bullish/bearish components so a SHORT continuation does not receive the
    same regime support as a LONG continuation inside a bullish impulse.
    """
    c15 = _v9532_recent_confirmed(context, "15m", 20)
    label = str(context.get("regime") or Regime.NORMAL.value).upper()
    scores = {
        "TREND_CONTINUATION": 0.0,
        "MEAN_REVERSION": 0.0,
        "RANGE_EXPANSION": 0.0,
        "REVERSAL": 0.0,
        "SHOCK": 0.0,
    }
    label_boosts = {
        Regime.TREND.value: ("TREND_CONTINUATION", 1.35),
        Regime.RANGE.value: ("MEAN_REVERSION", 1.20),
        Regime.TRANSITION.value: ("REVERSAL", 0.90),
        Regime.SHOCK.value: ("SHOCK", 1.55),
        Regime.NORMAL.value: ("RANGE_EXPANSION", 0.25),
    }
    k, v = label_boosts.get(label, ("RANGE_EXPANSION", 0.15))
    scores[k] += v
    efficiency = 0.0
    range_ratio = 1.0
    shock_ratio = 1.0
    directional = 0.0
    if len(c15) >= 8:
        closes = [safe_float(c.close) for c in c15]
        path = sum(abs(closes[i] - closes[i-1]) for i in range(1, len(closes)))
        net_signed = closes[-1] - closes[0]
        net = abs(net_signed)
        efficiency = clamp(net / max(path, 1e-9), 0.0, 1.0)
        directional = 1.0 if net_signed > 0 else -1.0 if net_signed < 0 else 0.0
        ranges = [max(safe_float(c.high)-safe_float(c.low), 1e-9) for c in c15]
        recent_mean = mean(ranges[-4:])
        baseline = median(ranges[:-4] or ranges)
        range_ratio = recent_mean / max(baseline, 1e-9)
        shock_ratio = ranges[-1] / max(median(ranges[:-1] or ranges), 1e-9)
        scores["TREND_CONTINUATION"] += 1.25 * efficiency + 0.25 * max(0.0, range_ratio-1.0)
        scores["MEAN_REVERSION"] += 1.10 * (1.0-efficiency) + 0.35 * max(0.0, 1.0-range_ratio)
        scores["RANGE_EXPANSION"] += 0.80 * max(0.0, range_ratio-0.75) + 0.35 * (1.0-efficiency)
        scores["SHOCK"] += 1.20 * max(0.0, shock_ratio-1.45)
        if len(c15) >= 12:
            first = c15[-12:-6]
            last = c15[-6:]
            def _eff(q: list[Candle]) -> float:
                cs=[safe_float(x.close) for x in q]
                pp=sum(abs(cs[i]-cs[i-1]) for i in range(1,len(cs)))
                return abs(cs[-1]-cs[0])/max(pp,1e-9) if len(cs)>1 else 0.0
            decay=max(0.0,_eff(first)-_eff(last))
            scores["REVERSAL"] += 1.35*decay
    probs = _v9532_softmax(scores)
    trend_p = safe_float(probs.get("TREND_CONTINUATION"), 0.0)
    if directional > 0:
        bull_share = 0.5 + 0.5 * efficiency
    elif directional < 0:
        bull_share = 0.5 - 0.5 * efficiency
    else:
        bull_share = 0.5
    bull_share = clamp(bull_share, 0.0, 1.0)
    bullish_trend_p = trend_p * bull_share
    bearish_trend_p = trend_p * (1.0 - bull_share)
    entropy = -sum(p*math.log(max(p,1e-12)) for p in probs.values()) / math.log(max(len(probs),2))
    dominant = max(probs, key=probs.get) if probs else "UNKNOWN"
    return {
        "probabilities": {k: round(v,6) for k,v in probs.items()},
        "dominant": dominant,
        "uncertainty": round(clamp(entropy,0.0,1.0),6),
        "legacy_label": label,
        "directional_sign": directional,
        "directional_bias": "BULLISH" if directional > 0 else "BEARISH" if directional < 0 else "NEUTRAL",
        "directional_efficiency": round(efficiency,6),
        "bullish_trend_probability": round(bullish_trend_p, 6),
        "bearish_trend_probability": round(bearish_trend_p, 6),
        "relative_range_ratio": round(range_ratio,6),
        "shock_ratio": round(shock_ratio,6),
        "schema_version": REGIME_VECTOR_SCHEMA_VERSION,
    }


def candidate_regime_fit_probability_v9533(regime_vector: dict[str, Any], candidate: Candidate, kind: str) -> float:
    """Candidate-side-aware regime support; advisory/routing only."""
    probs = dict(regime_vector.get("probabilities") or {})
    side = str(getattr(candidate, "side", "") or "")
    kind = str(kind or "CONTINUATION")
    side_trend = safe_float(
        regime_vector.get("bullish_trend_probability" if side == Side.LONG.value else "bearish_trend_probability"),
        safe_float(probs.get("TREND_CONTINUATION"), 0.0) * 0.5,
    )
    mean_rev = safe_float(probs.get("MEAN_REVERSION"), 0.0)
    expansion = safe_float(probs.get("RANGE_EXPANSION"), 0.0)
    reversal = safe_float(probs.get("REVERSAL"), 0.0)
    directional = safe_float(regime_vector.get("directional_sign"), 0.0)
    if kind == "AUCTION_MEAN":
        support = mean_rev + 0.25 * reversal + 0.10 * expansion
    elif kind == "REVERSAL":
        prior_move_against_candidate = (
            (side == Side.LONG.value and directional < 0)
            or (side == Side.SHORT.value and directional > 0)
        )
        direction_factor = 1.0 if prior_move_against_candidate else 0.45 if directional else 0.70
        support = reversal * direction_factor + 0.35 * mean_rev
    elif kind == "BREAKOUT":
        support = side_trend + 0.55 * expansion
    else:
        support = side_trend + 0.25 * expansion
    return clamp(support, 0.0, 1.0)


def _weighted_score_percentile_v9533(
    rows: list[dict[str, Any]], setup_type: str, value: float, *, min_exact: int = 3,
) -> dict[str, Any]:
    """Past-only recency-weighted within-setup percentile.

    Raw score scales drift as detectors/calibration evolve. Comparing an occurrence
    with recent history of the same setup is more stable than treating score=78 as
    equally exceptional across every model and every bot generation.
    """
    exact=[(i,row) for i,row in enumerate(rows) if str(row.get("setup_type") or "")==str(setup_type) and row.get("score") is not None]
    source="EXACT_SETUP"
    selected=exact
    if len(selected)<min_exact:
        selected=[(i,row) for i,row in enumerate(rows) if row.get("score") is not None]
        source="GLOBAL_FALLBACK"
    if not selected:
        return {"percentile":0.5,"n":0,"effective_n":0.0,"source":"NO_HISTORY","value":value}
    half_life=max(safe_float(globals().get("CONTEXT_EDGE_RECENCY_HALF_LIFE_TRADES"),45.0),1.0)
    last_index=max(len(rows)-1,0)
    less=equal=total=weight_sq=0.0
    for idx,row in selected:
        age=max(0,last_index-idx)
        weight=0.5**(age/half_life)
        score=safe_float(row.get("score"),0.0)
        total+=weight
        weight_sq+=weight*weight
        if score<value:
            less+=weight
        elif abs(score-value)<=1e-9:
            equal+=weight
    percentile=(less+0.5*equal)/max(total,1e-9)
    effective_n=(total*total/max(weight_sq,1e-9)) if weight_sq>0 else 0.0
    return {
        "percentile":round(clamp(percentile,0.0,1.0),6),
        "n":len(selected),
        "effective_n":round(effective_n,3),
        "source":source,
        "value":value,
        "recency_half_life_trades":half_life,
        "schema_version":"setup_relative_quality_v9.5.33_recency_weighted",
    }


def setup_relative_quality_percentile(journal: Optional[dict[str, Any]], candidate: Optional[Candidate], *, historical_rows: Optional[list[dict[str, Any]]] = None) -> dict[str, Any]:
    if candidate is None:
        return {"percentile": 0.5, "n": 0, "source": "NO_CANDIDATE"}
    rows = historical_rows if historical_rows is not None else [t for t in ((journal or {}).get("trades") or []) if isinstance(t,dict)]
    setup = str(getattr(candidate,"setup_type","") or "")
    value = safe_float(getattr(candidate,"final_score",0.0),0.0)
    return _weighted_score_percentile_v9533(rows,setup,value)


def control_transfer_score(context: dict[str, Any], candidate: Candidate) -> dict[str, Any]:
    """Continuous microstructure-control score for reversal/structural entries."""
    q=_v9532_recent_confirmed(context,"3m",8)
    if len(q)<6:
        return {"score":50.0,"status":"INSUFFICIENT_3M","schema_version":"control_transfer_v9.5.32"}
    side=str(candidate.side); sign=side_sign(side); atr=max(safe_float(context.get("atr15"),0.0),1e-9)
    recent=q[-6:]; closes=[safe_float(c.close) for c in recent]
    directional_closes=sum(1 for c in recent if sign*(safe_float(c.close)-safe_float(c.open))>0)
    net=sign*(closes[-1]-closes[0])/atr
    path=sum(abs(closes[i]-closes[i-1]) for i in range(1,len(closes)))/atr
    efficiency=clamp(max(0.0,net)/max(path,0.05),0.0,1.0)
    last=recent[-1]; rng=max(safe_float(last.high)-safe_float(last.low),1e-9); body=sign*(safe_float(last.close)-safe_float(last.open)); body_ratio=max(0.0,body)/rng
    if sign>0:
        protected=max(safe_float(c.high) for c in recent[:3]); structure_break=max(safe_float(c.close) for c in recent[3:])>protected+atr*0.02
        retrace=min(safe_float(c.low) for c in recent[-3:])>min(safe_float(c.low) for c in recent[:3])-atr*0.08
    else:
        protected=min(safe_float(c.low) for c in recent[:3]); structure_break=min(safe_float(c.close) for c in recent[3:])<protected-atr*0.02
        retrace=max(safe_float(c.high) for c in recent[-3:])<max(safe_float(c.high) for c in recent[:3])+atr*0.08
    score=(25.0*(directional_closes/6.0)+25.0*efficiency+20.0*clamp(max(0.0,net)/0.45,0.0,1.0)+15.0*clamp(body_ratio/0.65,0.0,1.0)+10.0*float(structure_break)+5.0*float(retrace))
    return {"score":round(clamp(score,0.0,100.0),2),"directional_closes":directional_closes,"net_move_atr":round(net,4),"efficiency":round(efficiency,4),"structure_break":bool(structure_break),"hold_after_break":bool(retrace),"last_body_ratio":round(body_ratio,4),"schema_version":"control_transfer_v9.5.32"}


def continuation_integrity_score(context: dict[str, Any], candidate: Candidate) -> dict[str, Any]:
    q=_v9532_recent_confirmed(context,"3m",10)
    if len(q)<6:
        return {"score":50.0,"status":"INSUFFICIENT_3M","schema_version":"continuation_integrity_v9.5.32"}
    side=str(candidate.side); sign=side_sign(side); atr=max(safe_float(context.get("atr15"),0.0),1e-9); recent=q[-8:]
    closes=[safe_float(c.close) for c in recent]; directional=sum(1 for c in recent if sign*(safe_float(c.close)-safe_float(c.open))>0)
    net=sign*(closes[-1]-closes[0])/atr; path=sum(abs(closes[i]-closes[i-1]) for i in range(1,len(closes)))/atr
    eff=clamp(max(0.0,net)/max(path,0.05),0.0,1.0)
    if sign>0:
        adverse=max(0.0,max(closes)-closes[-1])/atr
    else:
        adverse=max(0.0,closes[-1]-min(closes))/atr
    htf=clamp((safe_float(get_htf_fact(candidate).get("alignment_score"),0.0)+1.0)/2.0,0.0,1.0)
    freshness=clamp(1.0-candidate_execution_trigger_age_minutes(candidate)/max(float(EXECUTION_TRIGGER_TTL_MIN),1.0),0.0,1.0)
    score=28.0*(directional/8.0)+27.0*eff+20.0*clamp(max(0.0,net)/0.75,0.0,1.0)+15.0*htf+10.0*freshness-20.0*clamp(adverse/0.8,0.0,1.0)
    return {"score":round(clamp(score,0.0,100.0),2),"directional_closes":directional,"net_move_atr":round(net,4),"efficiency":round(eff,4),"adverse_pullback_atr":round(adverse,4),"htf_alignment01":round(htf,4),"freshness":round(freshness,4),"schema_version":"continuation_integrity_v9.5.32"}


def liquidity_runway_profile(context: dict[str, Any], candidate: Candidate, plan: Optional[TradePlan]=None) -> dict[str, Any]:
    price=safe_float(context.get("price"),0.0); atr=max(safe_float(context.get("atr15"),0.0),price*0.001,1e-6)
    if price<=0:
        return {"runway_r":1.5,"score":50.0,"known":False,"schema_version":"liquidity_runway_v9.5.32"}
    if plan is not None:
        risk=max(abs(safe_float(plan.entry,price)-safe_float(plan.stop,price)),ABS_MIN_STOP_DOLLARS,1e-6)
    else:
        risk=max(abs(price-safe_float(getattr(candidate,"invalidation_level",price),price)),ABS_MIN_STOP_DOLLARS,atr*MIN_STOP_ATR15,1e-6)
    targets=[]
    try:
        targets=find_technical_targets(candidate.side,price,context.get("zones") or [],context.get("liquidity") or {},atr,macro=context.get("macro_liquidity") or {})
    except Exception:
        targets=[]
    favorable=[]
    sign=side_sign(candidate.side)
    for t in targets:
        level=safe_float((t or {}).get("level"),0.0)
        if level>0 and sign*(level-price)>0:
            favorable.append((sign*(level-price),t))
    favorable.sort(key=lambda x:x[0])
    if favorable:
        dist,t=favorable[0]; runway=dist/risk; known=True; kind=str((t or {}).get("kind") or "TECHNICAL")
    else:
        runway=1.5; known=False; kind="NO_QUALIFIED_TARGET"
    score=100.0*clamp((runway-0.5)/2.5,0.0,1.0) if known else 50.0
    return {"runway_r":round(runway,4),"score":round(score,2),"known":known,"nearest_target_kind":kind,"risk_distance":round(risk,6),"schema_version":"liquidity_runway_v9.5.32"}



def adverse_selection_index(context: dict[str, Any], candidate: Candidate, runway: Optional[dict[str,Any]]=None) -> dict[str, Any]:
    """Signed, setup-family-aware adverse-selection estimate.

    Favorable-direction extension from the execution anchor is a chase risk and
    is penalized more than an equally-sized value-side retest. No hard block is
    produced; the index only changes execution tactic.
    """
    price=safe_float(context.get("price"),0.0)
    atr=max(safe_float(context.get("atr15"),0.0),price*0.001,1e-6)
    sign=side_sign(candidate.side)
    anchor=safe_float(getattr(candidate,"execution_anchor",0.0),safe_float(getattr(candidate,"trigger_level",price),price)) or price
    signed_extension=sign*(price-anchor)/atr
    distance=abs(price-anchor)/atr
    kind=str((SETUP_STATE_MACHINE_REGISTRY.get(str(candidate.setup_type)) or {}).get("kind") or "CONTINUATION")
    q=_v9532_recent_confirmed(context,"3m",8)
    consumed=0.0
    wick_exhaustion=0.0
    if len(q)>=4:
        consumed=max(0.0,sign*(safe_float(q[-1].close)-safe_float(q[0].open))/atr)
        last=q[-1]
        rng=max(safe_float(last.high)-safe_float(last.low),1e-9)
        wick=(safe_float(last.high)-max(safe_float(last.open),safe_float(last.close))) if sign>0 else (min(safe_float(last.open),safe_float(last.close))-safe_float(last.low))
        wick_exhaustion=clamp(wick/rng,0.0,1.0)
    age=max(0.0,candidate_execution_trigger_age_minutes(candidate))
    freshness_pen=clamp(age/max(float(EXECUTION_TRIGGER_TTL_MIN),1.0),0.0,1.5)
    loc=clamp(safe_float(getattr(candidate,"location_score",50),50.0)/100.0,0.0,1.0)
    runway=runway or liquidity_runway_profile(context,candidate)
    runway_r=safe_float(runway.get("runway_r"),1.5)
    opposing_pen=clamp((1.4-runway_r)/1.4,0.0,1.0)
    # Normal retest depth should not be treated as FOMO. Chase extension is more
    # dangerous for continuation; reversal gets slightly more room after control transfer.
    favorable_chase=max(0.0,signed_extension)
    distance_metric=0.55*distance+0.45*favorable_chase
    distance_scale=1.30 if kind in {"REVERSAL","AUCTION_MEAN"} else 1.15
    impulse_weight=18.0 if kind in {"REVERSAL","AUCTION_MEAN"} else 24.0
    score=(
        34.0*clamp(distance_metric/distance_scale,0.0,1.0)
        + impulse_weight*clamp(consumed/2.0,0.0,1.0)
        + 16.0*freshness_pen
        + 12.0*wick_exhaustion
        + 10.0*(1.0-loc)
        + 14.0*opposing_pen
    )
    reasons=[]
    if favorable_chase>0.70: reasons.append("FAVORABLE_DIRECTION_CHASE_FROM_ANCHOR")
    elif distance>0.90: reasons.append("FAR_FROM_EXECUTION_ANCHOR")
    if consumed>1.35: reasons.append("IMPULSE_ALREADY_CONSUMED")
    if age>EXECUTION_TRIGGER_TTL_MIN*0.65: reasons.append("TRIGGER_MATURING")
    if opposing_pen>0.45: reasons.append("OPPOSING_LIQUIDITY_CLOSE")
    return {
        "index":round(clamp(score,0.0,100.0),2),
        "distance_from_anchor_atr":round(distance,4),
        "signed_extension_atr":round(signed_extension,4),
        "favorable_chase_atr":round(favorable_chase,4),
        "impulse_consumed_atr":round(consumed,4),
        "trigger_age_minutes":round(age,2),
        "wick_exhaustion":round(wick_exhaustion,4),
        "location_quality01":round(loc,4),
        "opposing_liquidity_penalty":round(opposing_pen,4),
        "setup_kind":kind,
        "reasons":reasons,
        "hard_block":False,
        "schema_version":"adverse_selection_v9.5.33_signed_family_aware",
    }



def native_setup_execution_evidence_v9533(candidate: Candidate, control_threshold: float) -> dict[str, Any]:
    """Bridge setup-native execution facts into the generic state machine.

    The new state machine must not contradict a stricter setup-specific detector
    that has already produced a fresh execution source. Native readiness is only
    supportive; it never resurrects stale/no-source candidates.
    """
    reval=dict(getattr(candidate,"revalidation_profile",{}) or {})
    conf=dict(getattr(candidate,"confirmation_state",{}) or {})
    shortp=dict(getattr(candidate,"short_reversal_profile",{}) or {})
    source=str(getattr(candidate,"execution_source",ExecutionSource.NONE.value) or ExecutionSource.NONE.value)
    native_trigger=bool(
        getattr(candidate,"trigger_ready",False)
        or getattr(candidate,"live_3m_trigger_ready",False)
    )
    entry_supported=bool(reval.get("entry_supported", True))
    source_valid=source != ExecutionSource.NONE.value
    native_ready=bool(native_trigger and source_valid and entry_supported)

    support_values=[]
    for key in ("acceptance_quality","execution_quality","micro_score","score","quality"):
        if key in conf:
            support_values.append(safe_float(conf.get(key),0.0))
        if key in reval:
            support_values.append(safe_float(reval.get(key),0.0))
        if key in shortp:
            support_values.append(safe_float(shortp.get(key),0.0))
    native_score=max(support_values, default=0.0)
    if native_ready:
        native_score=max(native_score, control_threshold + 4.0)
    return {
        "native_ready":native_ready,
        "native_trigger":native_trigger,
        "source_valid":source_valid,
        "entry_supported":entry_supported,
        "native_score":round(clamp(native_score,0.0,100.0),2),
        "execution_source":source,
        "policy":"NATIVE_SETUP_CONTRACT_MAY_SUPPORT_GENERIC_STATE_BUT_NEVER_RESURRECT_STALE_OR_NO_SOURCE_PATH",
        "schema_version":"native_setup_contract_bridge_v9.5.33",
    }


def setup_state_machine_profile(context: dict[str, Any], candidate: Candidate, *, control: Optional[dict[str,Any]]=None, continuation: Optional[dict[str,Any]]=None, asi: Optional[dict[str,Any]]=None) -> dict[str, Any]:
    contract=SETUP_STATE_MACHINE_REGISTRY.get(str(candidate.setup_type),{"kind":"CONTINUATION","phases":["THESIS","LOCATION","CONTROL","TRIGGER","EXECUTION","MANAGEMENT"],"preferred_tactics":list(EXECUTION_ROUTER_ACTIONS)})
    kind=str(contract.get("kind") or "CONTINUATION")
    control=control or control_transfer_score(context,candidate)
    continuation=continuation or continuation_integrity_score(context,candidate)
    asi=asi or adverse_selection_index(context,candidate)
    thesis=bool(int(getattr(candidate,"final_score",0) or 0)>=ARMED_SCORE_BASE or getattr(candidate,"trigger_ready",False))
    location_limit=safe_float(contract.get("location_asi_limit"),72.0)
    location=bool(safe_float(asi.get("index"),50.0)<location_limit)
    generic_structural=safe_float(control.get("score"),50.0) if kind in {"REVERSAL","AUCTION_MEAN"} else safe_float(continuation.get("score"),50.0)
    control_threshold=safe_float(contract.get("control_threshold"),52.0)
    native=native_setup_execution_evidence_v9533(candidate,control_threshold)
    structural_score=max(generic_structural,safe_float(native.get("native_score"),0.0)) if native.get("native_ready") else generic_structural
    control_ready=structural_score>=control_threshold
    trigger=bool(native.get("native_ready") or getattr(candidate,"trigger_ready",False) or getattr(candidate,"live_3m_trigger_ready",False))
    phase_states={"THESIS":thesis,"LOCATION":location,"CONTROL":control_ready,"TRIGGER":trigger}
    if not thesis:
        current="THESIS"
    elif not location:
        current="LOCATION"
    elif not control_ready:
        current="CONTROL"
    elif not trigger:
        current="TRIGGER"
    else:
        current="EXECUTION"
    return {
        "setup_type":candidate.setup_type,
        "kind":kind,
        "current_state":current,
        "phase_states":phase_states,
        "structural_score":round(structural_score,2),
        "generic_structural_score":round(generic_structural,2),
        "native_execution_bridge":native,
        "control_threshold":round(control_threshold,2),
        "location_asi_limit":round(location_limit,2),
        "location_semantic":str(contract.get("location") or "SETUP_LOCATION"),
        "control_semantic":str(contract.get("control") or "STRUCTURAL_CONTROL"),
        "trigger_semantic":str(contract.get("trigger") or "SETUP_TRIGGER"),
        "preferred_tactics":list(contract.get("preferred_tactics") or EXECUTION_ROUTER_ACTIONS),
        "management_state":"PENDING" if current!="EXECUTION" else "READY_AFTER_EXECUTION",
        "hard_setup_block":False,
        "policy":"SETUP_NATIVE_CONTRACT + GENERIC_INTELLIGENCE; NATIVE DETECTOR READINESS IS NEVER CONTRADICTED BY A GENERIC SCORE",
        "schema_version":"setup_state_machine_v9.5.33_native_contract_bridge",
    }


# ---------------- Outcome ML: P(TP0 before invalidation) ----------------
OUTCOME_FEATURE_NAMES=("score_rel","setup_quality","timing_quality","entry_quality","is_long","regime_trend","regime_range","regime_transition","asi_inverse","structural_integrity","runway","regime_certainty")


def _outcome_trade_rows(journal: Optional[dict[str,Any]]) -> list[dict[str,Any]]:
    rows=[]
    for t in ((journal or {}).get("trades") or []):
        if not isinstance(t,dict) or "tp0_hit" not in t or t.get("tp0_hit") is None: continue
        if t.get("ml_eligible") is False: continue
        rows.append(t)
    return rows


def _historical_setup_percentile(rows: list[dict[str,Any]], idx: int) -> float:
    row=rows[idx]; setup=str(row.get("setup_type") or ""); value=safe_float(row.get("score"),70.0)
    hist=rows[:idx]; vals=[safe_float(x.get("score"),70.0) for x in hist if str(x.get("setup_type") or "")==setup]
    if len(vals)<3: vals=[safe_float(x.get("score"),70.0) for x in hist]
    if not vals: return 0.5
    return clamp((sum(v<value for v in vals)+0.5*sum(abs(v-value)<=1e-9 for v in vals))/len(vals),0.0,1.0)


def _outcome_features_from_trade(rows: list[dict[str,Any]], idx: int) -> dict[str,float]:
    t=rows[idx]; reg=str(t.get("opened_regime") or t.get("regime") or "").upper(); intel=dict(t.get("execution_intelligence") or {})
    return {
        "score_rel":_historical_setup_percentile(rows,idx),
        "setup_quality":clamp(safe_float(t.get("setup_quality"),50.0)/100.0,0.0,1.0),
        "timing_quality":clamp(safe_float(t.get("timing_quality"),50.0)/100.0,0.0,1.0),
        "entry_quality":clamp(safe_float(t.get("evaluation_entry_quality"),50.0)/100.0,0.0,1.0),
        "is_long":1.0 if str(t.get("side") or "").upper()==Side.LONG.value else 0.0,
        "regime_trend":1.0 if reg==Regime.TREND.value else 0.0,
        "regime_range":1.0 if reg==Regime.RANGE.value else 0.0,
        "regime_transition":1.0 if reg==Regime.TRANSITION.value else 0.0,
        "asi_inverse":clamp(1.0-safe_float(intel.get("asi"),50.0)/100.0,0.0,1.0),
        "structural_integrity":clamp(safe_float(intel.get("structural"),50.0)/100.0,0.0,1.0),
        "runway":clamp(safe_float(intel.get("runway_r"),1.5)/3.0,0.0,1.0),
        "regime_certainty":clamp(1.0-safe_float(intel.get("regime_uncertainty"),0.5),0.0,1.0),
    }


def _fit_outcome_logistic(feature_rows: list[tuple[dict[str,float],int]]) -> dict[str,float]:
    coef={"bias":0.0,**{k:0.0 for k in OUTCOME_FEATURE_NAMES}}
    if len(feature_rows)<8: return coef
    for epoch in range(120):
        grad={k:0.0 for k in coef}
        for x,y in feature_rows:
            z=coef["bias"]+sum(coef[k]*safe_float(x.get(k),0.0) for k in OUTCOME_FEATURE_NAMES); p=_sigmoid(z); err=p-y
            grad["bias"]+=err
            for k in OUTCOME_FEATURE_NAMES: grad[k]+=err*safe_float(x.get(k),0.0)
        lr=0.09/math.sqrt(1.0+epoch*0.06); n=max(len(feature_rows),1)
        for k in coef:
            reg=0.0 if k=="bias" else 0.025*coef[k]
            coef[k]-=lr*(grad[k]/n+reg)
    return coef


def _predict_outcome_logistic(coef: dict[str,float], features: dict[str,float]) -> float:
    return clamp(_sigmoid(safe_float(coef.get("bias"),0.0)+sum(safe_float(coef.get(k),0.0)*safe_float(features.get(k),0.0) for k in OUTCOME_FEATURE_NAMES)),0.02,0.98)

_OUTCOME_OOS_CACHE: dict[tuple[int,str],dict[str,Any]]={}
def outcome_model_oos_status(journal: Optional[dict[str,Any]]) -> dict[str,Any]:
    rows=_outcome_trade_rows(journal); key=(len(rows),str((rows[-1] or {}).get("id") if rows else ""))
    if key in _OUTCOME_OOS_CACHE: return copy.deepcopy(_OUTCOME_OOS_CACHE[key])
    labels=[]; probs=[]
    for i in range(30,len(rows)):
        train=[(_outcome_features_from_trade(rows,j),1 if bool(rows[j].get("tp0_hit")) else 0) for j in range(i)]
        coef=_fit_outcome_logistic(train); x=_outcome_features_from_trade(rows,i); probs.append(_predict_outcome_logistic(coef,x)); labels.append(1 if bool(rows[i].get("tp0_hit")) else 0)
    auc=_auc_binary(probs,labels) if labels else 0.5; brier=mean((p-y)**2 for p,y in zip(probs,labels)) if labels else 0.25
    trusted=bool(len(labels)>=OUTCOME_MODEL_MIN_OOS and auc>=OUTCOME_MODEL_MIN_AUC and brier<=OUTCOME_MODEL_MAX_BRIER)
    out={"predictions":len(labels),"auc":round(auc,6),"brier":round(brier,6),"authority_trusted":trusted,"target":"P(TP0_BEFORE_INVALIDATION)","selection_uses_future_labels":False,"policy":"STRICT_CHRONOLOGICAL_OOS; NEW_FEATURES_DEFAULT_NEUTRAL_UNTIL_PERSISTED","schema_version":OUTCOME_MODEL_SCHEMA_VERSION}
    _OUTCOME_OOS_CACHE.clear(); _OUTCOME_OOS_CACHE[key]=copy.deepcopy(out); return out


def outcome_probability_profile(journal: Optional[dict[str,Any]], context: dict[str,Any], candidate: Candidate, intel_seed: dict[str,Any]) -> dict[str,Any]:
    rows=_outcome_trade_rows(journal); rel=setup_relative_quality_percentile(journal,candidate); rv=intel_seed.get("regime_vector") or regime_probability_vector(context)
    probs=dict(rv.get("probabilities") or {}); reg=str(context.get("regime") or "").upper()
    x={
        "score_rel":safe_float(rel.get("percentile"),0.5),
        "setup_quality":clamp(safe_float(getattr(candidate,"setup_quality_score",50),50)/100,0,1),
        "timing_quality":clamp(safe_float(getattr(candidate,"timing_quality_score",50),50)/100,0,1),
        "entry_quality":clamp(safe_float(getattr(candidate,"entry_quality_score",50),50)/100,0,1),
        "is_long":1.0 if candidate.side==Side.LONG.value else 0.0,
        "regime_trend":clamp(safe_float(probs.get("TREND_CONTINUATION"),1.0 if reg==Regime.TREND.value else 0.0),0,1),
        "regime_range":clamp(safe_float(probs.get("MEAN_REVERSION"),1.0 if reg==Regime.RANGE.value else 0.0),0,1),
        "regime_transition":clamp(safe_float(probs.get("REVERSAL"),1.0 if reg==Regime.TRANSITION.value else 0.0),0,1),
        "asi_inverse":clamp(1.0-safe_float((intel_seed.get("adverse_selection") or {}).get("index"),50)/100,0,1),
        "structural_integrity":clamp(safe_float(intel_seed.get("structural_score"),50)/100,0,1),
        "runway":clamp(safe_float((intel_seed.get("liquidity_runway") or {}).get("runway_r"),1.5)/3.0,0,1),
        "regime_certainty":clamp(1.0-safe_float(rv.get("uncertainty"),0.5),0,1),
    }
    train=[(_outcome_features_from_trade(rows,i),1 if bool(rows[i].get("tp0_hit")) else 0) for i in range(len(rows))]
    coef=_fit_outcome_logistic(train); raw=_predict_outcome_logistic(coef,x) if len(rows)>=OUTCOME_MODEL_MIN_ROWS else 0.5; oos=outcome_model_oos_status(journal)
    # Fail-soft: when old-history OOS is weak, model informs tactic uncertainty but cannot dominate.
    influence=1.0 if oos.get("authority_trusted") else 0.25 if len(rows)>=OUTCOME_MODEL_MIN_ROWS else 0.0
    p=0.5+(raw-0.5)*influence
    n_eff=max(8.0,min(float(len(rows)),80.0)*(1.0 if oos.get("authority_trusted") else 0.35)); se=math.sqrt(max(p*(1-p),1e-6)/n_eff); lo=clamp(p-1.64*se,0.01,0.99); hi=clamp(p+1.64*se,0.01,0.99)
    return {"probability":round(p,6),"raw_probability":round(raw,6),"interval_90":[round(lo,6),round(hi,6)],"uncertainty_width":round(hi-lo,6),"features":{k:round(v,6) for k,v in x.items()},"sample_size":len(rows),"oos_validation":oos,"authority_trusted":bool(oos.get("authority_trusted")),"target":"P(TP0_BEFORE_INVALIDATION)","confirmation_model_separate":True,"schema_version":OUTCOME_MODEL_SCHEMA_VERSION}


def _parse_time_any(value: Any) -> Optional[datetime]:
    try:
        if not value: return None
        dt=datetime.fromisoformat(str(value).replace("Z","+00:00")); return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    except Exception: return None



def survival_hazard_profile(journal: Optional[dict[str,Any]], candidate: Candidate) -> dict[str,Any]:
    """Time-to-edge profile using exact TP0 timestamps when available.

    Legacy rows without TP0 timestamps are retained only as weak descriptive
    evidence. They may not drive aggressive route timing because closed_at is an
    upper bound on TP0 time, not the event time itself.
    """
    trades=[t for t in ((journal or {}).get("trades") or []) if isinstance(t,dict) and "tp0_hit" in t]
    exact_scope=[t for t in trades if str(t.get("setup_type") or "")==str(candidate.setup_type) and str(t.get("execution_source") or "")==str(candidate.execution_source) and str(t.get("side") or "")==str(candidate.side)]
    sample=exact_scope if len(exact_scope)>=4 else [t for t in trades if str(t.get("setup_type") or "")==str(candidate.setup_type)]
    if len(sample)<4:
        sample=trades

    exact_times=[]
    legacy_success_upper_bounds=[]
    success_flags=[]
    for t in sample:
        opened=_parse_time_any(t.get("time") or t.get("opened_at"))
        if not opened:
            continue
        hit=bool(t.get("tp0_hit"))
        success_flags.append(hit)
        if not hit:
            continue
        tp0_dt=None
        ts=int(safe_float(t.get("tp0_hit_ts"),0.0))
        if ts>0:
            try:
                tp0_dt=datetime.fromtimestamp(ts/1000.0,tz=timezone.utc)
            except Exception:
                tp0_dt=None
        if tp0_dt is None:
            tp0_dt=_parse_time_any(t.get("tp0_hit_at"))
        if tp0_dt is not None and tp0_dt>=opened:
            exact_times.append(max(1.0,(tp0_dt-opened).total_seconds()/60.0))
        else:
            closed=_parse_time_any(t.get("closed_at"))
            if closed and closed>=opened:
                legacy_success_upper_bounds.append(max(1.0,(closed-opened).total_seconds()/60.0))

    buckets=[15,30,60,120]
    cumulative={}
    exact_den=max(len(sample),1)
    for bucket in buckets:
        hit_exact=sum(1 for tm in exact_times if tm<=bucket)
        # Legacy upper bounds receive only 20% weight; they are not event times.
        hit_legacy=0.20*sum(1 for tm in legacy_success_upper_bounds if tm<=bucket)
        cumulative[str(bucket)]=(hit_exact+hit_legacy)/exact_den

    exact_share=len(exact_times)/max(sum(1 for x in sample if bool(x.get("tp0_hit"))),1)
    timing_reliability=clamp(exact_share,0.0,1.0)
    if exact_times:
        median_success=median(exact_times)
    elif legacy_success_upper_bounds:
        # Descriptive fallback only. Router will see low reliability and not
        # treat this as mature timing authority.
        median_success=median(legacy_success_upper_bounds)
    else:
        median_success=45.0
    return {
        "sample_size":len(sample),
        "successes":sum(1 for x in sample if bool(x.get("tp0_hit"))),
        "exact_tp0_time_rows":len(exact_times),
        "legacy_close_time_surrogate_rows":len(legacy_success_upper_bounds),
        "timing_reliability":round(timing_reliability,6),
        "p_tp0_by_minutes":{k:round(v,6) for k,v in cumulative.items()},
        "median_success_minutes":round(median_success,2),
        "expected_reaction_window_minutes":round(clamp(median_success,12.0,90.0),2),
        "legacy_time_is_conservative_upper_bound":True,
        "legacy_surrogate_weight":0.20,
        "hard_expiry":False,
        "schema_version":"time_to_edge_hazard_v9.5.33_exact_tp0_timestamp",
    }


def contextual_edge_v9532_oos(journal: Optional[dict[str,Any]]) -> dict[str,Any]:
    rows=_context_edge_rows(journal); scores=[]; labels=[]
    for i in range(12,len(rows)):
        row=rows[i]; hist=rows[:i]
        # exact-setup relative score percentile uses only prior closed trades and
        # the same recency half-life as live contextual authority.
        value=safe_float(row.get("score"),70.0)
        pct=safe_float(_weighted_score_percentile_v9533(hist,str(row.get("setup_type") or ""),value).get("percentile"),0.5)
        route=_contextual_route_edge_from_rows(hist,row["setup_type"],row["execution_source"],row["side"],row["regime"])
        p=0.70*clamp(pct,0.01,0.99)+0.30*clamp(safe_float(route.get("edge_probability"),0.5),0.01,0.99)
        scores.append(clamp(p,0.01,0.99)); labels.append(1 if safe_float(row.get("result_r"),0.0)>0 else 0)
    auc=_auc_binary(scores,labels) if labels else 0.5; brier=mean((p-y)**2 for p,y in zip(scores,labels)) if labels else 0.25
    return {"predictions":len(scores),"auc":round(auc,6),"brier":round(brier,6),"validation_pass":bool(len(scores)>=30 and auc>=0.56),"formula":"0.70*PAST_ONLY_RECENCY_WEIGHTED_SETUP_RELATIVE_PERCENTILE + 0.30*ROUTE_PARTIAL_POOLING","absolute_quality_is_universal":False,"future_labels_used":False,"schema_version":"contextual_authority_v9.5.33_recency_relative_quality"}


def contextual_authority_v9532(journal: Optional[dict[str,Any]], candidate: Candidate) -> dict[str,Any]:
    rel=setup_relative_quality_percentile(journal,candidate); route=contextual_route_edge_profile(journal,candidate); oos=contextual_edge_v9532_oos(journal)
    p=0.70*safe_float(rel.get("percentile"),0.5)+0.30*safe_float(route.get("edge_probability"),safe_float(route.get("posterior_win_rate"),0.5))
    strength=clamp((p-0.5)/0.25,-1.0,1.0); adjustment=3.0*strength*(1.0 if oos.get("validation_pass") else 0.35)
    return {"edge_probability":round(clamp(p,0.01,0.99),6),"selection_adjustment":round(clamp(adjustment,-3.0,3.0),6),"setup_relative_quality":rel,"route_partial_pooling":route,"oos_validation":oos,"raw_score_mutated":False,"schema_version":"contextual_authority_v9.5.33_recency_relative_quality"}


def route_geometry_profile(journal: Optional[dict[str,Any]], candidate: Candidate, router_action: str = "") -> dict[str,Any]:
    """MFE/MAE geometry conditioned on the actual execution route when available.

    Real trades are authoritative evidence. The bounded counterfactual matrix may
    supplement route-tactic geometry (MARKET/RETEST/CONFIRM/LIMIT), but it never
    grants trade/no-trade authority and never loosens the hard stop floor.
    """
    trades=[t for t in ((journal or {}).get("trades") or []) if isinstance(t,dict)]
    exact=[]; routed=[]
    for t in trades:
        if str(t.get("setup_type") or "")!=str(candidate.setup_type): continue
        if str(t.get("execution_source") or "")!=str(candidate.execution_source): continue
        if str(t.get("side") or "")!=str(candidate.side): continue
        if t.get("mfe_r") is None or t.get("mae_r") is None: continue
        exact.append(t)
        if router_action and str((t.get("execution_intelligence") or {}).get("router") or "")==str(router_action): routed.append(t)
    cf=[]
    if router_action:
        for ev in ((journal or {}).get("opportunity_outcome_matrix") or []):
            if not isinstance(ev,dict) or ev.get("status")!="RESOLVED": continue
            if str(ev.get("setup_type") or "")!=str(candidate.setup_type) or str(ev.get("side") or "")!=str(candidate.side): continue
            if str(ev.get("execution_source") or "")!=str(candidate.execution_source): continue
            out=dict((ev.get("outcomes") or {}).get(router_action) or {})
            if not out.get("filled") or out.get("mfe_r") is None or out.get("mae_r") is None: continue
            cf.append({"pnl_r":safe_float(out.get("result_r"),0.0),"mfe_r":safe_float(out.get("mfe_r"),0.0),"mae_r":safe_float(out.get("mae_r"),0.0),"evidence_origin":"COUNTERFACTUAL_ROUTE"})
    if router_action and len(routed)+len(cf)>=ROUTE_GEOMETRY_MIN_TRADES:
        rows=routed+cf; scope="SETUP_SOURCE_SIDE_ROUTER"
    elif len(exact)>=ROUTE_GEOMETRY_MIN_TRADES:
        rows=exact; scope="SETUP_SOURCE_SIDE_FALLBACK"
    else:
        rows=[t for t in trades if str(t.get("setup_type") or "")==str(candidate.setup_type) and t.get("mfe_r") is not None and t.get("mae_r") is not None]; scope="SETUP_FALLBACK"
    def q(vals:list[float],p:float,default:float)->float:
        vals=sorted(vals)
        if not vals:return default
        idx=min(len(vals)-1,max(0,int(round((len(vals)-1)*p))));return vals[idx]
    winners=[t for t in rows if safe_float(t.get("pnl_r"),0.0)>0]; losers=[t for t in rows if safe_float(t.get("pnl_r"),0.0)<=0]
    wm=[safe_float(t.get("mfe_r"),0.0) for t in winners]; wa=[safe_float(t.get("mae_r"),0.0) for t in winners]; lm=[safe_float(t.get("mfe_r"),0.0) for t in losers]
    return {"n":len(rows),"wins":len(winners),"actual_route_n":len(routed),"counterfactual_route_n":len(cf),"router_action":str(router_action or "UNSPECIFIED"),"evidence_scope":scope,"winner_mfe_q50":round(q(wm,.50,2.0),4),"winner_mfe_q75":round(q(wm,.75,2.5),4),"winner_mae_q75":round(q(wa,.75,.75),4),"loser_mfe_q75":round(q(lm,.75,.35),4),"mature":len(rows)>=ROUTE_GEOMETRY_MIN_TRADES and len(winners)>=3,"stop_policy":"UNCHANGED_HARD_SAFETY_FLOORS","counterfactual_scope":"EXECUTION_TACTIC_GEOMETRY_ONLY_NO_TRADE_PERMISSION","schema_version":DYNAMIC_GEOMETRY_SCHEMA_VERSION}



def execution_intelligence_assistants(context: dict[str,Any], candidate: Candidate, intel: dict[str,Any]) -> dict[str,Any]:
    asi=safe_float((intel.get("adverse_selection") or {}).get("index"),50)
    structural=safe_float(intel.get("structural_score"),50)
    runway=safe_float((intel.get("liquidity_runway") or {}).get("runway_r"),1.5)
    rv=intel.get("regime_vector") or {}
    out=intel.get("outcome_model") or {}
    ctx=intel.get("contextual_authority") or {}
    kind=str((intel.get("state_machine") or {}).get("kind") or "CONTINUATION")
    regime_support=candidate_regime_fit_probability_v9533(rv,candidate,kind)

    def opinion(value:float,good:float,bad:float)->str:
        return AdvisoryOpinion.SUPPORT.value if value>=good else AdvisoryOpinion.AGAINST.value if value<=bad else AdvisoryOpinion.CAUTION.value

    assistants={
        "LOCATION_ASSISTANT":{
            "opinion":opinion(100-asi,65,30),
            "metric":round(100-asi,2),
            "feature_ownership":["anchor_distance_signed","impulse_consumed","freshness","wick_exhaustion"],
        },
        "STRUCTURE_ASSISTANT":{
            "opinion":opinion(structural,62,40),
            "metric":round(structural,2),
            "feature_ownership":["3m_control_or_continuation_integrity","native_setup_execution_bridge"],
        },
        "REGIME_ASSISTANT":{
            "opinion":opinion(regime_support*100,50,25),
            "metric":round(regime_support*100,2),
            "feature_ownership":["directional_regime_probability_vector","candidate_side_regime_fit","regime_uncertainty"],
        },
        "LIQUIDITY_ASSISTANT":{
            "opinion":opinion(runway,1.55,.85),
            "metric":round(runway,3),
            "feature_ownership":["nearest_draw_on_liquidity","runway_r"],
        },
        "STATISTICAL_ASSISTANT":{
            "opinion":opinion(safe_float(ctx.get("edge_probability"),.5),.57,.43),
            "metric":round(safe_float(ctx.get("edge_probability"),.5),4),
            "feature_ownership":["past_only_route_edge","setup_relative_quality","outcome_probability_interval"],
            "outcome_probability":out.get("probability"),
            "uncertainty_width":out.get("uncertainty_width"),
        },
    }
    return {
        "modules":assistants,
        "candidate_regime_fit":round(regime_support,6),
        "independent_feature_ownership":True,
        "none_may_publish_action":True,
        "schema_version":"independent_execution_assistants_v9.5.33_directional",
    }



def _bandit_context_key(candidate: Candidate, regime_vector: dict[str,Any]) -> str:
    """Exact route-learning context. Family pooling is a parent prior, not identity."""
    return f"{candidate.setup_type}|{candidate.side}|{regime_vector.get('dominant','UNKNOWN')}"


def _bandit_parent_context_key(candidate: Candidate, regime_vector: dict[str,Any]) -> str:
    # Compatibility shape intentionally matches the v9.5.32 family context so
    # existing aggregate route evidence remains usable as a parent prior.
    return f"{candidate.setup_family}|{regime_vector.get('dominant','UNKNOWN')}"



def _bandit_action_profile(journal: Optional[dict[str,Any]], context_key:str, action:str, parent_key: str = "") -> dict[str,float]:
    bandit=(journal or {}).get("execution_route_bandit") or {}
    row=((bandit.get(context_key) or {}).get(action) or {})
    parent=((bandit.get(parent_key) or {}).get(action) or {}) if parent_key else {}
    n=safe_float(row.get("n"),0.0)
    wins=safe_float(row.get("wins"),0.0)
    reward=safe_float(row.get("reward_sum"),0.0)
    pn=safe_float(parent.get("n"),0.0)
    pw=safe_float(parent.get("wins"),0.0)
    pr=safe_float(parent.get("reward_sum"),0.0)

    prior=EXECUTION_ROUTER_BANDIT_PRIOR_N
    parent_wr=(pw+0.55*prior)/(pn+prior)
    parent_er=pr/max(pn+prior,1e-9)
    wr=(wins+parent_wr*prior)/(n+prior)
    er=(reward+parent_er*prior)/(n+prior)
    exploration=EXECUTION_ROUTER_EXPLORATION/math.sqrt(n+prior)
    utility=0.65*wr+0.20*clamp(0.5+0.25*er,0.0,1.0)+exploration
    return {
        "n":n,
        "parent_n":pn,
        "posterior_win_rate":wr,
        "posterior_reward":er,
        "utility":utility,
        "pooling":"EXACT_SETUP_SIDE_REGIME -> FAMILY_REGIME_PARENT",
    }



def _execution_router_profile_core_v9532(journal: Optional[dict[str,Any]], context: dict[str,Any], candidate: Candidate, intel: dict[str,Any]) -> dict[str,Any]:
    sm=intel["state_machine"]
    asi=safe_float(intel["adverse_selection"].get("index"),50)
    structural=safe_float(intel.get("structural_score"),50)
    runway=safe_float(intel["liquidity_runway"].get("runway_r"),1.5)
    outcome=intel["outcome_model"]
    rv=intel["regime_vector"]
    hazard=intel.get("survival_hazard") or {}
    uncertainty=safe_float(outcome.get("uncertainty_width"),.35)
    anchor=safe_float(getattr(candidate,"execution_anchor",0.0),safe_float(getattr(candidate,"trigger_level",0.0),0.0))
    atr=max(safe_float(context.get("atr15"),0.0),1e-9)
    price=safe_float(context.get("price"),0.0)
    dist=abs(price-anchor)/atr if anchor>0 and price>0 else 9.0

    base={"MARKET_NOW":0.55,"FIRST_RETEST":0.50,"ONE_3M_CONFIRM":0.48,"LIMIT_AT_ANCHOR":0.46}

    # Setup-native tactic preferences are soft priors, not entry filters.
    preferred=list(sm.get("preferred_tactics") or EXECUTION_ROUTER_ACTIONS)
    preference_bonus=(0.08,0.05,0.025,0.0)
    for idx,action in enumerate(preferred[:4]):
        if action in base:
            base[action]+=preference_bonus[min(idx,len(preference_bonus)-1)]

    # Preserve Router intent across the short saved-opportunity lifecycle. This is
    # a soft continuity prior only: fresh market evidence may choose another tactic.
    intended=str(((getattr(candidate,"stage_plan",{}) or {}).get("router_intended_tactic")) or "")
    if intended in base:
        base[intended]+=0.12

    # Rule-based execution preference, never thesis blocking.
    if asi<=38 and structural>=60 and runway>=1.20:
        base["MARKET_NOW"]+=0.30
    if asi>=55 or str(sm.get("current_state"))=="LOCATION":
        base["FIRST_RETEST"]+=0.34
    if structural<55 or uncertainty>0.34 or str(sm.get("current_state")) in {"CONTROL","TRIGGER"}:
        base["ONE_3M_CONFIRM"]+=0.30
    if anchor>0 and 0.10<=dist<=0.85:
        base["LIMIT_AT_ANCHOR"]+=0.18

    kind=str(sm.get("kind") or "CONTINUATION")
    regime_fit=candidate_regime_fit_probability_v9533(rv,candidate,kind)
    if regime_fit>=0.48 and str(sm.get("current_state"))=="EXECUTION":
        base["MARKET_NOW"]+=0.10
    elif regime_fit<0.30:
        # Weak candidate-relative regime fit does not block the setup. Spend the
        # same thesis on a more informative route.
        base["ONE_3M_CONFIRM"]+=0.08
        base["FIRST_RETEST"]+=0.06

    if kind in {"REVERSAL","AUCTION_MEAN"}:
        base["FIRST_RETEST"]+=0.08
        base["ONE_3M_CONFIRM"]+=0.08

    # Time-to-edge is route guidance only. Exact TP0 timestamps are required for
    # strong timing influence; legacy close-time surrogates are deliberately weak.
    hsample=int(hazard.get("sample_size") or 0)
    hrel=safe_float(hazard.get("timing_reliability"),0.0)
    hp=dict(hazard.get("p_tp0_by_minutes") or {})
    hp15=safe_float(hp.get("15"),0.0)
    hp30=safe_float(hp.get("30"),0.0)
    hp60=safe_float(hp.get("60"),0.0)
    if hsample>=4 and hrel>=0.50:
        if hp15>=0.45 and str(sm.get("current_state"))=="EXECUTION":
            base["MARKET_NOW"]+=0.06
        if hp15<0.25 and hp60>=hp15+0.15:
            base["ONE_3M_CONFIRM"]+=0.08
            base["FIRST_RETEST"]+=0.05
        if safe_float(hazard.get("expected_reaction_window_minutes"),45.0)>45.0:
            base["ONE_3M_CONFIRM"]+=0.04

    context_key=_bandit_context_key(candidate,rv)
    parent_key=_bandit_parent_context_key(candidate,rv)
    action_rows={}
    for action in EXECUTION_ROUTER_ACTIONS:
        action_rows[action]=_bandit_action_profile(journal,context_key,action,parent_key=parent_key)

    max_route_n=max((safe_float(row.get("n"),0.0) for row in action_rows.values()),default=0.0)
    parent_route_n=max((safe_float(row.get("parent_n"),0.0) for row in action_rows.values()),default=0.0)
    route_maturity=clamp((max_route_n+0.35*parent_route_n)/20.0,0.0,1.0)
    bandit_weight=0.16+0.22*route_maturity
    combined={action:base[action]+bandit_weight*safe_float(action_rows[action].get("utility"),0.0) for action in EXECUTION_ROUTER_ACTIONS}

    eligible=set(EXECUTION_ROUTER_ACTIONS)
    if anchor<=0:
        eligible.discard("FIRST_RETEST")
        eligible.discard("LIMIT_AT_ANCHOR")
    if not _v9532_recent_confirmed(context,"3m",2):
        eligible.discard("ONE_3M_CONFIRM")
    phase=str(sm.get("current_state") or "EXECUTION")
    if phase=="LOCATION":
        eligible &= {"FIRST_RETEST","LIMIT_AT_ANCHOR"}
    elif phase in {"CONTROL","TRIGGER"}:
        eligible &= {"ONE_3M_CONFIRM","FIRST_RETEST"}
    elif phase=="THESIS":
        eligible &= {"ONE_3M_CONFIRM","FIRST_RETEST","LIMIT_AT_ANCHOR"}

    chosen=max(eligible,key=lambda a:combined[a]) if eligible else "MARKET_NOW"
    return {
        "action":chosen,
        "scores":{a:round(combined[a],6) for a in EXECUTION_ROUTER_ACTIONS},
        "bandit":action_rows,
        "bandit_weight":round(bandit_weight,6),
        "route_evidence_maturity":round(route_maturity,6),
        "context_key":context_key,
        "parent_context_key":parent_key,
        "candidate_regime_fit":round(regime_fit,6),
        "hazard_evidence":{
            "sample_size":hsample,
            "timing_reliability":round(hrel,4),
            "p15":round(hp15,4),
            "p30":round(hp30,4),
            "p60":round(hp60,4),
            "expected_reaction_window_minutes":safe_float(hazard.get("expected_reaction_window_minutes"),45.0),
        },
        "max_wait_minutes":EXECUTION_ROUTER_MAX_WAIT_MINUTES,
        "setup_blocked":False,
        "only_routes_execution":True,
        "reason":"BEST_EXECUTION_TACTIC_FOR_CURRENT_STATE",
        "schema_version":EXECUTION_ROUTER_SCHEMA_VERSION,
    }






def compact_execution_intelligence_v9532(intel: dict[str,Any]) -> dict[str,Any]:
    if not isinstance(intel,dict):
        return {}
    # Already-compact records pass through a normalized allow-list. This is the
    # second half of journal idempotency: compact(compact(x)) must not replace
    # real assistant metrics with neutral defaults.
    if "asi" in intel and "structural" in intel and "adverse_selection" not in intel:
        keys = (
            "router", "state", "kind", "asi", "structural", "runway_r",
            "regime", "regime_bias", "regime_fit", "regime_uncertainty",
            "setup_pct", "ctx_edge", "outcome_p", "outcome_uncertainty",
            "hazard_15", "hazard_30", "hazard_60", "hazard_reliability",
            "reaction_window", "geo_n", "assistant_opinions", "assistant_metrics",
            "assistant_feedback_complete", "schema",
        )
        normalized = {key: copy.deepcopy(intel.get(key)) for key in keys if key in intel}
        normalized.setdefault("schema", "xi40")
        return normalized
    rv=intel.get("regime_vector") or {}
    sm=intel.get("state_machine") or {}
    router=intel.get("execution_router") or {}
    outcome=intel.get("outcome_model") or {}
    geo=intel.get("route_geometry") or {}
    hazard=intel.get("survival_hazard") or {}
    hp=hazard.get("p_tp0_by_minutes") or {}
    assistant_modules=((intel.get("assistants") or {}).get("modules") or {})
    assistant_opinions={
        str(name):str((row or {}).get("opinion") or "")
        for name,row in assistant_modules.items() if isinstance(row,dict)
    }
    assistant_metrics={
        str(name):round(safe_float((row or {}).get("metric"),50.0),4)
        for name,row in assistant_modules.items() if isinstance(row,dict)
    }
    return {
        "router":router.get("action"),
        "state":sm.get("current_state"),
        "kind":sm.get("kind"),
        "asi":round(safe_float((intel.get("adverse_selection") or {}).get("index"),50),2),
        "structural":round(safe_float(intel.get("structural_score"),50),2),
        "runway_r":round(safe_float((intel.get("liquidity_runway") or {}).get("runway_r"),1.5),3),
        "regime":rv.get("dominant"),
        "regime_bias":rv.get("directional_bias"),
        "regime_fit":round(safe_float(router.get("candidate_regime_fit"),.5),3),
        "regime_uncertainty":round(safe_float(rv.get("uncertainty"),.5),3),
        "setup_pct":round(safe_float((intel.get("setup_relative_quality") or {}).get("percentile"),.5),3),
        "ctx_edge":round(safe_float((intel.get("contextual_authority") or {}).get("edge_probability"),.5),3),
        "outcome_p":round(safe_float(outcome.get("probability"),.5),3),
        "outcome_uncertainty":round(safe_float(outcome.get("uncertainty_width"),.5),3),
        "hazard_15":round(safe_float(hp.get("15"),0.0),3),
        "hazard_30":round(safe_float(hp.get("30"),0.0),3),
        "hazard_60":round(safe_float(hp.get("60"),0.0),3),
        "hazard_reliability":round(safe_float(hazard.get("timing_reliability"),0.0),3),
        "reaction_window":round(safe_float(hazard.get("expected_reaction_window_minutes"),45.0),1),
        "geo_n":int(geo.get("n") or 0),
        "assistant_opinions":assistant_opinions,
        "assistant_metrics":assistant_metrics,
        "assistant_feedback_complete":len(assistant_opinions)==5,
        "schema":"xi40",
    }


# ---------------- Unified opportunity counterfactual matrix ----------------
def _opportunity_matrix_key(candidate: Candidate, context: dict[str,Any]) -> str:
    try:
        return setup_market_episode_key({"side":candidate.side,"setup_type":candidate.setup_type,"model_id":candidate.ict_model,"thesis_key":candidate.thesis_key,"execution_anchor":candidate.execution_anchor,"trigger_level":candidate.trigger_level,"model_thesis_age_minutes":candidate.model_thesis_age_minutes,"market_thesis_age_minutes":candidate.market_thesis_age_minutes,"thesis_origin":candidate.thesis_origin},context)
    except Exception:
        return f"{candidate.side}|{candidate.setup_type}|{int(_preconfirm_as_of_ts(context)//3600000)}"



def _simulate_route_path_v9532(event: dict[str,Any], candles: list[Candle], action:str) -> dict[str,Any]:
    """Conservative route-specific counterfactual simulator.

    MARKET, passive LIMIT, causal FIRST_RETEST and ONE_3M_CONFIRM intentionally
    have different fill semantics. OHLC ambiguity remains stop-first.
    """
    if not candles:
        return {"filled":False,"result_r":None,"reason":"NO_FUTURE_CANDLES"}
    side=str(event.get("side") or "")
    sign=side_sign(side)
    observed=safe_float(event.get("price"),0.0)
    anchor=safe_float(event.get("anchor"),0.0)
    atr=max(safe_float(event.get("atr15"),1.0),1e-9)
    risk=max(safe_float(event.get("risk_distance"),0.0),atr*0.8,1e-6)
    rr0=max(RUNWAY_SCOUT_TP0_MIN_R,safe_float(event.get("rr0"),1.0))
    rr1=max(MIN_RR1,safe_float(event.get("rr1"),MIN_RR1))
    kind=str((event.get("xi") or {}).get("kind") or "CONTINUATION")

    entry=observed
    start_idx=0
    fill_reason="MARKET_AT_OBSERVATION"

    if action=="LIMIT_AT_ANCHOR":
        if anchor<=0:
            return {"filled":False,"result_r":None,"reason":"NO_ANCHOR"}
        found=None
        for i,c in enumerate(candles):
            if safe_float(c.low)<=anchor<=safe_float(c.high):
                found=i
                break
        if found is None:
            return {"filled":False,"result_r":None,"reason":"ANCHOR_NOT_TOUCHED"}
        entry=anchor
        start_idx=found
        fill_reason="PASSIVE_LIMIT_FIRST_ANCHOR_TOUCH"

    elif action=="FIRST_RETEST":
        if anchor<=0:
            return {"filled":False,"result_r":None,"reason":"NO_ANCHOR"}
        touch=None
        for i,c in enumerate(candles):
            if safe_float(c.low)<=anchor<=safe_float(c.high):
                touch=i
                break
        if touch is None:
            return {"filled":False,"result_r":None,"reason":"ANCHOR_NOT_RETESTED"}
        confirm=None
        for j in range(touch+1,min(len(candles),touch+4)):
            c=candles[j]
            body=sign*(safe_float(c.close)-safe_float(c.open))
            held=sign*(safe_float(c.close)-anchor)>=-0.02*atr
            if body>=0.04*atr and held:
                confirm=j
                break
        if confirm is None:
            return {"filled":False,"result_r":None,"reason":"RETEST_TOUCHED_BUT_NO_CAUSAL_HOLD_CONFIRM"}
        entry=safe_float(candles[confirm].close,anchor)
        # Never reuse the confirmation candle as post-entry future path.
        start_idx=confirm+1
        fill_reason="FIRST_RETEST_THEN_DIRECTIONAL_HOLD"

    elif action=="ONE_3M_CONFIRM":
        found=None
        if kind in {"REVERSAL","AUCTION_MEAN"}:
            # Reversal confirmation needs control transfer plus follow-through.
            for i in range(len(candles)-1):
                c=candles[i]
                n=candles[i+1]
                body=sign*(safe_float(c.close)-safe_float(c.open))
                follow=sign*(safe_float(n.close)-safe_float(c.close))
                holds_anchor=(anchor<=0) or sign*(safe_float(n.close)-anchor)>=-0.05*atr
                if body>=0.08*atr and follow>=0.02*atr and holds_anchor:
                    found=i+1
                    break
        else:
            # Continuation/breakout confirmation must close through the prior
            # micro extreme, not merely print any same-colour candle.
            for i in range(1,len(candles)):
                c=candles[i]
                prev=candles[i-1]
                body=sign*(safe_float(c.close)-safe_float(c.open))
                broke=(safe_float(c.close)>safe_float(prev.high)+0.01*atr) if sign>0 else (safe_float(c.close)<safe_float(prev.low)-0.01*atr)
                if body>=0.08*atr and broke:
                    found=i
                    break
        if found is None:
            return {"filled":False,"result_r":None,"reason":"NO_SETUP_AWARE_3M_CONFIRM"}
        entry=safe_float(candles[found].close,observed)
        # Never score the confirmation candle itself as future PnL.
        start_idx=found+1
        fill_reason="SETUP_AWARE_3M_CONFIRM_CLOSE"

    stop=entry-sign*risk
    tp0=entry+sign*risk*rr0
    tp1=entry+sign*risk*rr1

    # Passive-limit fill inside an OHLC bar has unknown intrabar ordering. To
    # avoid optimistic route learning, the fill bar may prove an immediate stop
    # (adverse move after/around the touch), but may NOT claim TP0/TP1 from that
    # same ambiguous bar. Favorable route outcome starts with the next 3M bar.
    if action=="LIMIT_AT_ANCHOR" and start_idx < len(candles):
        fill_bar=candles[start_idx]
        fill_stop_hit=safe_float(fill_bar.low)<=stop if sign>0 else safe_float(fill_bar.high)>=stop
        if fill_stop_hit:
            return {
                "filled":True,"result_r":-1.0,"tp0_hit":False,"tp1_hit":False,
                "mfe_r":0.0,"mae_r":1.0,"terminal":"STOP",
                "fill_reason":fill_reason,"intrabar_policy":"FILL_BAR_STOP_ALLOWED_TP_DEFERRED",
            }
        start_idx+=1

    path=candles[start_idx:]
    mfe=0.0
    mae=0.0
    for c in path:
        fav=(safe_float(c.high)-entry)/risk if sign>0 else (entry-safe_float(c.low))/risk
        adv=(entry-safe_float(c.low))/risk if sign>0 else (safe_float(c.high)-entry)/risk
        mfe=max(mfe,fav)
        mae=max(mae,adv)
        stop_hit=safe_float(c.low)<=stop if sign>0 else safe_float(c.high)>=stop
        tp1_hit=safe_float(c.high)>=tp1 if sign>0 else safe_float(c.low)<=tp1
        tp0_hit=safe_float(c.high)>=tp0 if sign>0 else safe_float(c.low)<=tp0
        # Stop-first is deliberately conservative for intrabar ambiguity.
        if stop_hit:
            return {"filled":True,"result_r":-1.0,"tp0_hit":False,"tp1_hit":False,"mfe_r":round(max(0,mfe),4),"mae_r":round(max(0,mae),4),"terminal":"STOP","fill_reason":fill_reason}
        if tp1_hit:
            return {"filled":True,"result_r":round(rr1,4),"tp0_hit":True,"tp1_hit":True,"mfe_r":round(max(0,mfe),4),"mae_r":round(max(0,mae),4),"terminal":"TP1","fill_reason":fill_reason}
        if tp0_hit:
            return {"filled":True,"result_r":round(min(rr0,1.0),4),"tp0_hit":True,"tp1_hit":False,"mfe_r":round(max(0,mfe),4),"mae_r":round(max(0,mae),4),"terminal":"TP0","fill_reason":fill_reason}
    final=sign*(safe_float(path[-1].close)-entry)/risk if path else 0.0
    return {"filled":True,"result_r":round(final,4),"tp0_hit":mfe>=rr0,"tp1_hit":mfe>=rr1,"mfe_r":round(max(0,mfe),4),"mae_r":round(max(0,mae),4),"terminal":"HORIZON","fill_reason":fill_reason}



def resolve_opportunity_outcome_matrix_v9532(journal: dict[str,Any], context: dict[str,Any]) -> int:
    store=journal.get("opportunity_outcome_matrix") or []
    c3=_v9532_recent_confirmed(context,"3m",240)
    nowts=_preconfirm_as_of_ts(context)
    resolved=0
    for ev in store:
        if not isinstance(ev,dict) or ev.get("status")!="PENDING" or nowts<int(ev.get("horizon_ts") or 0):
            continue
        path=[c for c in c3 if int(c.ts)>int(ev.get("observed_ts") or 0) and int(c.ts)<=int(ev.get("horizon_ts") or 0)]
        if not path:
            continue
        outcomes={a:_simulate_route_path_v9532(ev,path,a) for a in EXECUTION_ROUTER_ACTIONS}
        ev["outcomes"]={
            a:{k:v for k,v in o.items() if k in {"filled","result_r","tp0_hit","terminal","mfe_r","mae_r","fill_reason","reason"}}
            for a,o in outcomes.items()
        }
        ev["status"]="RESOLVED"
        ev["resolved_at"]=iso_now()
        resolved+=1

        # Contextual bandit learns execution tactic only, never trade/no-trade.
        # Leaf context is exact setup+side+regime; family+regime is a pooled prior.
        leaf=str(ev.get("bandit_context") or "UNKNOWN")
        parent=str(ev.get("bandit_parent_context") or "")
        weight=clamp(safe_float(ev.get("route_learning_weight"),1.0),0.10,1.0)
        for context_key,context_weight in ((leaf,weight),(parent,weight*0.50)):
            if not context_key:
                continue
            bandit=journal.setdefault("execution_route_bandit",{}).setdefault(context_key,{})
            for action,o in outcomes.items():
                if not o.get("filled") or o.get("result_r") is None:
                    continue
                w=context_weight
                row=bandit.setdefault(action,{"n":0.0,"wins":0.0,"reward_sum":0.0,"updated_at":""})
                row["n"]=round(safe_float(row.get("n"),0.0)+w,4)
                row["wins"]=round(safe_float(row.get("wins"),0.0)+(w if safe_float(o.get("result_r"),0.0)>0 else 0.0),4)
                row["reward_sum"]=round(safe_float(row.get("reward_sum"),0.0)+w*safe_float(o.get("result_r"),0.0),6)
                row["updated_at"]=iso_now()
    return resolved



def record_opportunity_outcome_event_v9532(
    journal: dict[str,Any], context: dict[str,Any], candidate: Candidate,
    plan: Optional[TradePlan], intel: dict[str,Any], actual_action:str,
    *, draft_action_before_route: str = "",
) -> bool:
    if candidate is None:
        return False
    key=_opportunity_matrix_key(candidate,context)
    store=journal.setdefault("opportunity_outcome_matrix",[])
    if any(isinstance(x,dict) and x.get("episode_key")==key for x in store[-OPPORTUNITY_OUTCOME_MATRIX_LIMIT:]):
        return False
    price=safe_float(context.get("price"),0.0)
    atr=max(safe_float(context.get("atr15"),0.0),1e-6)
    risk=abs(safe_float(getattr(plan,"entry",price),price)-safe_float(getattr(plan,"stop",price),price)) if plan else max(atr*MIN_STOP_ATR15,ABS_MIN_STOP_DOLLARS)
    ts=_preconfirm_as_of_ts(context)
    router=(intel.get("execution_router") or {}).get("action")
    rv=intel.get("regime_vector") or {}
    ev={
        "episode_key":key,
        "observed_ts":ts,
        "horizon_ts":ts+OPPORTUNITY_OUTCOME_HORIZON_MINUTES*60_000,
        "status":"PENDING",
        "side":candidate.side,
        "setup_type":candidate.setup_type,
        "setup_family":candidate.setup_family,
        "execution_source":candidate.execution_source,
        "price":round_price(price),
        "anchor":round_price(safe_float(candidate.execution_anchor,safe_float(candidate.trigger_level,price))),
        "atr15":round(atr,6),
        "risk_distance":round(risk,6),
        "rr0":safe_float(getattr(plan,"rr0",1.0),1.0) if plan else 1.0,
        "rr1":safe_float(getattr(plan,"rr1",MIN_RR1),MIN_RR1) if plan else MIN_RR1,
        "router_action":router,
        "actual_action":actual_action,
        "draft_action_before_route":str(draft_action_before_route or actual_action),
        "origin":"SELECTED_HYPOTHESIS",
        "route_learning_weight":1.0,
        "bandit_context":_bandit_context_key(candidate,rv),
        "bandit_parent_context":_bandit_parent_context_key(candidate,rv),
        "xi":compact_execution_intelligence_v9532(intel),
        "schema_version":COUNTERFACTUAL_MATRIX_SCHEMA_VERSION,
    }
    store.append(ev)
    if len(store)>OPPORTUNITY_OUTCOME_MATRIX_LIMIT:
        del store[:-OPPORTUNITY_OUTCOME_MATRIX_LIMIT]
    return True



def record_rejected_opportunity_events_v9532(journal: dict[str,Any], context: dict[str,Any], decision: Decision, limit: int = 2) -> int:
    """Merge rejected hypotheses into the same bounded route-learning matrix."""
    audit=decision.audit or {}
    rows=[]
    for row in (audit.get("rejected_hypotheses") or []):
        if isinstance(row,dict):
            rows.append(row)
    per_side=audit.get("best_candidate_per_side") or {}
    if isinstance(per_side,dict):
        for row in per_side.values():
            if isinstance(row,dict) and not bool(row.get("selected")) and row.get("candidate_created") is not False:
                rows.append(row)
    ts=_preconfirm_as_of_ts(context)
    atr=max(safe_float(context.get("atr15"),0.0),1e-6)
    price=safe_float(context.get("price"),0.0)
    added=0
    seen=set()
    rv=regime_probability_vector(context)
    dominant=str(rv.get("dominant") or "UNKNOWN")
    for row in rows:
        if added>=limit:
            break
        side=str(row.get("side") or "")
        setup=str(row.get("setup_type") or "")
        if side not in {Side.LONG.value,Side.SHORT.value} or setup not in _tracked_setup_types():
            continue
        blueprint=dict(row.get("counterfactual") or {})
        entry=safe_float(blueprint.get("entry"),price)
        stop=safe_float(blueprint.get("stop"),0.0)
        anchor=safe_float(row.get("entry_anchor"),entry) or entry
        risk=abs(entry-stop) if entry>0 and stop>0 else max(atr*MIN_STOP_ATR15,ABS_MIN_STOP_DOLLARS)
        if entry<=0 or risk<=0:
            continue
        key=f"REJECTED|{side}|{setup}|{int(round(anchor/max(atr*0.25,1e-6)))}|{ts//(60*60_000)}"
        if key in seen or any(isinstance(x,dict) and x.get("episode_key")==key for x in (journal.get("opportunity_outcome_matrix") or [])[-OPPORTUNITY_OUTCOME_MATRIX_LIMIT:]):
            continue
        seen.add(key)
        setup_family=str(row.get("setup_family") or SetupFamily.NONE.value)
        execution_source=str(row.get("execution_source") or ExecutionSource.NONE.value)
        rr0=abs(safe_float(blueprint.get("tp0"),entry)-entry)/risk if blueprint.get("tp0") else 1.0
        rr1=abs(safe_float(blueprint.get("tp1"),entry)-entry)/risk if blueprint.get("tp1") else MIN_RR1
        ev={
            "episode_key":key,
            "observed_ts":ts,
            "horizon_ts":ts+OPPORTUNITY_OUTCOME_HORIZON_MINUTES*60_000,
            "status":"PENDING",
            "side":side,
            "setup_type":setup,
            "setup_family":setup_family,
            "execution_source":execution_source,
            "price":round_price(entry),
            "anchor":round_price(anchor),
            "atr15":round(atr,6),
            "risk_distance":round(risk,6),
            "rr0":round(max(RUNWAY_SCOUT_TP0_MIN_R,rr0),3),
            "rr1":round(max(MIN_RR1,rr1),3),
            "router_action":"UNOBSERVED_REJECTED",
            "actual_action":Action.NO_SETUP.value,
            "origin":"REJECTED_HYPOTHESIS",
            "route_learning_weight":0.35,
            "bandit_context":f"{setup}|{side}|{dominant}",
            "bandit_parent_context":f"{setup_family}|{dominant}",
            "xi":{
                "kind":str((SETUP_STATE_MACHINE_REGISTRY.get(setup) or {}).get("kind") or "CONTINUATION"),
                "regime":dominant,
            },
            "rejection_reason":str(row.get("failed_gate") or row.get("top_rejection_reason") or "REJECTED")[:120],
            "schema_version":COUNTERFACTUAL_MATRIX_SCHEMA_VERSION,
        }
        store=journal.setdefault("opportunity_outcome_matrix",[])
        store.append(ev)
        added+=1
        if len(store)>OPPORTUNITY_OUTCOME_MATRIX_LIMIT:
            del store[:-OPPORTUNITY_OUTCOME_MATRIX_LIMIT]
    return added


# ---------------- Loss attribution and bounded journal budget ----------------
def loss_attribution_v9532(trade: dict[str,Any], signal: Optional[dict[str,Any]]=None) -> dict[str,Any]:
    result=safe_float(trade.get("pnl_r"),0.0)
    if result>=0:return {"primary":"NONE","secondary":"NONE"}
    xi=dict(trade.get("execution_intelligence") or (signal or {}).get("execution_intelligence") or {})
    asi=safe_float(xi.get("asi"),50); structural=safe_float(xi.get("structural"),50); runway=safe_float(xi.get("runway_r"),1.5); mfe=safe_float(trade.get("mfe_r"),0.0); mae=safe_float(trade.get("mae_r"),0.0); delay=safe_float(trade.get("entry_delay_directional_delta"),0.0); kind=str(xi.get("kind") or "")
    causes=[]
    if asi>=65: causes.append("ADVERSE_SELECTION_LATE_ENTRY")
    if structural<45: causes.append("NO_CONTROL_OR_INTEGRITY")
    if runway<1.0: causes.append("LIQUIDITY_RUNWAY_TOO_SHORT")
    if mfe<0.20 and mae>=0.50: causes.append("PREMATURE_OR_WRONG_DIRECTION")
    if mfe>=0.65 and result<0: causes.append("MFE_GIVEBACK_MANAGEMENT")
    if safe_float(xi.get("regime_uncertainty"),0.5)>=0.72: causes.append("REGIME_UNCERTAINTY")
    if abs(delay)>0.45: causes.append("ENTRY_DELAY_LOCATION_DECAY")
    if not causes: causes.append("NO_FOLLOW_THROUGH")
    return {"primary":causes[0],"secondary":causes[1] if len(causes)>1 else "NONE","kind":kind or "UNKNOWN"}


def refresh_loss_attribution_v9532(journal: dict[str,Any]) -> dict[str,Any]:
    sig={str(s.get("id") or ""):s for s in (journal.get("signals") or []) if isinstance(s,dict)}; agg={}; secondary={}; losses=0
    for t in (journal.get("trades") or []):
        if not isinstance(t,dict) or safe_float(t.get("pnl_r"),0.0)>=0: continue
        losses+=1; s=sig.get(str(t.get("signal_id") or "")); a=loss_attribution_v9532(t,s); t["loss_code"]=a["primary"]; t["loss_secondary"]=a["secondary"]
        agg[a["primary"]]=agg.get(a["primary"],0)+1
        if a["secondary"]!="NONE":secondary[a["secondary"]]=secondary.get(a["secondary"],0)+1
    report={"losses":losses,"primary_counts":dict(sorted(agg.items(),key=lambda kv:-kv[1])),"secondary_counts":dict(sorted(secondary.items(),key=lambda kv:-kv[1])),"per_trade_storage":"TWO_SHORT_CODES_ONLY; NO_SEPARATE_LOSS_EVENT_LEDGER","schema_version":LOSS_ATTRIBUTION_SCHEMA_VERSION}
    journal.setdefault("analytics",{})["loss_attribution"]=report; return report


def v9532_journal_budget_compaction(journal: dict[str,Any]) -> dict[str,Any]:
    before={"active_shadow":len(journal.get("active_trade_shadow_scans") or []),"rejected":len(journal.get("rejected_hypothesis_shadows") or []),"matrix":len(journal.get("opportunity_outcome_matrix") or [])}
    for key,limit in (("active_trade_shadow_scans",ACTIVE_TRADE_SHADOW_SCAN_LIMIT),("rejected_hypothesis_shadows",REJECTED_HYPOTHESIS_SHADOW_LIMIT),("opportunity_outcome_matrix",OPPORTUNITY_OUTCOME_MATRIX_LIMIT)):
        rows=journal.get(key)
        if isinstance(rows,list) and len(rows)>limit: del rows[:-limit]
    # Bandit is aggregate-only. Keep at least the strongest exact leaf context
    # for every named setup before filling the remaining budget by evidence. This
    # prevents rare setups from losing all route memory to high-frequency families.
    bandit=journal.get("execution_route_bandit") or {}
    if isinstance(bandit,dict) and len(bandit)>96:
        def evidence_n(item):
            return sum(safe_float((v or {}).get("n"),0.0) for v in (item[1] or {}).values())
        protected={}
        tracked=set(_tracked_setup_types())
        for key,row in bandit.items():
            prefix=str(key).split("|",1)[0]
            if prefix not in tracked:
                continue
            current=protected.get(prefix)
            if current is None or evidence_n((key,row))>evidence_n(current):
                protected[prefix]=(key,row)
        kept={k:v for k,v in protected.values()}
        ranked=sorted(bandit.items(),key=evidence_n,reverse=True)
        for key,row in ranked:
            if len(kept)>=96:
                break
            kept.setdefault(key,row)
        journal["execution_route_bandit"]=kept
    return {"before":before,"after":{"active_shadow":len(journal.get("active_trade_shadow_scans") or []),"rejected":len(journal.get("rejected_hypothesis_shadows") or []),"matrix":len(journal.get("opportunity_outcome_matrix") or [])},"policy":"BOUNDED_INTELLIGENCE_WITH_ONE_EXACT_ROUTE_MEMORY_PER_NAMED_SETUP","schema_version":"journal_budget_v9.5.33_setup_protected"}



# Replace, do not stack, the v9.5.31 contextual selection adjustment.
_evidence_adjusted_selection_profile_v9531_final = evidence_adjusted_selection_profile
def evidence_adjusted_selection_profile(journal: Optional[dict[str,Any]], candidate: Optional[Candidate]) -> dict[str,Any]:
    base=_evidence_adjusted_selection_profile_v9531_final(journal,candidate)
    if candidate is None or not base.get("active"):
        return base
    components=base.setdefault("components",{}); legacy=safe_float(components.get("contextual_edge_adjustment"),0.0)
    baseline=safe_float(base.get("selection_score_pre_context"),safe_float(base.get("selection_score"),safe_float(getattr(candidate,"final_score",0),0))-legacy)
    cap=safe_float(base.get("selection_authority_cap"),100.0); ctx=contextual_authority_v9532(journal,candidate); adj=safe_float(ctx.get("selection_adjustment"),0.0); updated=clamp(min(baseline+adj,cap),0.0,100.0)
    base["selection_score_pre_context"]=round(baseline,6); base["selection_score"]=round(updated,6); base["total_adjustment"]=round(updated-safe_float(base.get("raw_hypothesis_score"),updated),6)
    components["legacy_v9531_context_adjustment_replaced"]=round(legacy,6); components["contextual_edge_adjustment"]=round(adj,6)
    base.setdefault("evidence",{})["contextual_authority_v9532"]=ctx
    base["policy"]=str(base.get("policy") or "")+"; V9_5_32_RELATIVE_QUALITY_CONTEXT_REPLACES_V9_5_31_CONTEXT_NO_DOUBLE_COUNT"
    base["schema_version"]="evidence_adjusted_selection_v9.5.32_relative_quality_context"
    return base

# ---------------- Dynamic geometry wrapper ----------------
_build_trade_plan_v9531 = build_trade_plan
def build_trade_plan(context: dict, candidate: Candidate, entry_price_override: Optional[float]=None, journal: Optional[dict[str,Any]]=None) -> TradePlan:
    if entry_price_override is None:
        route_override=safe_float(((getattr(candidate,"stage_plan",{}) or {}).get("route_entry_price_override")),0.0)
        if route_override>0 and str(((getattr(candidate,"stage_plan",{}) or {}).get("router_intended_tactic")) or "")=="LIMIT_AT_ANCHOR":
            entry_price_override=route_override
    plan=_build_trade_plan_v9531(context,candidate,entry_price_override=entry_price_override,journal=journal)
    # Before the router chooses its tactic, keep geometry descriptive only. The
    # route-specific TP1 adjustment is applied once, after tactic selection.
    geo=route_geometry_profile(journal,candidate); plan.breathing_profile=plan.breathing_profile or {}; plan.breathing_profile["route_geometry_v9532"]=geo; candidate.stage_plan=candidate.stage_plan or {}; candidate.stage_plan["route_geometry_v9532"]=geo
    return plan


def _apply_route_tactic_geometry_v9532(plan: Optional[TradePlan], candidate: Candidate, geo: dict[str,Any]) -> bool:
    if plan is None or not plan.valid or not geo.get("mature"): return False
    risk=max(abs(plan.entry-plan.stop),1e-9); current_rr=abs(plan.tp1-plan.entry)/risk
    empirical_rr=max(MIN_RR1,min(current_rr,safe_float(geo.get("winner_mfe_q50"),current_rr)*0.85))
    floor=max(MIN_RR1,current_rr-ROUTE_GEOMETRY_MAX_TP1_REDUCTION_R); target_rr=max(floor,empirical_rr)
    if target_rr>=current_rr-0.05: return False
    sign=side_sign(candidate.side); new_tp1=plan.entry+sign*risk*target_rr
    if not ((sign>0 and new_tp1<plan.tp2) or (sign<0 and new_tp1>plan.tp2)): return False
    plan.tp1=round_price(new_tp1); plan.rr1=round(target_rr,2); plan.target_basis += f" | v9.5.32 route-tactic MFE geometry TP1={target_rr:.2f}R"
    geo["tp1_adjusted"]=True; geo["tp1_rr_before"]=round(current_rr,3); geo["tp1_rr_after"]=round(target_rr,3)
    plan.breathing_profile=plan.breathing_profile or {}; plan.breathing_profile["route_geometry_v9532"]=geo
    return True


# ---------------- Execution Router wrapper ----------------
_evaluate_new_setup_v9531 = evaluate_new_setup

def executive_route_resolution_v9533(decision: Decision, tactic: str) -> Decision:
    """Executive-owned application of a route recommendation.

    The Router recommends a tactic but never publishes/withdraws an Action by
    itself. Any change to the final executable action is performed here under
    the same Executive authority contract.
    """
    tactic=str(tactic or "MARKET_NOW")
    if decision.action not in EXECUTABLE_ENTRY_ACTIONS or tactic=="MARKET_NOW" or decision.candidate is None:
        return decision

    original=str(decision.action)
    cand=decision.candidate
    if tactic in {"FIRST_RETEST","LIMIT_AT_ANCHOR"}:
        cand.execution_lane=ExecutionLane.WAIT_RETEST.value
        cand.opportunity_status=OpportunityStatus.WAIT_PULLBACK.value
        cand.confirmation_pending=False
        decision.audit["opportunity_status"]=OpportunityStatus.ARMED.value
        executive_state=ExecutiveDecisionState.WAIT_RETEST.value
        required=f"{tactic} within {EXECUTION_ROUTER_MAX_WAIT_MINUTES}m"
    else:
        cand.execution_lane=ExecutionLane.WAIT_CONFIRMATION.value
        cand.opportunity_status=OpportunityStatus.CONFIRMATION_PENDING.value
        cand.confirmation_pending=True
        decision.audit["opportunity_status"]=OpportunityStatus.CONFIRMATION_PENDING.value
        executive_state=ExecutiveDecisionState.WAIT_CONFIRMATION.value
        required=f"fresh setup-aware 3M confirmation within {EXECUTION_ROUTER_MAX_WAIT_MINUTES}m"

    report=(((decision.audit or {}).get("executive_director") or {}).get("report") or {})
    ex=report.setdefault("executive_decision",{})
    ex["action"]=executive_state
    ex["state"]=executive_state
    ex["allow_execution"]=False
    ex["allowed_stage"]=executive_state
    ex["final_risk_pct"]=0.0
    ex["required_next_event"]=required
    ex.setdefault("audit",{})["execution_router_resolution"]={
        "router_recommendation":tactic,
        "routed_from_action":original,
        "setup_blocked":False,
        "route_wait_minutes":EXECUTION_ROUTER_MAX_WAIT_MINUTES,
        "authority":"EXECUTIVE_DECISION_LAYER",
        "schema_version":"executive_route_resolution_v9.5.33",
    }
    report["action"]=Action.NO_SETUP.value
    report["execution_router_deferred"]=True

    decision.action=Action.NO_SETUP.value
    decision.reason=f"EXECUTIVE ROUTE {tactic}: setup remains active; bounded execution wait <= {EXECUTION_ROUTER_MAX_WAIT_MINUTES}m"
    ed=decision.audit.setdefault("executive_director",{})
    ed["final_action"]=decision.action
    ed["statement"]="Only Executive Decision Layer can publish or defer trading actions; Router is advisory route intelligence"
    funnel=decision.audit.get("execution_funnel")
    if isinstance(funnel,dict):
        funnel["entry_published"]=False
        funnel["blocking_layer"]="EXECUTION_ROUTER_TACTIC"
    xi=decision.audit.setdefault("execution_intelligence_v9532",{})
    xi["routed_from_action"]=original
    xi["setup_blocked"]=False
    xi["route_applied_by"]="EXECUTIVE_DECISION_LAYER"
    return DECISION_AUTHORITY_GUARD.approve_executive_decision(decision)


def evaluate_new_setup(context: dict, state: dict, journal: dict) -> Decision:
    # v9.5.33 release hardening: fail closed before any detector arithmetic if
    # the execution price is missing/invalid. run_bot() already blocks this, but
    # the final authority boundary must remain safe when called independently
    # (tests, replay tooling, future integrations).
    price = safe_float(context.get("price"), 0.0)
    if price <= 0.0 or not math.isfinite(price):
        return Decision(
            id=uuid.uuid4().hex[:10], time=iso_now(), action=Action.NO_SETUP.value,
            side=Side.NEUTRAL.value, setup_type=SetupType.NONE.value, quality=0,
            reason="MARKET_DATA_UNAVAILABLE: invalid or missing execution price",
            regime=str(context.get("regime") or Regime.NORMAL.value),
            candidate=None, plan=None, current_price=0.0,
            audit={
                "market_data_guard": {
                    "valid_price": False,
                    "execution_price_trusted": bool(context.get("execution_price_trusted", False)),
                    "price_source": str(context.get("price_source") or "NONE"),
                    "fail_closed": True,
                    "authority": "EXECUTIVE_DECISION_BOUNDARY",
                    "schema_version": "market_data_guard_v9.5.33",
                }
            },
        )
    resolve_opportunity_outcome_matrix_v9532(journal,context)
    decision=_evaluate_new_setup_v9531(context,state,journal)
    rejected_added=record_rejected_opportunity_events_v9532(journal,context,decision)
    if rejected_added:
        decision.audit.setdefault("execution_intelligence_v9532",{})["rejected_hypotheses_merged_into_counterfactual_matrix"]=rejected_added
    cand=decision.candidate
    if cand is None:
        return decision

    intel=build_execution_intelligence_v9532(context,cand,journal,decision.plan)
    cand.score_components=cand.score_components or {}
    cand.score_components["execution_intelligence_v9532"]=intel
    cand.stage_plan=cand.stage_plan or {}
    cand.stage_plan["execution_intelligence_v9532"]=compact_execution_intelligence_v9532(intel)

    router=intel.get("execution_router") or {}
    tactic=str(router.get("action") or "MARKET_NOW")
    draft_action=str(decision.action)
    if decision.action in EXECUTABLE_ENTRY_ACTIONS and tactic=="MARKET_NOW":
        _apply_route_tactic_geometry_v9532(decision.plan,cand,intel.get("route_geometry") or {})

    decision.audit.setdefault("execution_intelligence_v9532",{})["summary"]=compact_execution_intelligence_v9532(intel)
    decision.audit["execution_intelligence_v9532"]["assistants"]=intel.get("assistants")
    decision.audit["execution_intelligence_v9532"]["router"]=router

    # Router remains advisory. Executive owns the final route defer/publish.
    decision=executive_route_resolution_v9533(decision,tactic)
    # Record the FINAL published action, while preserving the Executive draft for
    # counterfactual interpretation. This prevents deferred routes being mislabeled
    # as live entries in the learning matrix.
    record_opportunity_outcome_event_v9532(
        journal,context,cand,decision.plan,intel,decision.action,
        draft_action_before_route=draft_action,
    )
    return decision


# ---------------- Management: path-decay defense after positive excursion ----------------
def _active_path_integrity_v9532(trade: ActiveTrade, context: dict[str,Any]) -> float:
    q=_v9532_recent_confirmed(context,"3m",7)
    if len(q)<4:return 50.0
    sign=side_sign(trade.side); atr=max(safe_float(context.get("atr15"),0.0),1e-9); closes=[safe_float(c.close) for c in q]
    net=sign*(closes[-1]-closes[0])/atr; path=sum(abs(closes[i]-closes[i-1]) for i in range(1,len(closes)))/atr; eff=clamp(max(0.0,net)/max(path,.05),0,1); dirs=sum(1 for c in q if sign*(safe_float(c.close)-safe_float(c.open))>0)/len(q)
    return clamp(55.0*eff+45.0*dirs,0.0,100.0)

_manage_active_trade_v9531 = manage_active_trade
def manage_active_trade(trade: ActiveTrade, context: dict) -> dict:
    result=_manage_active_trade_v9531(trade,context)
    if result.get("closed") or not PATH_DECAY_DEFENSE_ENABLED:return result
