_save_journal_v9531 = save_journal
def save_journal(journal: dict) -> None:
    # Link compact entry intelligence into newly closed trades before the canonical compactor runs.
    sig={str(s.get("id") or ""):s for s in (journal.get("signals") or []) if isinstance(s,dict)}
    for t in (journal.get("trades") or []):
        if not isinstance(t,dict) or t.get("execution_intelligence"): continue
        s=sig.get(str(t.get("signal_id") or ""))
        if isinstance(s,dict) and s.get("execution_intelligence"): t["execution_intelligence"]=dict(s.get("execution_intelligence") or {})
    refresh_loss_attribution_v9532(journal); journal.setdefault("analytics",{})["v9532_journal_budget"]=v9532_journal_budget_compaction(journal)
    return _save_journal_v9531(journal)


