def router_reentry_tactic_readiness_v9533(opp: Opportunity, context: dict[str,Any]) -> dict[str,Any]:
    """Validate the saved Router tactic with post-decision market evidence.

    This function can only make a saved re-entry *less* executable than the
    native re-entry detector. It never creates a trigger that the underlying
    setup did not already have, so old setup contracts remain authoritative.
    """
    tactic=str(getattr(opp,"execution_tactic","") or "")
    if tactic not in EXECUTION_ROUTER_ACTIONS or tactic=="MARKET_NOW":
        return {"applicable":False,"ready":True,"tactic":tactic or "UNSPECIFIED","reason":"NO_DEFERRED_ROUTER_TACTIC","schema_version":"router_reentry_tactic_v9.5.33"}
    price=safe_float(context.get("price"),0.0)
    atr=max(safe_float(context.get("atr15"),0.0),price*0.001,1e-6)
    anchor=safe_float(getattr(opp,"trigger_level",0.0),price)
    created=_parse_time_any(getattr(opp,"created_at","") or "")
    created_ts=int(created.timestamp()*1000) if created else 0
    bars=[c for c in _v9532_recent_confirmed(context,"3m",20) if int(getattr(c,"ts",0) or 0)>created_ts]
    sign=side_sign(str(getattr(opp,"side",Side.NEUTRAL.value) or Side.NEUTRAL.value))
    kind=str((SETUP_STATE_MACHINE_REGISTRY.get(str(getattr(opp,"setup_type","") or "")) or {}).get("kind") or "CONTINUATION")
    dist=abs(price-anchor)/atr if anchor>0 and price>0 else 99.0

    ready=False
    reason="WAITING_POST_DECISION_EVIDENCE"
    evidence_ts=0
    entry_override=0.0
    if tactic=="LIMIT_AT_ANCHOR":
        # This is a signal bot, not an exchange-hosted resting limit order. Never
        # claim a retrospective anchor fill. Publish only when the *current*
        # trusted market price is already inside a tight anchor zone, and journal
        # that current price as the actual execution reference.
        ready=bool(anchor>0 and price>0 and dist<=EXECUTION_ROUTER_LIMIT_LIVE_TOLERANCE_ATR)
        reason="CURRENT_PRICE_REACHED_LIMIT_ANCHOR_ZONE" if ready else "WAIT_CURRENT_PRICE_AT_LIMIT_ANCHOR"
        entry_override=price if ready else 0.0
        evidence_ts=int(bars[-1].ts) if bars else 0
    elif tactic=="FIRST_RETEST":
        touch=None
        for i,c in enumerate(bars):
            if safe_float(c.low)<=anchor<=safe_float(c.high):
                touch=i; break
        confirm=None
        if touch is not None:
            for j in range(touch+1,min(len(bars),touch+4)):
                c=bars[j]
                body=sign*(safe_float(c.close)-safe_float(c.open))
                held=sign*(safe_float(c.close)-anchor)>=-0.02*atr
                if body>=0.04*atr and held:
                    confirm=j; break
        ready=bool(confirm is not None and dist<=0.60)
        reason="POST_DECISION_RETEST_AND_HOLD_CONFIRMED" if ready else "WAIT_POST_DECISION_RETEST_AND_HOLD"
        evidence_ts=int(bars[confirm].ts) if confirm is not None else 0
    elif tactic=="ONE_3M_CONFIRM":
        confirm=None
        if kind in {"REVERSAL","AUCTION_MEAN"}:
            for i in range(max(0,len(bars)-6),len(bars)-1):
                c,n=bars[i],bars[i+1]
                body=sign*(safe_float(c.close)-safe_float(c.open))
                follow=sign*(safe_float(n.close)-safe_float(c.close))
                holds=(anchor<=0) or sign*(safe_float(n.close)-anchor)>=-0.05*atr
                if body>=0.08*atr and follow>=0.02*atr and holds:
                    confirm=i+1; break
        else:
            for i in range(max(1,len(bars)-6),len(bars)):
                c,prev=bars[i],bars[i-1]
                body=sign*(safe_float(c.close)-safe_float(c.open))
                broke=(safe_float(c.close)>safe_float(prev.high)+0.01*atr) if sign>0 else (safe_float(c.close)<safe_float(prev.low)-0.01*atr)
                if body>=0.08*atr and broke:
                    confirm=i; break
        ready=bool(confirm is not None and dist<=0.75)
        reason="POST_DECISION_SETUP_AWARE_3M_CONFIRM" if ready else "WAIT_POST_DECISION_SETUP_AWARE_3M_CONFIRM"
        evidence_ts=int(bars[confirm].ts) if confirm is not None else 0
    return {
        "applicable":True,"ready":ready,"tactic":tactic,"reason":reason,
        "post_decision_bars":len(bars),"evidence_ts":evidence_ts,
        "distance_to_anchor_atr":round(dist,4),"entry_price_override":round_price(entry_override) if entry_override else 0.0,
        "native_trigger_still_required":True,"setup_blocked":False,
        "schema_version":"router_reentry_tactic_v9.5.33_causal",
    }


# Router waiting is deliberately short-lived. A stale saved WAIT_RETEST/WAIT_CONFIRMATION
# opportunity cannot survive for hours merely because the generic Opportunity TTL is longer.
_candidate_from_missed_opportunity_v9531 = candidate_from_missed_opportunity
def candidate_from_missed_opportunity(opp: Opportunity, context: dict) -> Optional[Candidate]:
    lane=str(getattr(opp,"execution_lane","") or "")
    if lane in {ExecutionLane.WAIT_RETEST.value,ExecutionLane.WAIT_CONFIRMATION.value}:
        created=_parse_time_any(getattr(opp,"created_at",None)); age=(now_utc()-created).total_seconds()/60.0 if created else 1e9
        if age>EXECUTION_ROUTER_MAX_WAIT_MINUTES:
            return None
    cand=_candidate_from_missed_opportunity_v9531(opp,context)
    if cand is not None:
        intended=str(getattr(opp,"execution_tactic","") or "")
        if intended in EXECUTION_ROUTER_ACTIONS:
            cand.stage_plan=cand.stage_plan or {}
            cand.stage_plan["router_intended_tactic"]=intended
            cand.score_components=cand.score_components or {}
            tactic_state=router_reentry_tactic_readiness_v9533(opp,context)
            native_ready=bool(cand.trigger_ready and cand.execution_source!=ExecutionSource.NONE.value)
            tactic_ready=bool(tactic_state.get("ready"))
            overall_ready=bool(native_ready and tactic_ready)
            cand.score_components["router_reentry_lineage"]={
                "intended_tactic":intended,
                "bounded_wait_minutes":EXECUTION_ROUTER_MAX_WAIT_MINUTES,
                "native_setup_trigger_ready":native_ready,
                "tactic_state":tactic_state,
                "overall_ready":overall_ready,
                "schema_version":"router_reentry_lineage_v9.5.33_causal",
            }
            cand.stage_plan["router_tactic_state"]=tactic_state
            if overall_ready:
                if intended=="LIMIT_AT_ANCHOR" and safe_float(tactic_state.get("entry_price_override"),0.0)>0:
                    cand.stage_plan["route_entry_price_override"]=safe_float(tactic_state.get("entry_price_override"),0.0)
            else:
                cand.trigger_ready=False
                cand.live_3m_trigger_ready=False
                cand.reentry_ready=False
                cand.execution_source=ExecutionSource.NONE.value
                cand.stage=OpportunityStage.ARMED.value
                cand.confirmation_pending=True
                cand.entry_stage=EntryStage.WAIT_CONFIRMATION.value if intended=="ONE_3M_CONFIRM" else EntryStage.WAIT_RETEST.value
                cand.execution_lane=ExecutionLane.WAIT_CONFIRMATION.value if intended=="ONE_3M_CONFIRM" else ExecutionLane.WAIT_RETEST.value
                cand.stage_plan["stage"]=cand.entry_stage
                cand.stage_plan["base_risk_pct"]=0.0
                cand.stage_plan["required_next_event"]=str(tactic_state.get("reason") or "ROUTER_TACTIC_EVIDENCE")
    return cand


_validate_runtime_configuration_v9531 = validate_runtime_configuration
def validate_runtime_configuration() -> dict[str,Any]:
    report=_validate_runtime_configuration_v9531(); errors=list(report.get("errors") or [])
    if set(SETUP_STATE_MACHINE_REGISTRY)!=set(_tracked_setup_types()): errors.append("v9.5.32 state-machine registry must cover exactly all 24 named setups")
    if not (6<=EXECUTION_ROUTER_MAX_WAIT_MINUTES<=18): errors.append("Execution Router wait must remain bounded to 6..18 minutes")
    if not (0.01<=EXECUTION_ROUTER_LIMIT_LIVE_TOLERANCE_ATR<=0.08): errors.append("Execution Router live limit-anchor tolerance must remain in 0.01..0.08 ATR")
    if not (48<=OPPORTUNITY_OUTCOME_MATRIX_LIMIT<=140): errors.append("Opportunity outcome matrix retention outside bounded journal budget")
    if not (0.52<=OUTCOME_MODEL_MIN_AUC<=0.80 and 0.15<=OUTCOME_MODEL_MAX_BRIER<=0.40): errors.append("Outcome ML validation gates invalid")
    if MIN_RR1<1.50: errors.append("v9.5.32 dynamic geometry may not lower professional MIN_RR1")
    return {"valid":not errors,"errors":errors}





